// Rock silhouettes.
//
// Every hazard used to be the same `IcosahedronGeometry(1, 0)` at the same identity
// rotation, so a field of rocks was a field of clones — the first thing anyone noticed
// when the game was finally flown. This builds a small set of distinct, lumpy solids
// once at load.
//
// Two constraints shape the approach:
//
//   * Variety must not cost draw calls. Hazards are drawn as `InstancedMesh`, one per
//     geometry, so the number of variants is the number of draw calls for the whole
//     field. A handful is free; per-rock geometry is not.
//   * The jitter must be baked, not per-instance. A vertex displaced at build time
//     costs nothing at runtime; displacing per instance would mean per-instance
//     geometry, which is exactly what instancing exists to avoid.
//
// The jitter uses its own seeded RNG rather than `Math.random`. Nothing in `view` is
// bound by the simulation's determinism rules, but a rock that looked different on
// every page load would make screenshot comparison useless and bug reports unrepeatable.
//
// ── Two scales of displacement, because one was the problem ──────────────────
//
// The first version displaced every vertex independently along its own normal. That is
// noise at exactly ONE frequency — the edge length of the mesh — and the result is a
// sphere with a rough surface rather than a rock: the silhouette stays circular however
// much you turn the jitter up, and past about 0.2 it stops reading as "lumpy" and
// starts reading as "shattered crystal".
//
// What makes a body read as a rock is the LOW frequency: a few broad lobes and hollows
// that break the outline, with the fine facet noise on top of them. So displacement
// here is the sum of a handful of smooth lobes (a cosine falloff around random
// directions, some positive and some negative) plus a small per-vertex term.

import { IcosahedronGeometry, Vector3, type BufferGeometry } from "three";
import { Rng } from "@core/rng.js";
import { directionFromUniforms } from "./sampling.js";

/**
 * Fine per-vertex roughness, as a fraction of the radius.
 *
 * Small now that the lobes carry the shape: this is surface texture, and the flat
 * shading turns even a little of it into visible facets.
 */
const GRAIN = 0.05;

/** How many broad lobes and hollows each rock gets. */
const LOBES = { min: 3, max: 6 };

/** How far a lobe pushes the surface, as a fraction of the radius. */
const LOBE_DEPTH = { min: 0.12, max: 0.3 };

/**
 * Angular width of a lobe's falloff, in radians.
 *
 * Wide enough to cover several faces — a lobe narrower than the mesh's edge length is
 * indistinguishable from the per-vertex grain, which is the trap that makes "add some
 * lobes" quietly do nothing at detail 0.
 */
const LOBE_WIDTH = { min: 0.9, max: 1.8 };

/**
 * The radius a rock is built at, before its lobes.
 *
 * Below 1 on purpose, and this is the constant that decides whether the lobes do
 * anything at all. `HazardDef.radius` is the collision sphere and the renderer draws at
 * that radius, so the geometry is clamped to 1 — and when the base was also 1, every
 * BULGE was clipped flat while the hollows showed. The result was a sphere with dents,
 * which at detail 0 is unmistakably an icosahedron with dents.
 *
 * Building at 0.85 gives the bulges 0.15 of headroom to grow into before the clamp,
 * so a rock's outline is made of both.
 */
const BASE_SCALE = 0.85;

/**
 * Ceiling on the total displacement.
 *
 * Geometry beyond 1 is geometry a shot can pass through, so the drawn body may reach
 * the collision sphere and never exceed it. Erring on the small side is deliberate: a
 * rock drawn slightly inside its hitbox makes a marginal shot connect when it looked
 * like it missed, which reads as generous — the opposite reads as broken.
 *
 * Overlapping lobes can sum, so the clamp is on the ACCUMULATED scale rather than on
 * each term. That failure would be rare, shape-dependent, and impossible to spot by
 * looking at the constants.
 */
const MAX_SCALE = 1;

/**
 * Floor, for the same reason in the other direction: two hollows meeting could pinch a
 * vertex through the origin and turn the solid inside out.
 */
const MIN_SCALE = 0.5;

interface Lobe {
  readonly direction: Vector3;
  /** Signed: positive is a bulge, negative a hollow. */
  readonly depth: number;
  readonly width: number;
}

/**
 * Builds `count` lumpy unit-radius rocks.
 *
 * Subdivision alternates: a subdivided icosahedron has more, smaller facets and reads
 * as a different KIND of rock rather than the same rock re-jittered, which is what
 * makes a handful of variants feel like more than a handful.
 */
export function createRockGeometries(count: number, seed = 0x5eed): BufferGeometry[] {
  const rng = new Rng(seed);
  const geometries: BufferGeometry[] = [];
  const vertex = new Vector3();

  for (let i = 0; i < count; i++) {
    // Detail 1 and 2 alternating, never 0. A detail-0 icosahedron has twelve vertices
    // and twenty faces, which is not enough surface for a lobe to be expressed on: it
    // reads as a twenty-sided die whatever is done to it, and that is exactly what the
    // first version of this looked like. Detail 1 is 80 faces — still frankly faceted,
    // which suits the rest of the art, but faceted like broken stone.
    const geometry = new IcosahedronGeometry(1, 1 + (i % 2));
    const positions = geometry.getAttribute("position");

    const lobes: Lobe[] = [];
    const lobeCount = LOBES.min + Math.floor(rng.range(0, LOBES.max + 1 - LOBES.min));
    for (let l = 0; l < lobeCount; l++) {
      // Four draws per lobe whatever happens: this shares `rng` with the vertex grain
      // below, so a conditional draw would shift every later rock's surface. The same
      // fixed-draw discipline the simulation follows, for a different reason — here it
      // is repeatability of a screenshot rather than of a run.
      const direction = directionFromUniforms(rng.float(), rng.float(), new Vector3());
      const depth = rng.range(LOBE_DEPTH.min, LOBE_DEPTH.max);
      const width = rng.range(LOBE_WIDTH.min, LOBE_WIDTH.max);
      // Alternating sign rather than a random one, so a rock cannot draw five bulges
      // and no hollows and come out a sphere again.
      lobes.push({ direction, depth: l % 2 === 0 ? depth : -depth, width });
    }

    // Displace along each vertex's own normal — which, on a unit-radius solid centred
    // at the origin, is the vertex direction itself. Scaling rather than adding keeps
    // the displacement radial and stops a big one from turning the solid inside out.
    for (let v = 0; v < positions.count; v++) {
      vertex.set(positions.getX(v), positions.getY(v), positions.getZ(v));
      const direction = vertex.clone().normalize();

      let scale = BASE_SCALE + rng.range(-GRAIN, GRAIN);
      for (const lobe of lobes) {
        // Angular distance to the lobe's centre, and a raised-cosine falloff over its
        // width. Smooth to zero at the edge, so lobes blend instead of leaving a seam.
        const angle = Math.acos(Math.min(1, Math.max(-1, direction.dot(lobe.direction))));
        if (angle >= lobe.width) continue;
        const falloff = 0.5 * (1 + Math.cos((angle / lobe.width) * Math.PI));
        scale += lobe.depth * falloff;
      }

      scale = Math.min(MAX_SCALE, Math.max(MIN_SCALE, scale));
      positions.setXYZ(v, direction.x * scale, direction.y * scale, direction.z * scale);
    }

    positions.needsUpdate = true;
    // Flat shading reads the face normals, so they have to be rebuilt after moving
    // vertices or the lighting still describes the sphere this used to be.
    geometry.computeVertexNormals();
    geometries.push(geometry);
  }

  return geometries;
}
