// Fixed-timestep clock.
//
// The single most consequential difference from the previous engine, which fed a
// raw `performance.now()` delta straight into its physics. A variable timestep means
// the same inputs produce different outcomes on different machines and different
// frames, which rules out replay tests, client-side prediction, and rollback all at
// once. Here `dt` is a constant; the renderer absorbs frame-rate variation by
// interpolating between the last two simulated states (see `alpha`).

export interface FixedStepOptions {
  /** Simulation frequency. 60 Hz unless there is a strong reason otherwise. */
  hz?: number;
  /**
   * Upper bound on ticks run for a single frame. When the tab is backgrounded or
   * the machine stalls, the accumulator can build up seconds of debt; running all
   * of it would take longer than a frame and build more debt — the "spiral of
   * death". Past this bound we drop the surplus time instead.
   */
  maxTicksPerFrame?: number;
}

export class FixedStepClock {
  /** Seconds per tick. Constant for the lifetime of the clock. */
  readonly dt: number;
  readonly hz: number;
  private readonly maxTicksPerFrame: number;

  /** Ticks simulated since the clock was created or reset. The sim's only clock. */
  tick = 0;

  private accumulator = 0;
  /** Ticks discarded to avoid a death spiral. Worth surfacing in a debug HUD. */
  droppedTicks = 0;

  constructor({ hz = 60, maxTicksPerFrame = 5 }: FixedStepOptions = {}) {
    this.hz = hz;
    this.dt = 1 / hz;
    this.maxTicksPerFrame = maxTicksPerFrame;
  }

  /**
   * Feeds a wall-clock frame delta (in SECONDS) and returns how many simulation
   * ticks the caller should run now. The clock's `tick` counter is advanced by that
   * many, so the caller's loop body is simply "simulate one tick".
   *
   *   for (let i = 0, n = clock.advance(delta); i < n; i++) simulate(world, clock.dt);
   *   render(world, clock.alpha);
   */
  advance(frameDelta: number): number {
    if (!Number.isFinite(frameDelta) || frameDelta <= 0) return 0;

    this.accumulator += frameDelta;

    let steps = Math.floor(this.accumulator / this.dt);
    if (steps > this.maxTicksPerFrame) {
      this.droppedTicks += steps - this.maxTicksPerFrame;
      // Discard the surplus rather than carrying debt into the next frame.
      this.accumulator -= (steps - this.maxTicksPerFrame) * this.dt;
      steps = this.maxTicksPerFrame;
    }

    this.accumulator -= steps * this.dt;
    this.tick += steps;
    return steps;
  }

  /**
   * How far the renderer sits between the previous tick and the current one, in
   * [0, 1). Render at `lerp(stateAt(tick - 1), stateAt(tick), alpha)` — without
   * this a 60 Hz simulation visibly stutters on a 144 Hz display.
   */
  get alpha(): number {
    return this.accumulator / this.dt;
  }

  /** Seconds of simulated time elapsed. Derived from ticks, never from the clock. */
  get elapsed(): number {
    return this.tick * this.dt;
  }

  reset(tick = 0): void {
    this.tick = tick;
    this.accumulator = 0;
    this.droppedTicks = 0;
  }
}

/** Converts a duration in seconds to a whole number of ticks at `hz`. */
export const secondsToTicks = (seconds: number, hz = 60): number => Math.round(seconds * hz);

/** Converts ticks back to seconds. */
export const ticksToSeconds = (ticks: number, hz = 60): number => ticks / hz;
