// The puff of shards a rock leaves when it breaks.
//
// Splitting already worked and already looked deliberate — the pieces scatter on a
// sphere and inherit the parent's motion (`sim/split.ts`). What it lacked is the thing
// that makes a break-up read as a break-up rather than as a substitution: for one
// frame, the big rock is replaced by smaller rocks and NOTHING ELSE happens. Real
// fragmentation throws off far more material than it leaves in countable pieces.
//
// So this adds the material that is not worth simulating: a few dozen chips that fly
// out, tumble, shrink and vanish. They are cosmetic in the strict sense — nothing can
// be shot, nothing collides, and a client that never drew one has the same world as a
// client that drew a hundred.
//
// ── Why it lives in `view` and costs the simulation nothing ──────────────────
//
// Debris as entities would mean components, culling, and a snapshot column, for objects
// that exist for half a second and can never affect an outcome. It would also put a
// per-shard RNG draw inside the determinism boundary, which is exactly the trap
// `sim/split.ts` documents at length. Here the pool is a fixed ring buffer, so a busy
// frame overwrites the oldest chip rather than allocating, and the worst case is bounded
// at one draw call.
//
// The clock is the SIM's, `(tick + alpha) / hz`, not a wall clock: a paused or slowed
// tab then shows the debris at the age the simulation says it has, and the same frame
// drawn twice looks the same both times.

import {
  Color,
  DynamicDrawUsage,
  InstancedBufferAttribute,
  InstancedMesh,
  Matrix4,
  MeshBasicMaterial,
  Quaternion,
  Vector3,
  type BufferGeometry,
  type Scene,
} from "three";
import { Rng } from "@core/rng.js";
import { directionFromUniforms } from "./sampling.js";

/**
 * How many chips can be in the air at once.
 *
 * A cascade — a large rock into three mediums into six smalls — is the burst this has
 * to survive, and it is the one the player is looking straight at. 256 covers it with
 * room to spare at a cost of one instanced draw call.
 */
const MAX_SHARDS = 256;

/** Chips per burst, scaled by the rock's radius. A small rock is not a small explosion. */
const SHARDS_PER_RADIUS = 6;
const MIN_SHARDS = 6;
const MAX_PER_BURST = 22;

/**
 * How long a chip lives, in seconds.
 *
 * Long enough to be seen at the distance rocks are usually shot from, short enough that
 * the pieces are gone before the rail has carried the player past the wreck.
 */
const LIFETIME = 0.9;

/**
 * Outward speed range, world units per second.
 *
 * Slower than the pieces themselves (`HazardSplit.scatterSpeed` is 5–7), so the chips
 * read as the dust the break threw off rather than as more debris overtaking it.
 */
const SPEED = { min: 2, max: 7 };

/**
 * Chip size as a fraction of the parent's radius.
 *
 * The first pass used 0.06–0.16 and the burst was invisible at any distance you would
 * actually shoot a rock from — a few pixels, for a third of a second. Chunky reads as
 * fragments; small reads as nothing at all.
 */
const SIZE = { min: 0.18, max: 0.42 };

/**
 * Smallest a chip may be drawn, in world units.
 *
 * A floor rather than a bigger fraction, because the fraction is right for a large rock
 * and wrong for the small one — which is the rock most often destroyed, and whose burst
 * was a handful of two-pixel specks at the distance anyone shoots from.
 */
const MIN_CHIP = 0.16;

/**
 * How much brighter a chip is than the rock it came off, at birth.
 *
 * The interior of a broken body is a fresher face than its weathered outside, and
 * unlit geometry needs the help: without it the chips are the same value as the dark
 * side of the rock they left.
 */
const FRESH_FACE = 1.9;

/** How fast a chip tumbles, radians per second. Far faster than a rock — it was just hit. */
const SPIN = { min: 3, max: 9 };

const matrix = new Matrix4();
const position = new Vector3();
const direction = new Vector3();
const axis = new Vector3();
const rotation = new Quaternion();
const scale = new Vector3();
const colour = new Color();

export interface Debris {
  readonly mesh: InstancedMesh;
  /**
   * Throws a burst of chips from a point.
   *
   * `seconds` is the sim clock at the moment of the break, so a burst spawned from an
   * event that arrived mid-frame ages from when it HAPPENED rather than from when it
   * was drawn.
   */
  burst(x: number, y: number, z: number, radius: number, tint: Color, seconds: number): void;
  /** Advances and redraws every live chip. */
  update(seconds: number): void;
  /** How many chips are currently alive. Exposed for the debug surface and the spec. */
  activeCount(): number;
  /**
   * How many chips have been thrown since boot. Monotonic.
   *
   * `activeCount` cannot answer "did that break-up throw debris" from outside: the pool
   * is shared, and a burst that arrives while an earlier one is expiring can leave the
   * live count LOWER than it was a moment ago. A counter that only goes up says what
   * actually happened.
   */
  spawnedTotal(): number;
  dispose(): void;
}

export function createDebris(scene: Scene, geometry: BufferGeometry, seed = 0xdeb1): Debris {
  // Its own stream, never `Math.random`: bursts happen in event order, which is the
  // same on every client, so seeding makes the debris identical everywhere and a
  // screenshot repeatable. Nothing depends on that being true — this is the one place
  // in the codebase where determinism is a convenience rather than a requirement.
  const rng = new Rng(seed);

  // UNLIT, unlike the rocks. A chip is a handful of pixels at the distance a rock is
  // actually shot from, and a lit fragment turned away from the key light is black —
  // half of every burst would simply not be there. Unlit also means the fade can be
  // exact: the instance colour is the whole of what is drawn, so multiplying it by the
  // remaining life dims the chip out precisely rather than approximately.
  const material = new MeshBasicMaterial({ color: new Color(0xffffff) });
  const mesh = new InstancedMesh(geometry, material, MAX_SHARDS);
  mesh.instanceMatrix.setUsage(DynamicDrawUsage);
  mesh.instanceColor = new InstancedBufferAttribute(new Float32Array(MAX_SHARDS * 3), 3);
  mesh.instanceColor.setUsage(DynamicDrawUsage);
  mesh.frustumCulled = false;
  mesh.count = 0;
  scene.add(mesh);

  // Struct-of-arrays over a fixed pool, in the same spirit as the simulation's
  // component columns: no per-shard object, no allocation on the hot path, and a burst
  // during a cascade cannot make the renderer garbage-collect.
  const originX = new Float32Array(MAX_SHARDS);
  const originY = new Float32Array(MAX_SHARDS);
  const originZ = new Float32Array(MAX_SHARDS);
  const velocityX = new Float32Array(MAX_SHARDS);
  const velocityY = new Float32Array(MAX_SHARDS);
  const velocityZ = new Float32Array(MAX_SHARDS);
  const axisX = new Float32Array(MAX_SHARDS);
  const axisY = new Float32Array(MAX_SHARDS);
  const axisZ = new Float32Array(MAX_SHARDS);
  const spinRate = new Float32Array(MAX_SHARDS);
  const size = new Float32Array(MAX_SHARDS);
  const birth = new Float32Array(MAX_SHARDS);
  const tintR = new Float32Array(MAX_SHARDS);
  const tintG = new Float32Array(MAX_SHARDS);
  const tintB = new Float32Array(MAX_SHARDS);
  // Negative means the slot has never been used. A zero birth would otherwise read as
  // "spawned at tick 0", which is a real moment — the first frame of every run.
  birth.fill(-1);

  // Ring cursor. Overwriting the OLDEST chip is the right eviction: it is the one
  // closest to vanishing anyway, so a burst that overflows the pool costs the least
  // visible thing on screen.
  let next = 0;
  let alive = 0;
  let spawned = 0;

  return {
    mesh,

    burst(x, y, z, radius, tint, seconds) {
      const count = Math.min(
        MAX_PER_BURST,
        Math.max(MIN_SHARDS, Math.round(radius * SHARDS_PER_RADIUS)),
      );
      for (let i = 0; i < count; i++) {
        const slot = next;
        next = (next + 1) % MAX_SHARDS;

        // Uniform on the sphere — see `sampling.ts` for why the two-angles version
        // everyone writes first would throw most of a burst out of two poles.
        directionFromUniforms(rng.float(), rng.float(), direction);
        const speed = rng.range(SPEED.min, SPEED.max);

        // Started on the parent's SURFACE rather than at its centre, so the burst
        // reads as the shell coming apart rather than as something emerging from a
        // point inside it.
        originX[slot] = x + direction.x * radius * 0.6;
        originY[slot] = y + direction.y * radius * 0.6;
        originZ[slot] = z + direction.z * radius * 0.6;
        velocityX[slot] = direction.x * speed;
        velocityY[slot] = direction.y * speed;
        velocityZ[slot] = direction.z * speed;

        // A second, independent direction: a chip that tumbled about the axis it flew
        // along would roll rather than tumble, which is the one motion a fragment
        // knocked off something does not have.
        directionFromUniforms(rng.float(), rng.float(), direction);
        axisX[slot] = direction.x;
        axisY[slot] = direction.y;
        axisZ[slot] = direction.z;
        spinRate[slot] = rng.range(SPIN.min, SPIN.max);

        size[slot] = Math.max(MIN_CHIP, radius * rng.range(SIZE.min, SIZE.max));
        spawned++;
        birth[slot] = seconds;
        // The parent's own tint, so a burst belongs to the rock it came from rather
        // than being a generic grey puff over a brown asteroid.
        tintR[slot] = tint.r;
        tintG[slot] = tint.g;
        tintB[slot] = tint.b;
      }
    },

    update(seconds) {
      let drawn = 0;
      for (let slot = 0; slot < MAX_SHARDS; slot++) {
        const born = birth[slot]!;
        if (born < 0) continue;
        const age = seconds - born;
        // A chip is stale when it has lived its life — or when it was born so far in
        // the FUTURE that it must belong to a previous run: `restart()` puts the sim
        // clock back to zero, and chips from the old world would otherwise hang in the
        // new one until its clock caught up.
        //
        // The backward test is a LIFETIME rather than zero, and the difference is a real
        // bug rather than a nicety. The view's clock is `(tick + alpha) / hz`, and it is
        // not monotonic: when a stalled frame asks for more ticks than
        // `maxTicksPerFrame`, `FixedStepClock.advance` DISCARDS the surplus accumulator
        // (`core/loop.ts`) — so `tick` rises by the cap while `alpha` falls further, and
        // the interpolated clock can step backward by a fraction of a second. Against
        // `age < 0` that silently deleted every chip in the air, which meant a burst
        // vanished whenever the browser hitched: exactly the moment a player would blame
        // their GPU rather than this line. Found by the browser smoke, which started
        // reporting live=0 for a burst it had just thrown once the hull retune kept the
        // ship alive long enough for frames to get expensive.
        //
        // A restart is a jump of many seconds in any run long enough to have thrown a
        // chip, so a lifetime separates the two cases with room to spare; and the worst
        // a wrong guess costs either way is one puff of debris.
        if (age <= -LIFETIME || age >= LIFETIME) {
          birth[slot] = -1;
          continue;
        }

        const life = 1 - age / LIFETIME;
        position.set(
          originX[slot]! + velocityX[slot]! * age,
          originY[slot]! + velocityY[slot]! * age,
          originZ[slot]! + velocityZ[slot]! * age,
        );
        axis.set(axisX[slot]!, axisY[slot]!, axisZ[slot]!);
        rotation.setFromAxisAngle(axis, spinRate[slot]! * age);
        // Shrinks away rather than blinking out. `life²` rather than `life` so most of
        // the shrinking happens at the end — a chip that starts shrinking immediately
        // reads as flying towards you.
        const s = size[slot]! * life * life;
        scale.set(s, s, s);
        matrix.compose(position, rotation, scale);
        mesh.setMatrixAt(drawn, matrix);
        // Brighter than the parent and fading to nothing: freshly broken stone is a
        // lighter face than a weathered one, and the burst has to register against a
        // black sky in the third of a second anyone is looking at it.
        const glow = FRESH_FACE * life;
        colour.setRGB(
          Math.min(1, tintR[slot]! * glow),
          Math.min(1, tintG[slot]! * glow),
          Math.min(1, tintB[slot]! * glow),
        );
        mesh.setColorAt(drawn, colour);
        drawn++;
      }

      alive = drawn;
      mesh.count = drawn;
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    },

    activeCount: () => alive,
    spawnedTotal: () => spawned,

    dispose() {
      scene.remove(mesh);
      mesh.dispose();
      material.dispose();
      // The geometry is the rock bucket's and is disposed with it — disposing here
      // would leave the field drawing a freed buffer.
    },
  };
}
