// Committing the party to a course at a fork.
//
// The thirty lines that were missing. `buildRailNetwork`, `commitS`, `chooseCourse`
// and the selectors all landed in M1a step 2b and were specced thoroughly, and none of
// it was ever called: `world.courseId` was read by six systems and written by none. A
// level with a fork in it would have carried the party straight down course 0, and
// nothing would have looked broken.
//
// ── Why it runs after flight ─────────────────────────────────────────────────────
//
// `flightSystem` advances `railS`, so deciding before it would commit a tick late.
// Switching afterwards is safe precisely because of the commit rule: at `commitS` every
// course through the fork has identical geometry, so the position flight just wrote on
// the old course is the position the new course would have written. The next tick picks
// up on the new one with nothing to see.
//
// ── Why "resolved" is one float ──────────────────────────────────────────────────
//
// `commitS` ascends along a course and `railS` only ever increases, so a fork is
// already decided exactly when its commit point is at or behind `world.lastForkS`. No
// per-fork set, no ids to replicate — the party's whole rail state stays `courseId`,
// `railS`, and this. That matters: it is the reason a branching co-op run costs five
// bytes on the wire rather than a decision log.

import { chooseCourse, type SelectionContext } from "../rail.js";
import type { SimWorld } from "../world.js";

/**
 * Upper bound on forks committed in a single tick.
 *
 * Two forks whose commit points fall inside one tick of travel is pathological
 * authoring, but the loop re-reads `forksOn` after every switch — the fork list belongs
 * to the course — and an unbounded loop over a mutable list is not something to leave
 * to the level designer's judgement.
 */
const MAX_COMMITS_PER_TICK = 4;

export function forkSystem(world: SimWorld): void {
  const rail = world.rail;
  if (!rail) return;

  for (let guard = 0; guard < MAX_COMMITS_PER_TICK; guard++) {
    const fork = nextUnresolvedFork(world);
    if (!fork) return;

    const from = world.courseId;
    const chosen = chooseCourse(fork, selectionContext(world));

    // Recorded BEFORE the switch: `lastForkS` is what marks this fork resolved, and a
    // course change reorders nothing about it — every course through a fork agrees on
    // its commit point, which is the whole basis for the single-float bookkeeping.
    world.lastForkS = fork.commitS;
    world.courseId = chosen;

    world.events.push({
      type: "courseCommitted",
      forkKey: fork.key,
      fromCourse: from,
      toCourse: chosen,
      commitS: fork.commitS,
      tick: world.tick,
    });
  }
}

/** The first fork on the current course that is due and not yet decided. */
function nextUnresolvedFork(world: SimWorld) {
  const forks = world.rail!.forksOn(world.courseId);
  for (const fork of forks) {
    if (fork.commitS <= world.lastForkS) continue; // already decided
    if (fork.commitS > world.railS) return null; // not there yet; the list is sorted
    return fork;
  }
  return null;
}

/**
 * What the selectors get to look at.
 *
 * Explicit inputs rather than the world itself, so `chooseCourse` stays pure and the
 * host can evaluate it and replicate one integer. `partyLateral` is the MEAN box
 * offset across living ships — in co-op the whole party votes by flying, which is the
 * only selector that needs no authoring at all.
 *
 * EXPORTED for the debug rail readout, which previews which way a pending fork would
 * go if it committed this tick. That preview is worse than nothing if it disagrees with
 * the system — a second, subtly different copy of "what is the party's lateral" is
 * exactly the bug the readout exists to diagnose — so there is one definition and both
 * callers use it. It is a pure read either way.
 */
export function selectionContext(world: SimWorld): SelectionContext {
  const { boxOffset, ship } = world.components;

  let sum = 0;
  let count = 0;
  for (let slot = 0; slot < world.shipBySlot.length; slot++) {
    const entity = world.shipBySlot[slot];
    if (entity === undefined || !world.ecs.isAlive(entity)) continue;

    const s = ship.row(entity);
    const b = boxOffset.row(entity);
    // A downed player does not get a vote. Counting them would pull the mean toward
    // wherever they happened to die and hold it there for the rest of the run.
    if (s < 0 || b < 0 || ship.columns.health[s]! <= 0) continue;

    sum += boxOffset.columns.ox[b]!;
    count++;
  }

  return {
    partyLateral: count > 0 ? sum / count : 0,
    boxHalfWidth: world.rail!.box.width / 2,
    // Built here rather than kept as a Set on the world: the world stores a sorted
    // array so the fingerprint has a stable iteration order, and this runs only on the
    // handful of ticks where a fork actually commits.
    firedTriggers: new Set(world.firedTriggers),
  };
}
