// Collision.
//
// Runs AFTER motion, and tests projectiles as SWEPT SEGMENTS rather than points. At
// 120 units/second a bolt covers two units per tick while a hazard is 1.5 across, so
// a point test would let shots tunnel straight through — intermittently, depending on
// where the tick boundary happened to fall, which is the worst kind of bug to chase.
//
// The broadphase is a naive double loop. At M1a scale (a few hundred projectiles
// against a few dozen hazards) that is comfortably cheap, and a spatial index is an
// M2 concern once enemy counts grow. Written as an explicit loop rather than hidden
// behind a helper so the cost is visible when that day comes.
//
// ── Who can hurt whom ────────────────────────────────────────────────────────────
//
// A projectile carries a `faction`, and it is checked rather than assumed:
//
//   player shot  →  hazards, enemies
//   enemy shot   →  ships
//   enemy hull   →  ships (contact)
//   hazard       →  ships (contact, unchanged)
//   pickup       →  ships (collected, the one contact that helps)
//
// Two absences are deliberate. An enemy's shot does NOT destroy hazards: it would
// double the broadphase for a cosmetic gain, and it would let a player use a rock
// field as cover that the spawner makes no promise to provide. And an enemy's shot
// cannot hit another enemy — without the faction check, two drones firing past each
// other would shoot each other down while the player watched, which is the kind of
// "emergent" behaviour that reads as a bug.

import { clamp, Vec3 } from "@core/math/index.js";
import type { Entity } from "@core/ecs.js";
import { Faction } from "../faction.js";
import type { SimWorld } from "../world.js";

/**
 * Damage a ship takes from ramming a hazard.
 *
 * Still a constant, unlike the ship radius beside it: this is a property of hitting a
 * rock, not of the ship or of the rock. It becomes a `HazardDef` field when hazards
 * gain one worth authoring.
 */
const RAM_DAMAGE = 25;

const hazardPos = new Vec3();
const targetPos = new Vec3();
const shotPos = new Vec3();
const shotStart = new Vec3();
const segment = new Vec3();
const toHazard = new Vec3();
const shipPos = new Vec3();

/** Squared distance from `point` to the segment `start → end`. */
function distanceSqToSegment(point: Vec3, start: Vec3, end: Vec3): number {
  segment.copy(end).sub(start);
  const lengthSq = segment.lengthSq();
  toHazard.copy(point).sub(start);
  if (lengthSq < 1e-12) return toHazard.lengthSq();

  const t = clamp(toHazard.dot(segment) / lengthSq, 0, 1);
  return toHazard.addScaledVector(segment, -t).lengthSq();
}

export function collisionSystem(world: SimWorld): void {
  const { transform, motion, projectile, hazard, enemy, pickup, ship } = world.components;
  const dt = world.dt;

  // ── Projectiles ─────────────────────────────────────────────────────────────
  // Iterate backwards: a hit queues destruction, and while that is deferred, the
  // reverse walk keeps the loop correct even if that ever changes.
  for (let p = projectile.count - 1; p >= 0; p--) {
    const shot = projectile.dense[p]! as Entity;
    const t = transform.row(shot);
    const m = motion.row(shot);
    if (t < 0 || m < 0) continue;

    shotPos.readFrom(transform.columns.pos, t * 3);
    shotStart
      .readFrom(motion.columns.vel, m * 3)
      .multiplyScalar(-dt)
      .add(shotPos); // where it was at the start of this tick

    const damage = projectile.columns.damage[p]!;
    const ownerSlot = projectile.columns.ownerSlot[p]!;
    // Extra reach on the bolt itself, added to whatever it is testing against. Read
    // from the OWNER's resolved stats rather than stored per projectile: stats are
    // folded once at run start and cannot change mid-flight, so the lookup is exact
    // and the projectile schema — which every replay fingerprint folds in — does not
    // grow a column. Enemy shots have no owner slot and so no bonus, which is the
    // point: a wider enemy bolt would make an easier difficulty harder.
    const hitRadius = ownerSlot >= 0 ? world.statsFor(ownerSlot).weapon.hitRadius : 0;
    // A shot is spent on its first hit, whatever it hit and whether or not the target
    // died — otherwise one bolt would rake a whole cluster, which is not what "fire a
    // shot" means. Tracked as a flag rather than a `break`, because a player's shot
    // has two candidate target sets to walk.
    let spent = false;

    if (projectile.columns.faction[p] === Faction.Player) {
      for (let h = hazard.count - 1; h >= 0; h--) {
        const target = hazard.dense[h]! as Entity;
        const ht = transform.row(target);
        if (ht < 0) continue;

        hazardPos.readFrom(transform.columns.pos, ht * 3);
        const radius = hazard.columns.radius[h]! + hitRadius;
        if (distanceSqToSegment(hazardPos, shotStart, shotPos) > radius * radius) continue;

        const remaining = hazard.columns.health[h]! - damage;
        hazard.columns.health[h] = remaining;
        world.ecs.destroyLater(shot);
        if (remaining <= 0) world.destroyHazard(target, ownerSlot);
        spent = true;
        break;
      }

      for (let e = enemy.count - 1; !spent && e >= 0; e--) {
        const target = enemy.dense[e]! as Entity;
        const et = transform.row(target);
        if (et < 0) continue;

        targetPos.readFrom(transform.columns.pos, et * 3);
        const radius = enemy.columns.radius[e]! + hitRadius;
        if (distanceSqToSegment(targetPos, shotStart, shotPos) > radius * radius) continue;

        const remaining = enemy.columns.health[e]! - damage;
        enemy.columns.health[e] = remaining;
        world.ecs.destroyLater(shot);
        if (remaining <= 0) world.destroyEnemy(target, ownerSlot);
        spent = true;
      }
      continue;
    }

    // ── An enemy's shot: ships only ───────────────────────────────────────────
    // By slot, for the same reason every other party loop is: stable as players join
    // and leave, so a six-player run resolves the same way every time.
    for (let slot = 0; slot < world.shipBySlot.length && !spent; slot++) {
      const entity = world.shipBySlot[slot];
      if (entity === undefined || !world.ecs.isAlive(entity)) continue;

      const s = ship.row(entity);
      const st = transform.row(entity);
      if (s < 0 || st < 0 || ship.columns.health[s]! <= 0) continue;

      targetPos.readFrom(transform.columns.pos, st * 3);
      const hitRadius = world.statsFor(slot).radius;
      if (distanceSqToSegment(targetPos, shotStart, shotPos) > hitRadius * hitRadius) continue;

      world.damageShip(entity, damage);
      world.ecs.destroyLater(shot);
      spent = true;
    }
  }

  // ── Hazards against ships ───────────────────────────────────────────────────
  // By slot, not by dense row: both are deterministic, but slot order stays stable
  // as players join and leave, so a six-player run resolves the same way every time.
  for (let slot = 0; slot < world.shipBySlot.length; slot++) {
    const entity = world.shipBySlot[slot];
    if (entity === undefined || !world.ecs.isAlive(entity)) continue;

    const s = ship.row(entity);
    const t = transform.row(entity);
    if (s < 0 || t < 0 || ship.columns.health[s]! <= 0) continue;

    shipPos.readFrom(transform.columns.pos, t * 3);
    // Hoisted out of both inner loops: one lookup per ship rather than one per
    // candidate, and the value cannot change mid-tick — stats are folded at run start.
    const shipRadius = world.statsFor(slot).radius;

    for (let h = hazard.count - 1; h >= 0; h--) {
      const target = hazard.dense[h]! as Entity;
      const ht = transform.row(target);
      if (ht < 0) continue;

      hazardPos.readFrom(transform.columns.pos, ht * 3);
      const reach = hazard.columns.radius[h]! + shipRadius;
      if (hazardPos.distanceToSq(shipPos) > reach * reach) continue;

      world.damageShip(entity, RAM_DAMAGE);
      // The hazard is consumed, so a single rock cannot grind a ship down over
      // consecutive ticks while the two overlap.
      world.destroyHazard(target, -1);
    }

    // ── Pickups ───────────────────────────────────────────────────────────────
    // The one contact in this file that helps rather than hurts, and it runs AFTER the
    // two that hurt. That ordering is load-bearing rather than incidental: a ship the
    // hazard pass has just destroyed must not then collect a repair and come back.
    // `collectPickup` re-reads health for that reason and declines for a wreck, so the
    // guarantee does not rest on this loop staying where it is.
    for (let k = pickup.count - 1; k >= 0; k--) {
      const target = pickup.dense[k]! as Entity;
      const kt = transform.row(target);
      if (kt < 0) continue;

      targetPos.readFrom(transform.columns.pos, kt * 3);
      const reach = pickup.columns.radius[k]! + shipRadius;
      if (targetPos.distanceToSq(shipPos) > reach * reach) continue;

      world.collectPickup(target, entity, slot);
    }

    // ── Enemies against ships ─────────────────────────────────────────────────
    // Same rule, with the damage coming from the archetype rather than a constant:
    // flying into a lancer should cost more than clipping a drone. Consumed on
    // contact for the same reason a hazard is, and NOT credited as a kill — ramming
    // must not advance anything that counts kills.
    for (let e = enemy.count - 1; e >= 0; e--) {
      const target = enemy.dense[e]! as Entity;
      const et = transform.row(target);
      if (et < 0) continue;

      targetPos.readFrom(transform.columns.pos, et * 3);
      const reach = enemy.columns.radius[e]! + shipRadius;
      if (targetPos.distanceToSq(shipPos) > reach * reach) continue;

      const def = world.enemyCatalog[enemy.columns.defId[e]!];
      world.damageShip(entity, def?.contactDamage ?? RAM_DAMAGE);
      world.destroyEnemy(target, -1);
    }
  }
}
