// The aim reticle.
//
// A camera-facing ring sitting on the laser ray a fixed distance ahead. Two details
// carry over from the original because both are load-bearing for readability:
//
//   - It sits along `aimDir`, NOT along the nose. Shots go where the reticle is, so
//     the reticle must mark that and not where the ship happens to be pointing yet.
//   - It GROWS with the divergence between heading and aim. The lag while the ship
//     catches up reads as aim uncertainty rather than as the reticle drifting off.
//
// Billboarded after the camera is placed each frame, so it reads flat in every view.

import {
  Mesh,
  MeshBasicMaterial,
  RingGeometry,
  type PerspectiveCamera,
  type Scene,
} from "three";
import { RETICLE_DIST, RETICLE_GROW } from "@content/tuning/flight.js";
import type { FlightState } from "@sim/flight.js";
import { clamp, Vec3 } from "@core/math/index.js";

const at = new Vec3();

export interface Reticle {
  readonly mesh: Mesh;
  update(shipPosition: Vec3, flight: FlightState, camera: PerspectiveCamera): void;
  dispose(): void;
}

export function createReticle(scene: Scene): Reticle {
  const mesh = new Mesh(
    new RingGeometry(0.14, 0.22, 20),
    new MeshBasicMaterial({
      color: 0xff5a5a,
      transparent: true,
      opacity: 0.9,
      // Drawn on top so it stays readable against a dense asteroid field.
      depthTest: false,
      depthWrite: false,
    }),
  );
  mesh.renderOrder = 1000;
  mesh.frustumCulled = false;
  scene.add(mesh);

  return {
    mesh,

    update(shipPosition, flight, camera) {
      at.copy(shipPosition).addScaledVector(flight.aim, RETICLE_DIST);
      mesh.position.set(at.x, at.y, at.z);

      // Grow with heading↔aim divergence: a wide ring means the ship has not caught
      // up to where you are pointing yet.
      const divergence = Math.acos(clamp(flight.aim.dot(flight.head), -1, 1));
      const growth = 1 + divergence * RETICLE_GROW;
      mesh.scale.setScalar(growth);

      mesh.quaternion.copy(camera.quaternion);
      mesh.visible = true;
    },

    dispose() {
      mesh.geometry.dispose();
      (mesh.material as MeshBasicMaterial).dispose();
    },
  };
}
