// The hazard catalog.
//
// Authored in TypeScript rather than JSON for the same reason `levels/` is: the
// versioned-JSON pipeline with its migration chain is later M2 work, and moving this
// twice costs more than moving it once. What matters now is that the SHAPE is the
// authored shape — validated by `content/validation/hazard.ts`, consumed by `sim`
// through a def id, never hardcoded in a system.
//
// A three-tier rock, which is the whole point of the tiering being data: nothing in
// `sim` knows a rock has three sizes, and adding a fourth is an edit to this file.

import type { HazardCatalog, HazardDef } from "../schemas/hazard.js";

export const ROCK_SMALL: HazardDef = {
  id: "rock.small",
  radius: 0.7,
  health: 1,
  variants: 4,
};

export const ROCK_MEDIUM: HazardDef = {
  id: "rock.medium",
  radius: 1.4,
  health: 2,
  variants: 4,
  splitsInto: { def: ROCK_SMALL.id, count: 2, scatterSpeed: 7 },
};

export const ROCK_LARGE: HazardDef = {
  id: "rock.large",
  radius: 2.6,
  health: 4,
  variants: 3,
  // Three children rather than two: a large rock breaking into a pair reads as a
  // split, into a handful it reads as a break. Scatter is slower than the medium
  // tier's so the pieces stay roughly where the parent was for a beat.
  splitsInto: { def: ROCK_MEDIUM.id, count: 3, scatterSpeed: 5 },
};

export const HAZARDS: HazardCatalog = {
  [ROCK_SMALL.id]: ROCK_SMALL,
  [ROCK_MEDIUM.id]: ROCK_MEDIUM,
  [ROCK_LARGE.id]: ROCK_LARGE,
};

/**
 * The catalog as an ORDERED list. This order is the `defId` stored on every hazard
 * instance, so it is part of the wire format and part of every replay fingerprint:
 * appending is safe, reordering or removing is not. Same rule as component
 * registration order, for the same reason.
 */
export const HAZARD_ORDER: readonly HazardDef[] = [ROCK_SMALL, ROCK_MEDIUM, ROCK_LARGE];

/**
 * What the ambient spawner picks from, with relative weights.
 *
 * Weighted rather than uniform so the field is mostly small debris with the occasional
 * big one worth shooting, and expressed as a flat list of (def, weight) so the choice
 * costs exactly one RNG draw — a rejection loop here would reintroduce the variable
 * draw count the spawner was rebuilt to avoid.
 */
export const AMBIENT_ROCKS: readonly { readonly def: HazardDef; readonly weight: number }[] = [
  { def: ROCK_SMALL, weight: 5 },
  { def: ROCK_MEDIUM, weight: 3 },
  { def: ROCK_LARGE, weight: 2 },
];
