// Integrates velocity into position.
//
// Written against the raw component columns rather than through `Vec3`, because
// this touches every moving entity every tick and the vector wrapper would buy
// readability at the cost of the hottest loop in the simulation. Systems that run
// over a handful of ships should use `Vec3`; systems that run over hundreds of
// projectiles should look like this.

import type { Entity } from "@core/ecs.js";
import type { SimWorld } from "../world.js";

export function motionSystem(world: SimWorld): void {
  const { transform, motion } = world.components;
  const pos = transform.columns.pos;
  const vel = motion.columns.vel;
  const dt = world.dt;

  for (let row = 0; row < motion.count; row++) {
    const entity = motion.dense[row]! as Entity;
    const t = transform.row(entity);
    if (t < 0) continue; // velocity without a transform: nothing to integrate

    const p = t * 3;
    const v = row * 3;
    pos[p] = pos[p]! + vel[v]! * dt;
    pos[p + 1] = pos[p + 1]! + vel[v + 1]! * dt;
    pos[p + 2] = pos[p + 2]! + vel[v + 2]! * dt;
  }
}
