// The ship catalog.
//
// ⚠️ EVERY NUMBER HERE WAS THE VALUE THE SIMULATION ALREADY USED as a hardcoded
// constant, moved rather than retuned — that was the whole point of the step that
// created this file, and the evidence was that the golden replay hashes did not move.
//
// Where each came from:
//
//   maxHealth 100  `world.spawnShip` wrote a literal 100   ← SINCE RETUNED, see below
//   radius    1    `SHIP_RADIUS` in `systems/collision.ts`
//   boxSpeed  4    `BOX_MOVE` in `content/tuning/flight.ts`
//   aimRate   2    `AIM_RATE` in the same file
//
// ── The hull is 500 now, and that is a retune ────────────────────────────────
//
// The one number here that is no longer provenance. A rock hit costs 25, so 100 was
// four hits — and the thing that made that untenable was not the field but the RAIL:
// The Narrows commits its fork at rail distance 290, about twenty seconds in with the
// stop, and measured hands-off a ship died in 6.6-12.4 seconds. The first authored
// trigger fork in the game was unreachable for the ordinary reason that the run ended
// before the decision existed. Twenty hits is enough rail to reach it.
//
// It scales with difficulty like everything else (EASY 750, HARD 375) and it moved the
// golden replay hashes, which were re-recorded with a note. The debug HULL knob
// (0.25-20) multiplies from this base, so its floor is 125 rather than 25 — worth
// knowing, because that knob is how the browser smoke gets a run to END quickly.
//
// `BOX_MOVE` and `AIM_RATE` stay where they are and are IMPORTED here rather than
// copied. They are the flight model's tuning, hard-won and converted from the old
// engine's per-millisecond rates; duplicating the literals would mean a retune of the
// flight feel silently failing to reach the ship that flies it.

import { AIM_RATE, BOX_MOVE } from "../tuning/flight.js";
import type { ShipCatalog, ShipDef } from "../schemas/ship.js";
import { PULSE_LASER } from "../weapons/index.js";

export const SCOUT: ShipDef = {
  id: "ship.scout",
  maxHealth: 500,
  radius: 1,
  boxSpeed: BOX_MOVE,
  aimRate: AIM_RATE,
  weapon: PULSE_LASER.id,
};

export const SHIPS: ShipCatalog = {
  [SCOUT.id]: SCOUT,
};

/** What a player flies with no hull chosen. Becomes a loadout lookup with the save. */
export const DEFAULT_SHIP = SCOUT;
