// Hazards and projectiles, drawn as instanced meshes.
//
// One draw call per SHAPE rather than one per object. The old engine created a Mesh per
// asteroid and disposed it on death, which is both a draw-call per rock and steady
// GC pressure — neither survives six-player densities. Instance matrices are written
// straight from the interpolated simulation state each frame; nothing is allocated.
//
// Hazards are bucketed by `variant`, one `InstancedMesh` per rock shape. That keeps
// variety at a fixed handful of draw calls for the entire field however many rocks are
// alive, which is the whole reason variant is a small integer on the component rather
// than anything richer.
//
// Projectiles are bucketed by FACTION for the same cost: two meshes, two materials,
// and the player can tell at a glance which bolts are theirs. Getting that wrong is not
// a cosmetic problem in a game where the incoming ones do damage.

import {
  Color,
  InstancedBufferAttribute,
  ConeGeometry,
  DynamicDrawUsage,
  InstancedMesh,
  Matrix4,
  MeshStandardMaterial,
  OctahedronGeometry,
  Quaternion,
  SphereGeometry,
  Vector3,
  type Scene,
} from "three";
import { entityIndex, type Entity } from "@core/ecs.js";
import { Quat, Vec3 } from "@core/math/index.js";
import { Faction } from "@sim/faction.js";
import type { SimEvent } from "@sim/events.js";
import type { SimWorld } from "@sim/world.js";
import type { TransformInterpolator } from "./interpolation.js";
import { createRockGeometries } from "./rockGeometry.js";
import { silhouetteFor, tintFor, tumbleFor } from "./rockPose.js";
import { createDebris, type Debris } from "./debris.js";

/** Upper bound on simultaneously drawn instances, per bucket. Excess is not drawn. */
const MAX_PER_VARIANT = 256;
const MAX_PROJECTILES = 512;
const MAX_ENEMIES = 128;
const MAX_PICKUPS = 64;

/**
 * How many rock shapes exist.
 *
 * The ceiling across every `HazardDef.variants` in the catalog. A def asking for more
 * than this wraps rather than failing — a rock rendering as the wrong shape is a
 * cosmetic problem, and a crash in the renderer is not.
 */
const ROCK_VARIANTS = 6;

/**
 * How many entity indices the debris look-up remembers.
 *
 * Entity indices are dense and recycled, so this only has to cover how many entities
 * exist at once rather than how many a run creates. An index past the end simply gets
 * the default burst — a rock breaking is never worth a bounds crash.
 */
const MAX_TRACKED_ENTITIES = 4096;

const matrix = new Matrix4();
const position = new Vector3();
const rotation = new Quaternion();
const scale = new Vector3(1, 1, 1);
const sample = new Vec3();
const sampleRotation = new Quat();
// Rock pose scratch, kept beside the rest: `update` runs for every hazard every frame
// and must not allocate.
const rockScale = new Vector3(1, 1, 1);
const rockTint = new Color();

export interface Field {
  /** Every hazard bucket, one per variant. Exposed for the smoke's draw-call check. */
  readonly hazardMeshes: readonly InstancedMesh[];
  /** The player's bolts. */
  readonly projectiles: InstancedMesh;
  /** Incoming fire, drawn separately so it is distinguishable at a glance. */
  readonly hostileProjectiles: InstancedMesh;
  readonly enemies: InstancedMesh;
  readonly pickups: InstancedMesh;
  /** The cosmetic chips thrown by a break-up. */
  readonly debris: Debris;
  /**
   * Draws the field for one frame.
   *
   * `events` is the batch drained for THIS frame, and it is how a break-up becomes a
   * burst of debris. Passed in rather than drained here because the queue has one
   * consumer by design — the composition root — and a renderer that consumed events
   * would silently take them away from anything else that wanted them.
   */
  update(
    world: SimWorld,
    interpolator: TransformInterpolator,
    alpha: number,
    events?: readonly SimEvent[],
  ): void;
  dispose(): void;
}

export function createField(scene: Scene): Field {
  const rockGeometries = createRockGeometries(ROCK_VARIANTS);
  // One material shared across the buckets: they differ in shape, not in surface, and
  // sharing means one material to dispose and one shader to compile.
  // White, because the per-instance tint MULTIPLIES this: a coloured base would tint
  // the tint, and the palette in `rockPose.ts` would no longer be the palette on screen.
  const rockMaterial = new MeshStandardMaterial({
    color: new Color(0xffffff),
    flatShading: true,
    // Stone is not shiny. A little metalness keeps the lit faces from going chalky
    // white where the key light hits square on.
    roughness: 0.95,
    metalness: 0.06,
  });

  const hazardMeshes = rockGeometries.map((geometry) => {
    const mesh = new InstancedMesh(geometry, rockMaterial, MAX_PER_VARIANT);
    mesh.instanceMatrix.setUsage(DynamicDrawUsage);
    mesh.frustumCulled = false; // instance matrices move every frame
    // Allocates the per-instance colour attribute up front. Without this,
    // `setColorAt` allocates it on first use — mid-frame, on the first rock that
    // reaches the screen, for every bucket separately.
    mesh.instanceColor = new InstancedBufferAttribute(new Float32Array(MAX_PER_VARIANT * 3), 3);
    mesh.instanceColor.setUsage(DynamicDrawUsage);
    mesh.count = 0;
    scene.add(mesh);
    return mesh;
  });

  const boltGeometry = new SphereGeometry(0.22, 8, 6);
  const makeBolts = (color: number, emissive: number): InstancedMesh => {
    const mesh = new InstancedMesh(
      boltGeometry,
      new MeshStandardMaterial({ color: new Color(color), emissive: new Color(emissive) }),
      MAX_PROJECTILES,
    );
    mesh.instanceMatrix.setUsage(DynamicDrawUsage);
    mesh.frustumCulled = false;
    mesh.count = 0;
    scene.add(mesh);
    return mesh;
  };

  const projectiles = makeBolts(0xff5a5a, 0xff2020);
  // Green against the player's red. The two must not merely differ in brightness:
  // incoming fire is the thing you are meant to dodge, and telling it apart from your
  // own by shade alone fails the moment several of both are on screen.
  const hostileProjectiles = makeBolts(0x7dff8a, 0x18c02c);

  // Enemies: a cone nosed along local +X, matching the simulation's convention and the
  // player hull's, so the orientation quaternion the AI writes applies unmodified.
  const enemyGeometry = new ConeGeometry(0.7, 2.2, 6);
  enemyGeometry.rotateZ(-Math.PI / 2);
  const enemyMaterial = new MeshStandardMaterial({
    color: new Color(0xc25a2e),
    roughness: 0.5,
    metalness: 0.4,
    emissive: new Color(0x2a0a00),
  });
  const enemies = new InstancedMesh(enemyGeometry, enemyMaterial, MAX_ENEMIES);
  enemies.instanceMatrix.setUsage(DynamicDrawUsage);
  enemies.frustumCulled = false;
  enemies.count = 0;
  scene.add(enemies);

  // Pickups: an octahedron that spins on the spot. Motion is the whole read — a
  // stationary object the same size as everything else is scenery, and a pickup has
  // to look like something you would go out of your way for. Spun in the VIEW from
  // the tick count rather than stored, because it is cosmetic and every client
  // computes the same angle from state it already has.
  const pickupGeometry = new OctahedronGeometry(0.8, 0);
  const pickupMaterial = new MeshStandardMaterial({
    color: new Color(0x8fe9ff),
    emissive: new Color(0x1a6a80),
    roughness: 0.3,
    metalness: 0.6,
  });
  const pickups = new InstancedMesh(pickupGeometry, pickupMaterial, MAX_PICKUPS);
  pickups.instanceMatrix.setUsage(DynamicDrawUsage);
  pickups.frustumCulled = false;
  pickups.count = 0;
  scene.add(pickups);

  // Reused across frames so the per-bucket write loop allocates nothing.
  // Chips are drawn with the first rock shape at a fraction of its size: a fragment of
  // a rock IS a small rock, and reusing the geometry keeps this to one draw call and
  // one more buffer rather than a second silhouette to art-direct.
  const debris = createDebris(scene, rockGeometries[0]!);

  // What each live hazard looked like, so a destroy EVENT — which carries a position
  // but no size or colour — can throw a burst that matches the rock that just broke.
  // Indexed by entity index rather than a Map: this is written for every rock every
  // frame, and a Map would be the only allocation on the path.
  const lastRadius = new Float32Array(MAX_TRACKED_ENTITIES);
  const lastTint = new Float32Array(MAX_TRACKED_ENTITIES * 3);

  const bucketCounts = new Array<number>(hazardMeshes.length).fill(0);

  return {
    hazardMeshes,
    projectiles,
    hostileProjectiles,
    enemies,
    pickups,

    debris,

    update(world, interpolator, alpha, events) {
      const hazardStore = world.components.hazard;
      bucketCounts.fill(0);

      // The sim's clock, interpolated, rather than a wall clock: every client then
      // draws a rock at the same attitude, and a replay stopped at a checkpoint shows
      // the attitude that tick actually had. See the header of `rockPose.ts`.
      const seconds = (world.tick + alpha) / world.hz;

      for (let row = 0; row < hazardStore.count; row++) {
        const entity = hazardStore.dense[row]! as Entity;
        const bucket = hazardStore.columns.variant[row]! % hazardMeshes.length;
        const slot = bucketCounts[bucket]!;
        if (slot >= MAX_PER_VARIANT) continue;

        interpolator.position(world, entity, alpha, sample);
        position.set(sample.x, sample.y, sample.z);
        const r = hazardStore.columns.radius[row]!;
        // Squashed on two axes and never stretched, so the drawn body stays inside the
        // collision sphere the simulation uses — `rockPose.ts` has the argument.
        silhouetteFor(entity, rockScale);
        scale.set(r * rockScale.x, r * rockScale.y, r * rockScale.z);
        matrix.compose(position, tumbleFor(entity, r, seconds, rotation), scale);
        const mesh = hazardMeshes[bucket]!;
        mesh.setMatrixAt(slot, matrix);
        mesh.setColorAt(slot, tintFor(entity, rockTint));
        bucketCounts[bucket] = slot + 1;

        // Remembered while it is alive, because by the time its destruction is drained
        // the row is gone and the size and colour with it.
        const index = entityIndex(entity);
        if (index < MAX_TRACKED_ENTITIES) {
          lastRadius[index] = r;
          lastTint[index * 3] = rockTint.r;
          lastTint[index * 3 + 1] = rockTint.g;
          lastTint[index * 3 + 2] = rockTint.b;
        }
      }

      // Bursts are thrown from THIS frame's events, using the size and tint the rock
      // was last drawn at. A hazard destroyed before it was ever drawn — culled off
      // screen, or killed on its spawn tick — falls back to a default, which is the
      // right trade for a puff nobody is looking at.
      if (events) {
        for (const event of events) {
          if (event.type !== "hazardDestroyed") continue;
          const index = entityIndex(event.entity);
          const radius = index < MAX_TRACKED_ENTITIES ? lastRadius[index]! : 0;
          if (index < MAX_TRACKED_ENTITIES && radius > 0) {
            rockTint.setRGB(lastTint[index * 3]!, lastTint[index * 3 + 1]!, lastTint[index * 3 + 2]!);
          } else {
            rockTint.setRGB(0.55, 0.5, 0.44);
          }
          debris.burst(event.x, event.y, event.z, radius > 0 ? radius : 1, rockTint, seconds);
        }
      }
      debris.update(seconds);

      for (let i = 0; i < hazardMeshes.length; i++) {
        const mesh = hazardMeshes[i]!;
        mesh.count = bucketCounts[i]!;
        mesh.instanceMatrix.needsUpdate = true;
        // A rock leaving the field frees its slot to a different rock with a different
        // tint, so the colours are re-uploaded with the matrices rather than written
        // once at spawn.
        if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
      }

      // Enemies carry a real orientation — the AI writes it from the facing it aims
      // with — so unlike a rock's, theirs is read rather than derived. Seeing which
      // way a drone is pointing is how a player knows whether it is about to fire.
      const enemyStore = world.components.enemy;
      const enemyCount = Math.min(enemyStore.count, MAX_ENEMIES);
      scale.set(1, 1, 1);
      for (let row = 0; row < enemyCount; row++) {
        const entity = enemyStore.dense[row]! as Entity;
        interpolator.position(world, entity, alpha, sample);
        interpolator.rotation(world, entity, alpha, sampleRotation);
        position.set(sample.x, sample.y, sample.z);
        rotation.set(sampleRotation.x, sampleRotation.y, sampleRotation.z, sampleRotation.w);
        const r = enemyStore.columns.radius[row]!;
        scale.set(r, r, r);
        matrix.compose(position, rotation, scale);
        enemies.setMatrixAt(row, matrix);
      }
      enemies.count = enemyCount;
      enemies.instanceMatrix.needsUpdate = true;

      const pickupStore = world.components.pickup;
      const pickupCount = Math.min(pickupStore.count, MAX_PICKUPS);
      // One angle for all of them, from the tick: they spin in unison, which reads as
      // deliberate rather than as debris.
      const spin = (world.tick + alpha) * 0.04;
      rotation.set(0, Math.sin(spin), 0, Math.cos(spin));
      for (let row = 0; row < pickupCount; row++) {
        const entity = pickupStore.dense[row]! as Entity;
        interpolator.position(world, entity, alpha, sample);
        position.set(sample.x, sample.y, sample.z);
        const r = pickupStore.columns.radius[row]!;
        scale.set(r, r, r);
        matrix.compose(position, rotation, scale);
        pickups.setMatrixAt(row, matrix);
      }
      pickups.count = pickupCount;
      pickups.instanceMatrix.needsUpdate = true;

      // Projectiles are spheres: no variants, and orientation is invisible on one.
      // Split by faction, which means walking the store once and writing into whichever
      // bucket each row belongs to rather than filtering into a temporary.
      const projectileStore = world.components.projectile;
      rotation.identity();
      scale.set(1, 1, 1);
      let friendly = 0;
      let hostile = 0;
      for (let row = 0; row < projectileStore.count; row++) {
        const enemyOwned = projectileStore.columns.faction[row] === Faction.Enemy;
        const slot = enemyOwned ? hostile : friendly;
        if (slot >= MAX_PROJECTILES) continue;

        const entity = projectileStore.dense[row]! as Entity;
        interpolator.position(world, entity, alpha, sample);
        position.set(sample.x, sample.y, sample.z);
        matrix.compose(position, rotation, scale);
        (enemyOwned ? hostileProjectiles : projectiles).setMatrixAt(slot, matrix);
        if (enemyOwned) hostile = slot + 1;
        else friendly = slot + 1;
      }
      projectiles.count = friendly;
      projectiles.instanceMatrix.needsUpdate = true;
      hostileProjectiles.count = hostile;
      hostileProjectiles.instanceMatrix.needsUpdate = true;
    },

    dispose() {
      debris.dispose();
      for (const mesh of hazardMeshes) mesh.geometry.dispose();
      rockMaterial.dispose();
      boltGeometry.dispose();
      (projectiles.material as MeshStandardMaterial).dispose();
      (hostileProjectiles.material as MeshStandardMaterial).dispose();
      enemyGeometry.dispose();
      enemyMaterial.dispose();
      pickupGeometry.dispose();
      pickupMaterial.dispose();
    },
  };
}
