// Render interpolation.
//
// The simulation ticks at a fixed 60 Hz; displays do not. Without interpolation a
// 144 Hz monitor shows the same simulated position for two or three frames and then
// jumps, which reads as stutter even though the simulation is perfectly smooth.
// Rendering at `lerp(previousTick, currentTick, alpha)` fixes it.
//
// The subtlety is KEYING. Component rows move under swap-remove, so a row index is
// not a stable identity between ticks — the entity that was at row 3 last tick may be
// a different entity now. The snapshot is therefore keyed by entity INDEX, and each
// slot also records the entity's GENERATION. If the generation differs, the index was
// recycled and this is a different entity, so it snaps instead of interpolating.
// Without that guard a freshly spawned projectile would visibly streak in from
// wherever the previous occupant of its slot happened to die.

import { entityGeneration, entityIndex, type Entity } from "@core/ecs.js";
import { Quat, type Vec3 } from "@core/math/index.js";
import type { SimWorld } from "@sim/world.js";

const GROW_FACTOR = 2;

/**
 * Largest per-tick move that is still treated as travel, squared.
 *
 * The fastest thing in the game is a projectile at 120 u/s, which is 2 units in a
 * 60Hz tick; the fastest enemy manages a little over one. 20 units leaves an order of
 * magnitude of headroom over anything that moves under its own power, and is far below
 * the ~190-unit jump a recycled enemy makes.
 */
const MAX_INTERPOLATED_STEP_SQ = 20 * 20;

export class TransformInterpolator {
  /** Previous-tick position, 3 floats per entity index. */
  private positions: Float32Array;
  /** Previous-tick orientation, 4 floats per entity index. */
  private rotations: Float32Array;
  /** Generation of the entity the slot was captured for; 0 means "never captured". */
  private generations: Uint16Array;
  private captured: Uint8Array;

  constructor(capacity = 1024) {
    this.positions = new Float32Array(capacity * 3);
    this.rotations = new Float32Array(capacity * 4);
    this.generations = new Uint16Array(capacity);
    this.captured = new Uint8Array(capacity);
  }

  /**
   * Records the current transforms as "previous".
   *
   * Call immediately BEFORE each `stepSim`, inside the fixed-step loop — not once per
   * rendered frame. Several ticks can run between two frames, and "previous" must
   * mean one tick back, not one frame back.
   */
  capture(world: SimWorld): void {
    const { transform } = world.components;
    const pos = transform.columns.pos;
    const rot = transform.columns.rot;

    for (let row = 0; row < transform.count; row++) {
      const entity = transform.dense[row]! as Entity;
      const index = entityIndex(entity);
      if (index >= this.captured.length) this.grow(index + 1);

      const p = index * 3;
      const r = index * 4;
      this.positions[p] = pos[row * 3]!;
      this.positions[p + 1] = pos[row * 3 + 1]!;
      this.positions[p + 2] = pos[row * 3 + 2]!;
      this.rotations[r] = rot[row * 4]!;
      this.rotations[r + 1] = rot[row * 4 + 1]!;
      this.rotations[r + 2] = rot[row * 4 + 2]!;
      this.rotations[r + 3] = rot[row * 4 + 3]!;
      this.generations[index] = entityGeneration(entity);
      this.captured[index] = 1;
    }
  }

  /**
   * Writes the entity's rendered position into `out`, blended by `alpha`.
   *
   * Falls back to the current position when there is nothing to blend from — a brand
   * new entity, or one whose index was recycled since the last capture.
   */
  position(world: SimWorld, entity: Entity, alpha: number, out: Vec3): Vec3 {
    const { transform } = world.components;
    const row = transform.row(entity);
    if (row < 0) return out;

    out.readFrom(transform.columns.pos, row * 3);
    if (!this.hasPrevious(entity)) return out;

    const p = entityIndex(entity) * 3;
    // A teleport is not motion, and blending across one draws a streak from wherever
    // the entity used to be to wherever it now is. Recycled enemies are moved the
    // length of the encounter in a single tick, so this is reachable in normal play
    // rather than only in theory. Snapping on a delta no legitimate mover could
    // produce in one tick keeps this in the view, where a rendering artifact belongs,
    // instead of asking the simulation to announce that it moved something.
    const dx = out.x - this.positions[p]!;
    const dy = out.y - this.positions[p + 1]!;
    const dz = out.z - this.positions[p + 2]!;
    if (dx * dx + dy * dy + dz * dz > MAX_INTERPOLATED_STEP_SQ) return out;

    return out.set(
      this.positions[p]! + (out.x - this.positions[p]!) * alpha,
      this.positions[p + 1]! + (out.y - this.positions[p + 1]!) * alpha,
      this.positions[p + 2]! + (out.z - this.positions[p + 2]!) * alpha,
    );
  }

  /** Writes the entity's rendered orientation into `out`, slerped by `alpha`. */
  rotation(world: SimWorld, entity: Entity, alpha: number, out: Quat): Quat {
    const { transform } = world.components;
    const row = transform.row(entity);
    if (row < 0) return out;

    out.readFrom(transform.columns.rot, row * 4);
    if (!this.hasPrevious(entity)) return out;

    const r = entityIndex(entity) * 4;
    scratchRotation.set(
      this.rotations[r]!,
      this.rotations[r + 1]!,
      this.rotations[r + 2]!,
      this.rotations[r + 3]!,
    );
    // Blend from previous toward current, so alpha=1 lands exactly on the tick state.
    return out.copy(scratchRotation.slerp(out, alpha));
  }

  private hasPrevious(entity: Entity): boolean {
    const index = entityIndex(entity);
    return (
      index < this.captured.length &&
      this.captured[index] === 1 &&
      this.generations[index] === entityGeneration(entity)
    );
  }

  /**
   * Forgets every captured transform.
   *
   * Needed when the world is REPLACED rather than stepped — a restart. A fresh
   * `SimWorld` allocates entities from zero again, so the new run's ship reuses the
   * old run's index AND generation, and a stale capture would be accepted as this
   * entity's previous position. The visible result is one frame of every object
   * smeared from wherever its counterpart died to wherever the new run begins.
   */
  reset(): void {
    this.captured.fill(0);
    this.generations.fill(0);
  }

  private grow(needed: number): void {
    let size = this.captured.length;
    while (size < needed) size *= GROW_FACTOR;

    const positions = new Float32Array(size * 3);
    positions.set(this.positions);
    this.positions = positions;

    const rotations = new Float32Array(size * 4);
    rotations.set(this.rotations);
    this.rotations = rotations;

    const generations = new Uint16Array(size);
    generations.set(this.generations);
    this.generations = generations;

    const captured = new Uint8Array(size);
    captured.set(this.captured);
    this.captured = captured;
  }
}

const scratchRotation = new Quat();
