// A debug overlay for the rail's forks: where the choice locks in, which way it is
// currently pointing, and where the route not taken actually goes.
//
// It exists because a fork was invisible. The Narrows ships the game's first authored
// TRIGGER fork — clear the gate wave and the rail takes the low route — and flown by
// hand, clearing the wave and ignoring it looked identical. Three things were missing
// and only the third is a rendering problem:
//
// 1. Nothing marked the commit point, so there was no moment to watch for.
// 2. Nothing showed which way the fork was currently leaning, so nothing changed
//    visibly when the trigger fired.
// 3. **The alternative route was never drawn.** The rail guide follows the CURRENT
//    course only, so before a commit the other branch does not exist on screen — which
//    is most of why two genuinely different routes felt like one.
//
// Debug-only, and gated from `app` rather than sniffed here: `view` must not learn what
// a debug document is. It draws nothing and allocates nothing until it is turned on.

import {
  BufferGeometry,
  Color,
  EllipseCurve,
  Line,
  LineBasicMaterial,
  LineLoop,
  Matrix4,
  Vector3,
} from "three";
import { Vec3 } from "@core/math/index.js";
import { chooseCourse, TRUNK_COURSE, type MutableRailFrame } from "@sim/rail.js";
import { selectionContext } from "@sim/systems/forks.js";
import type { SimWorld } from "@sim/world.js";

/** Radius of the commit ring, in world units. Wider than the travel box on purpose. */
const RING_RADIUS = 9;
const RING_SEGMENTS = 48;
/** How finely a ghost course is sampled. Coarser than the real guide; it is a hint. */
const GHOST_SAMPLES = 160;

/**
 * Amber for the route the fork takes by DEFAULT, green for the one that has to be
 * earned.
 *
 * The same pair the HUD readout uses, deliberately: the ring ahead of the ship and the
 * text in the corner have to be saying the same thing in the same language, or a player
 * checking one against the other learns nothing. Amber is also the colour the stop
 * banner already uses for "the rail wants something from you", which is exactly what an
 * unearned fork is.
 */
const DEFAULT_COLOR = 0xffd479;
const EARNED_COLOR = 0x5fe0a0;
const GHOST_COLOR = 0x27506b;

export interface ForkMarker {
  /** Turns the whole overlay on or off. Off by default; nothing is built until on. */
  setVisible(visible: boolean): void;
  update(world: SimWorld): void;
  /**
   * Whether the commit ring is currently drawn.
   *
   * Exposed for the smoke, which cannot read a line's colour out of a canvas but can
   * tell drawn from not drawn — and the first version of this shipped with the overlay
   * enabled on ONE side of its seam, so the readout appeared and the ring never did.
   */
  ringVisible(): boolean;
  dispose(): void;
}

export function createForkMarker(scene: {
  add(o: Line | LineLoop): void;
  remove(o: Line | LineLoop): void;
}): ForkMarker {
  const ringMaterial = new LineBasicMaterial({ color: new Color(DEFAULT_COLOR) });
  const ring = new LineLoop(ringGeometry(), ringMaterial);
  ring.visible = false;
  scene.add(ring);

  const ghosts: Line[] = [];
  let ghostsBuiltFor: unknown = null;
  let visible = false;

  const frame: MutableRailFrame = {
    position: new Vec3(),
    tangent: new Vec3(),
    normal: new Vec3(),
    binormal: new Vec3(),
  };
  const basis = new Matrix4();
  const sample = new Vec3();

  const clearGhosts = (): void => {
    for (const ghost of ghosts) {
      scene.remove(ghost);
      ghost.geometry.dispose();
    }
    ghosts.length = 0;
    ghostsBuiltFor = null;
  };

  return {
    setVisible(next) {
      visible = next;
      if (!visible) {
        ring.visible = false;
        clearGhosts();
      }
    },

    update(world) {
      if (!visible) return;
      const rail = world.rail;
      const course = rail?.courses[world.courseId];
      if (!rail || !course) {
        ring.visible = false;
        return;
      }

      // ── Ghost courses ───────────────────────────────────────────────────────
      // Every course except the one being flown, which the real guide already draws.
      // Rebuilt only when the NETWORK changes, not when the course does: switching
      // course at a fork moves which line is the real one, and re-uploading every
      // buffer for that would drop a frame at exactly the moment the player is looking.
      if (ghostsBuiltFor !== rail) {
        clearGhosts();
        for (let id = 0; id < rail.courseCount; id++) {
          const other = rail.courses[id]!;
          const points: Vector3[] = [];
          for (let i = 0; i <= GHOST_SAMPLES; i++) {
            other.sample((i / GHOST_SAMPLES) * other.length, sample);
            points.push(new Vector3(sample.x, sample.y, sample.z));
          }
          const ghost = new Line(
            new BufferGeometry().setFromPoints(points),
            new LineBasicMaterial({ color: new Color(GHOST_COLOR) }),
          );
          scene.add(ghost);
          ghosts.push(ghost);
        }
        ghostsBuiltFor = rail;
      }
      for (let id = 0; id < ghosts.length; id++) ghosts[id]!.visible = id !== world.courseId;

      // ── The commit ring ─────────────────────────────────────────────────────
      // Placed at `commitS`, which is one full segment BEFORE the visible split. That
      // is the whole commit rule and it is the reason this marker is worth drawing at
      // all: the decision is already taken by the time the rail is seen to divide, so a
      // ring on the split itself would mark a moment at which nothing can be changed.
      const next = rail.nextForkOn(
        world.courseId,
        Math.max(world.railS, world.lastForkS + 1e-9),
      );
      if (next === null) {
        ring.visible = false;
        return;
      }

      course.frameAt(next.commitS, frame);
      // Same `chooseCourse` and same context the fork system itself uses — see the note
      // on `selectionContext`. A marker that previewed a different answer than the one
      // taken would be worse than no marker.
      const wouldTake = chooseCourse(next, selectionContext(world));
      const earned = (rail.courseBranch(wouldTake) ?? TRUNK_COURSE) !== TRUNK_COURSE;
      ringMaterial.color.setHex(earned ? EARNED_COLOR : DEFAULT_COLOR);

      // The ring's own plane is XY, so its +Z has to become the rail tangent for it to
      // read as a gate across the track rather than a hoop lying flat in it.
      basis.makeBasis(
        new Vector3(frame.binormal.x, frame.binormal.y, frame.binormal.z),
        new Vector3(frame.normal.x, frame.normal.y, frame.normal.z),
        new Vector3(frame.tangent.x, frame.tangent.y, frame.tangent.z),
      );
      ring.quaternion.setFromRotationMatrix(basis);
      ring.position.set(frame.position.x, frame.position.y, frame.position.z);
      ring.visible = true;
    },

    ringVisible: () => ring.visible,

    dispose() {
      scene.remove(ring);
      ring.geometry.dispose();
      ringMaterial.dispose();
      clearGhosts();
    },
  };
}

function ringGeometry(): BufferGeometry {
  const curve = new EllipseCurve(0, 0, RING_RADIUS, RING_RADIUS, 0, Math.PI * 2, false, 0);
  return new BufferGeometry().setFromPoints(
    curve.getPoints(RING_SEGMENTS).map((p) => new Vector3(p.x, p.y, 0)),
  );
}
