// The meta-save: what a player has EARNED, and what they have spent it on.
//
// The second of the two persisted documents, and `settingsStore.ts` says why they are
// two rather than one: settings describe a control setup, this describes progress, and
// a corrupt document of one kind must never cost the player the other. Two documents,
// two lifetimes.
//
// ── Owned IS equipped, for now ────────────────────────────────────────────────
//
// The roadmap lists "owned upgrades, loadout" as two things and they will be, but not
// yet: every upgrade in the shipped catalog is strictly good except `HEAVY_SLUGS`,
// which trades muzzle speed for damage. With five entries and one trade-off there is no
// interesting equip decision to make, so a loadout screen would be a second list to
// keep in step with the first and nothing to choose in it. `equipped()` is the seam that
// becomes real when a slot limit or a genuine trade-off arrives — every caller already
// goes through it rather than reading `owned` directly.
//
// ── Nothing read from storage is trusted ──────────────────────────────────────
//
// The same rule the debug store follows, and for a stronger reason here: this document
// decides what the player owns, so a hand-edited one is the obvious way to cheat and a
// STALE one is the ordinary case. An id that was in the catalog two builds ago is not an
// error to report — it is an upgrade that was renamed or removed, and the only sane
// reading of it is that it is not owned. Unknown ids are dropped on the way in.

import { UPGRADES } from "@content/upgrades/index.js";
import type { UpgradeCatalog, UpgradeDef } from "@content/schemas/upgrade.js";

const KEY = "sw.meta";

/** Bumped when a stored document can no longer be read as-is. */
const VERSION = 1;

export interface MetaSave {
  /** Banked credits, available to spend. A non-negative integer, always. */
  readonly credits: number;
  /** Ids of owned upgrades. Deduped and sorted, so two equal saves compare equal. */
  readonly owned: readonly string[];
}

/** A player who has never flown. Also what any unreadable document falls back to. */
export const EMPTY_SAVE: MetaSave = { credits: 0, owned: [] };

/**
 * Credits are whole numbers.
 *
 * Floored rather than rounded: rounding a stored 99.6 up to 100 would let a hand-edited
 * — or simply corrupt — document buy something it could not afford, and the direction
 * that errs toward the player is the one worth avoiding in the one function that decides
 * what they can spend.
 */
const clampCredits = (value: unknown): number => {
  const n = typeof value === "number" ? value : Number.NaN;
  if (!Number.isFinite(n) || n <= 0) return 0;
  return Math.floor(n);
};

/** Drops unknown ids, dedupes, and sorts. The only way an id list enters the document. */
const cleanOwned = (value: unknown, catalog: UpgradeCatalog): readonly string[] => {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  for (const entry of value as unknown[]) {
    if (typeof entry === "string" && catalog[entry]) seen.add(entry);
  }
  // Sorted so the document is stable on disk and two saves with the same contents are
  // `JSON.stringify`-equal — which is what lets a spec compare them directly.
  return [...seen].sort();
};

/**
 * Turns a stored string into a save. Pure, and the only path a document takes inward.
 *
 * Split from `loadMeta` the way `parseDebugJson` is split from `loadDebug`: everything
 * that DECIDES anything is here and specced headlessly, and the function that touches
 * `localStorage` is left to the browser. It is also the function a future migration
 * chain grows inside, which is a second reason not to bury it behind a global.
 *
 * Any failure returns `EMPTY_SAVE` rather than throwing. A player losing progress to a
 * bad document is bad; a player unable to BOOT because of one is worse, and
 * unrecoverable without a console.
 */
export function parseMeta(raw: string | null, catalog: UpgradeCatalog = UPGRADES): MetaSave {
  let stored: Partial<{ version: number; credits: number; owned: unknown }> = {};
  try {
    if (raw) {
      const parsed: unknown = JSON.parse(raw);
      if (parsed && typeof parsed === "object") stored = parsed as typeof stored;
    }
  } catch {
    // Malformed JSON. Nothing to recover and nothing worth reporting.
  }
  // A document from a version this build does not know is ignored wholesale rather than
  // field-by-field, exactly as the settings document is. There is one version so far, so
  // this is the shape of the decision rather than a migration — but this is the document
  // that will actually need the chain, because it is the one a player would mind losing.
  if (stored.version !== undefined && stored.version !== VERSION) return EMPTY_SAVE;

  return {
    credits: clampCredits(stored.credits),
    owned: cleanOwned(stored.owned, catalog),
  };
}

/** Reads the stored save. Storage being unavailable is a fallback, not an error. */
export function loadMeta(catalog: UpgradeCatalog = UPGRADES): MetaSave {
  try {
    return parseMeta(window.localStorage.getItem(KEY), catalog);
  } catch {
    // Private browsing or storage disabled. Not worth a broken boot.
    return EMPTY_SAVE;
  }
}

export function saveMeta(save: MetaSave): void {
  try {
    window.localStorage.setItem(
      KEY,
      JSON.stringify({ version: VERSION, credits: save.credits, owned: save.owned }),
    );
  } catch {
    // Storage full or disabled. The run still works; the progress just will not outlive
    // the tab, and there is nothing useful to tell the player about it mid-flight.
  }
}

/**
 * Adds a finished run's credits to the bank.
 *
 * Returns the SAME OBJECT when there is nothing to add, so a caller can skip the write
 * by identity — the idiom the debug and difficulty folds use for an untouched document.
 *
 * Negative and fractional earnings are floored to zero and whole respectively rather
 * than trusted: `world.credits` is a simulation number and this is the boundary where it
 * stops being one.
 */
export function bank(save: MetaSave, earned: number): MetaSave {
  const amount = clampCredits(earned);
  if (amount === 0) return save;
  return { ...save, credits: save.credits + amount };
}

/**
 * Buys an upgrade, if it is affordable and not already owned.
 *
 * Returns the SAME OBJECT when the purchase cannot happen, so the caller checks by
 * identity rather than by a boolean it could forget to read. There is deliberately no
 * throw: a shop that offers an unaffordable row is a rendering bug, and taking down the
 * page is a worse answer to it than doing nothing.
 */
export function purchase(save: MetaSave, upgrade: UpgradeDef): MetaSave {
  if (save.owned.includes(upgrade.id)) return save;
  if (save.credits < upgrade.cost) return save;
  return {
    credits: save.credits - upgrade.cost,
    owned: [...save.owned, upgrade.id].sort(),
  };
}

/**
 * Sells an upgrade back, at FULL price.
 *
 * Returns the SAME OBJECT when it is not owned, same as `purchase`.
 *
 * ── Why the refund is total ──────────────────────────────────────────────────
 *
 * A sell-back fee is a balance decision, and this shop is not yet a balanced economy —
 * it is a tuning instrument on a build nobody has finished flying. A full refund makes
 * the catalog something you can EXPERIMENT with: buy Heavy Slugs, fly a run, decide the
 * slower muzzle is not worth the damage, and put it back. Charging for that discourages
 * exactly the experiment the shop most needs performed on it right now.
 *
 * It also makes the one upgrade with a real trade-off testable at all. `HEAVY_SLUGS` is
 * the only entry whose value is not obvious, and with a lossy refund the honest advice to
 * a player would be "do not buy it until someone tells you if it is good".
 *
 * When the economy is tuned this may well become partial — a 50-75% buy-back is the
 * conventional answer — and that is a one-line change here plus a number in the shop
 * model. Until then it is deliberately free.
 *
 * While owned IS equipped this is also the UNEQUIP action: there is one list, so removing
 * something from it and refunding it are the same operation. When a separate `equipped`
 * list arrives they split, and this stays the one that touches credits.
 */
export function sell(save: MetaSave, upgrade: UpgradeDef): MetaSave {
  if (!save.owned.includes(upgrade.id)) return save;
  return {
    credits: save.credits + upgrade.cost,
    owned: save.owned.filter((id) => id !== upgrade.id),
  };
}

/**
 * The upgrades a run is built from.
 *
 * Owned is equipped today — see the header. Ids with no catalog entry are skipped rather
 * than faked, which matters on the path a save outlives the build that wrote it: the
 * stat fold takes `UpgradeDef`s, and a placeholder with no modifiers would be a silent
 * lie about what the ship is carrying.
 */
export function equipped(
  save: MetaSave,
  catalog: UpgradeCatalog = UPGRADES,
): readonly UpgradeDef[] {
  const defs: UpgradeDef[] = [];
  for (const id of save.owned) {
    const def = catalog[id];
    if (def) defs.push(def);
  }
  return defs;
}
