// The shop, drawn.
//
// A MODAL mounted once, not an inline panel mounted twice. The difficulty picker and
// the sensitivity sliders are inline and therefore exist in two copies — one on the
// title screen, one on the game-over overlay — which is why both carry a `set()` for
// reflecting a change made on the other. A modal needs none of that: there is one of
// it, either screen's button opens it, and the two can no longer disagree because there
// is no second copy to disagree with.
//
// It is also what keeps the title screen fitting a phone. That layout is already tight
// enough to be commented about — title, difficulty, two sliders and PLAY on a 390px-tall
// landscape viewport — and five upgrade rows inline would push PLAY off the bottom of
// the first screen anyone sees.
//
// Decisions, like the debug menu's, take effect on the NEXT run rather than this one:
// upgrades are folded into resolved stats when a world is built. Unlike difficulty,
// though, nothing here needs a confirm — the shop is reachable from the title screen,
// where there is no run yet, and from the game-over screen, where there is no longer
// one. There is never a run in progress to lose, which is the whole reason this did not
// need the pause that settings also did not need.

import type { UpgradeCatalog, UpgradeDef } from "@content/schemas/upgrade.js";
import type { MetaSave } from "./metaStore.js";
import { shopModel } from "./shop.js";

const STYLE = `
.sw-shop {
  position: fixed; inset: 0; z-index: 9;
  display: flex; align-items: center; justify-content: center;
  background: rgba(3,6,12,0.86);
  font: 12px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #cddcf0; pointer-events: auto; touch-action: manipulation;
  user-select: none; -webkit-user-select: none;
}
.sw-shop.sw-shop-hidden { display: none; }
.sw-shop-panel {
  width: min(560px, 94vw); max-height: 88vh; overflow-y: auto;
  /* Momentum scrolling, and a scroll that does not escape into the page behind it —
     the page is scroll-locked for the canvas's sake and would otherwise swallow the
     drag once this list hits its end. */
  -webkit-overflow-scrolling: touch; overscroll-behavior: contain;
  padding: 16px 18px calc(16px + env(safe-area-inset-bottom, 0px));
  background: rgba(8,14,26,0.96); border: 1px solid #2b3d5a; border-radius: 12px;
}
.sw-shop-head {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
  border-bottom: 1px solid #1d2c44; padding-bottom: 10px;
}
.sw-shop-title { font-size: 14px; letter-spacing: 0.24em; color: #ffd479; }
.sw-shop-credits { font-size: 13px; letter-spacing: 0.12em; color: #7fd6a2; }
.sw-shop-row {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 0; border-bottom: 1px solid #14203a;
}
.sw-shop-info { flex: 1 1 auto; min-width: 0; }
.sw-shop-name { color: #cddcf0; letter-spacing: 0.1em; font-size: 12px; }
.sw-shop-effects { margin-top: 4px; display: flex; flex-wrap: wrap; gap: 4px 10px; }
.sw-shop-effect { font-size: 11px; letter-spacing: 0.06em; color: #7fd6a2; }
.sw-shop-effect.bad { color: #e08a7a; }
.sw-shop-buy {
  flex: none; pointer-events: auto;
  font: 600 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.14em; color: #eaf3ff;
  background: rgba(30,70,120,0.9); border: 1px solid #6fa2dd; border-radius: 8px;
  /* 44px: pressed with a thumb on the device this is being played on. */
  min-height: 44px; min-width: 92px; padding: 0 14px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.sw-shop-buy:hover { background: rgba(44,96,158,0.9); }
.sw-shop-buy:active { transform: scale(0.97); }
/* Disabled rather than hidden: a price you cannot meet yet is the information that
   makes a credit worth collecting, so it stays legible instead of disappearing. */
.sw-shop-buy:disabled {
  color: #63728c; background: rgba(14,22,38,0.9); border-color: #263850;
  cursor: default; transform: none;
}
/* Owned rows are LIVE — the button sells back — so they need their own hover and active,
   or the base rule above would repaint them blue on touch and lose the one cue that says
   this upgrade is already on the ship. */
.sw-shop-buy.owned { color: #7fd6a2; background: rgba(16,38,30,0.9); border-color: #2f6b50; }
.sw-shop-buy.owned:hover { background: rgba(24,58,44,0.95); }
.sw-shop-buy.owned:active { transform: scale(0.97); background: rgba(40,86,64,0.9); }
.sw-shop-note { margin-top: 14px; color: #63728c; font-size: 11px; letter-spacing: 0.06em; }
.sw-shop-actions { display: flex; justify-content: flex-end; margin-top: 16px; }
.sw-shop-close {
  pointer-events: auto;
  font: 600 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.16em; color: #cddcf0;
  background: rgba(14,26,46,0.9); border: 1px solid #3d5f8c; border-radius: 8px;
  min-height: 44px; padding: 0 22px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.sw-shop-close:hover { background: rgba(24,44,74,0.95); }
.sw-shop-close:active { transform: scale(0.97); }
`;

export interface ShopOptions {
  readonly initial: MetaSave;
  readonly catalog: UpgradeCatalog;
  /**
   * Called when a BUY is pressed on an affordable, unowned row.
   *
   * The view does not decide whether the purchase succeeded and does not update itself:
   * the owner spends from the save, persists it, and calls `set()` with the result. One
   * place decides, which is what stops the drawn balance and the stored one drifting.
   */
  readonly onPurchase: (upgrade: UpgradeDef) => void;
  /** Called when SELL is pressed on an owned row. Same contract as `onPurchase`. */
  readonly onSell: (upgrade: UpgradeDef) => void;
}

export interface Shop {
  readonly root: HTMLElement;
  readonly isOpen: boolean;
  open(): void;
  close(): void;
  /** Redraws from a save. Called after every purchase and after a run banks its credits. */
  set(save: MetaSave): void;
  dispose(): void;
}

export function createShop(options: ShopOptions, parent: HTMLElement = document.body): Shop {
  const style = document.createElement("style");
  style.textContent = STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-shop sw-shop-hidden";
  root.dataset.shop = "";

  const panel = document.createElement("div");
  panel.className = "sw-shop-panel";

  const head = document.createElement("div");
  head.className = "sw-shop-head";
  const heading = document.createElement("div");
  heading.className = "sw-shop-title";
  heading.textContent = "UPGRADES";
  const credits = document.createElement("div");
  credits.className = "sw-shop-credits";
  credits.dataset.shopCredits = "";
  head.append(heading, credits);

  const list = document.createElement("div");

  const note = document.createElement("div");
  note.className = "sw-shop-note";

  const actions = document.createElement("div");
  actions.className = "sw-shop-actions";
  const close = document.createElement("button");
  close.type = "button";
  close.className = "sw-shop-close";
  close.dataset.shopClose = "";
  close.textContent = "CLOSE";
  actions.appendChild(close);

  panel.append(head, list, note, actions);
  root.appendChild(panel);
  parent.appendChild(root);

  // One listener on the list rather than one per button, so a redraw — which replaces
  // every row — cannot leak listeners or leave a stale one bound to a button that has
  // been detached.
  const onClick = (event: Event) => {
    const target = (event.target as HTMLElement | null)?.closest<HTMLButtonElement>("[data-shop-buy]");
    if (!target || target.disabled) return;
    event.preventDefault();
    event.stopPropagation();
    const upgrade = options.catalog[target.dataset.shopBuy ?? ""];
    if (!upgrade) return;
    // The MODEL decided which action this row offers; this reads it back rather than
    // re-deriving it from the save, so there is one answer to "buy or sell" and the
    // button the player pressed is the one that describes what happens.
    if (target.dataset.shopAction === "sell") options.onSell(upgrade);
    else if (target.dataset.shopAction === "buy") options.onPurchase(upgrade);
  };
  list.addEventListener("click", onClick);

  const onClose = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    root.classList.add("sw-shop-hidden");
  };
  close.addEventListener("click", onClose);

  // A tap on the backdrop closes, the way a modal is expected to. Guarded on the target
  // being the backdrop ITSELF: without that, any click inside the panel bubbles up here
  // and closes the shop the moment a BUY is pressed.
  const onBackdrop = (event: Event) => {
    if (event.target !== root) return;
    root.classList.add("sw-shop-hidden");
  };
  root.addEventListener("click", onBackdrop);

  const render = (save: MetaSave): void => {
    const model = shopModel(save, options.catalog);
    credits.textContent = `${model.credits} CR`;
    list.textContent = "";

    for (const row of model.rows) {
      const el = document.createElement("div");
      el.className = "sw-shop-row";

      const info = document.createElement("div");
      info.className = "sw-shop-info";
      const name = document.createElement("div");
      name.className = "sw-shop-name";
      name.textContent = row.upgrade.name;
      const effects = document.createElement("div");
      effects.className = "sw-shop-effects";
      for (const effect of row.effects) {
        const chip = document.createElement("span");
        chip.className = effect.good ? "sw-shop-effect" : "sw-shop-effect bad";
        chip.textContent = effect.text;
        effects.appendChild(chip);
      }
      info.append(name, effects);

      const buy = document.createElement("button");
      buy.type = "button";
      buy.className = row.owned ? "sw-shop-buy owned" : "sw-shop-buy";
      buy.dataset.shopBuy = row.upgrade.id;
      // The row is a toggle: an owned upgrade sells back at full price, so the control
      // that bought it is the control that puts it away. The price stays on the button
      // when selling — it is what you get back, and it is the number a player is deciding
      // against either way.
      buy.dataset.shopAction = row.action;
      buy.textContent = row.owned ? `SELL ${row.upgrade.cost}` : `${row.upgrade.cost} CR`;
      // Only an unaffordable unowned row is dead. Owned rows are now LIVE, which is the
      // change: previously they were disabled and read OWNED, and there was no way back
      // out of a purchase at all.
      buy.disabled = row.action === "none";

      el.append(info, buy);
      list.appendChild(el);
    }

    // Says the refund is total, because that is what makes the catalog safe to
    // experiment with and nobody would assume it.
    note.textContent = model.complete
      ? "Everything is bought. Fly it. Selling refunds in full."
      : "Applies to your next run. Selling refunds in full.";
  };

  render(options.initial);

  return {
    root,
    get isOpen() {
      return !root.classList.contains("sw-shop-hidden");
    },
    open() {
      root.classList.remove("sw-shop-hidden");
    },
    close() {
      root.classList.add("sw-shop-hidden");
    },
    set: render,
    dispose() {
      list.removeEventListener("click", onClick);
      close.removeEventListener("click", onClose);
      root.removeEventListener("click", onBackdrop);
      root.remove();
      style.remove();
    },
  };
}
