// The input composition point.
//
// Every source produces INTENT; this is the one place that merges them and calls
// `makeInputFrame`. That single call site is the whole reason the split exists: the
// frame is quantized at construction (see `core/input.ts`), so a source that built its
// own frame would be quantizing separately, and two sources merged AFTER quantization
// would round twice. Merging raw and quantizing once keeps a stick pulled half-left
// worth exactly the same on a phone as on a keyboard — and the same as it will be on
// the wire.
//
// Axes are summed and then clamped by `makeInputFrame`, rather than one source winning.
// It costs nothing, and it means a Bluetooth keyboard paired to a tablet does not fight
// the on-screen stick for control of the ship.

import { makeInputFrame, type InputFrame } from "@core/input.js";
import { Keyboard } from "./keyboard.js";
import { forcedTouch, looksLikeTouch, trackFirstTouch } from "./inputSource.js";
import { createTouchView, type TouchView } from "./touchView.js";
import { DEFAULT_SENSITIVITY, type StickSensitivity } from "./settingsStore.js";

export interface Controls {
  /** Builds the frame for a tick. Call exactly once per tick — it consumes tap latches. */
  sample(tick: number): InputFrame;
  /** Repaints any on-screen control. Once per rendered frame, not per tick. */
  draw(): void;
  /** Re-lays-out any on-screen control for the current viewport. */
  resize(): void;
  /**
   * Changes how far a thumb travels for a full axis. Applies immediately.
   *
   * A no-op without touch controls: a keyboard has no travel to scale.
   */
  setSensitivity(sensitivity: StickSensitivity): void;
  /** Whether the on-screen controls are up. Becomes true on a first touch. */
  readonly touchActive: boolean;
  /**
   * Subscribes to the on-screen controls appearing. Fires IMMEDIATELY if they already
   * have, so a caller never has to ask twice or race the boot.
   *
   * It exists because what a sensitivity slider scales is the on-screen stick, so a UI
   * that shows one has to follow the controls rather than re-run the sniff itself.
   */
  onTouchActive(listener: () => void): void;
  dispose(): void;
}

export function createControls(target: Window = window): Controls {
  const keyboard = new Keyboard();
  const detachKeyboard = keyboard.attach(target);

  let touch: TouchView | null = null;
  // Remembered so a view created LATER — on a first touch — comes up at the
  // sensitivity the player already chose, rather than at 1.0 until they touch a slider.
  let sensitivity: StickSensitivity = DEFAULT_SENSITIVITY;
  const listeners: (() => void)[] = [];

  const activate = (): void => {
    if (touch) return;
    touch = createTouchView();
    touch.setSensitivity(sensitivity);
    // Copied before iterating: a listener that subscribes another (the title screen
    // adds one when it mounts) must not mutate the array being walked.
    for (const listener of [...listeners]) listener();
  };

  const forced = forcedTouch(target.location.search);
  // `?touch=0` means off, and stays off through any number of taps — someone forcing
  // the desktop layout on a tablet is making a decision, not describing their hardware.
  let detachFirstTouch: (() => void) | null = null;
  if (forced ?? looksLikeTouch()) {
    activate();
  } else if (forced === null) {
    // The touchscreen-laptop case the boot sniff deliberately excludes: no controls
    // until a finger actually arrives, and then they appear along with the sliders
    // that scale them.
    detachFirstTouch = trackFirstTouch(target, activate);
  }

  return {
    get touchActive() {
      return touch !== null;
    },

    onTouchActive(listener) {
      if (touch) {
        listener();
        return;
      }
      listeners.push(listener);
    },

    sample(tick) {
      const k = keyboard.sample();
      const t = touch?.controls.sample();
      // A keyboard is a SINGLE-STICK source: its arrow keys both slide the ship and
      // turn the reticle, which is the coupling `makeInputFrame` defaults to. Leaving
      // the aim axes off here is what keeps the desktop feel exactly as it was.
      if (!t) return makeInputFrame(tick, k.steerX, k.steerY, k.buttons);

      // With touch present the two are genuinely independent — the left stick
      // translates, the firing thumb rotates — so all four are passed. The keyboard's
      // steer is added into BOTH, preserving its coupling for a tablet with a keyboard
      // paired to it without stopping the on-screen sticks from being separate.
      return makeInputFrame(
        tick,
        k.steerX + t.steerX,
        k.steerY + t.steerY,
        k.buttons | t.buttons,
        k.steerX + t.aimX,
        k.steerY + t.aimY,
      );
    },

    draw() {
      touch?.draw();
    },

    resize() {
      touch?.resize();
    },

    setSensitivity(next) {
      sensitivity = next;
      touch?.setSensitivity(next);
    },

    dispose() {
      detachKeyboard();
      detachFirstTouch?.();
      touch?.dispose();
    },
  };
}
