// The difficulty catalog.
//
// Three levels, and the middle one is the game as authored. That ordering is not
// cosmetic: the demo level's numbers were tuned by flying it, so NORMAL has to mean
// "those numbers" and the other two have to be expressed as departures from them.
// EASY that quietly became the baseline would make every future tuning conversation
// start from the wrong place.
//
// What each knob is worth was chosen from what actually kills a player on this level:
// contact with the field is the dominant cause of death by a wide margin (a rock is 25
// damage, which was four hits against the hull of 100 these ratios were picked at, and
// is twenty against today's 500), enemy fire is second, and running out of room to
// dodge is what makes the field lethal at all. So EASY buys room and hull rather than
// turning the enemies into targets — it should be the same game, flown with more
// margin, not a different one.
//
// The hull retune multiplied the margin without changing the ORDER of those causes, so
// the ratios below still describe the right thing. If contact ever stops being the
// dominant killer, this paragraph is the one to revisit before the numbers are.

import type { DifficultyCatalog, DifficultyDef } from "../schemas/difficulty.js";

export type { DifficultyDef } from "../schemas/difficulty.js";

/**
 * More hull, a thinner field, softer hits.
 *
 * Enemy health is deliberately NOT reduced. A drone that dies to one shot instead of
 * three stops reading as an enemy and starts reading as a prop, and the complaint that
 * prompted difficulty in the first place was about survival, not about how long things
 * take to kill.
 */
export const EASY: DifficultyDef = {
  id: "difficulty.easy",
  label: "EASY",
  hullScale: 1.5,
  enemyDamageScale: 0.6,
  contactDamageScale: 0.6,
  hazardRateScale: 0.6,
  enemyHealthScale: 1,
  // A bolt with real width. Hitting a weaving drone with a thumb is the hardest thing
  // this game asks, and it is a problem of CONNECTING rather than of doing enough once
  // you have — so widening the bolt is the honest easy-mode lever, where more damage
  // or more enemy health would only make the same misses cheaper.
  playerHitRadiusBonus: 0.6,
};

/** The game as authored. Every scale is 1 — see the header of `schemas/difficulty.ts`. */
export const NORMAL: DifficultyDef = {
  id: "difficulty.normal",
  label: "NORMAL",
  hullScale: 1,
  enemyDamageScale: 1,
  contactDamageScale: 1,
  hazardRateScale: 1,
  enemyHealthScale: 1,
  playerHitRadiusBonus: 0,
};

/**
 * Less hull, a denser field, harder hits, tougher enemies.
 *
 * The one level that scales enemy health, because at this end the complaint it would
 * cause is the point: an interceptor that takes six hits instead of four has to be
 * committed to rather than clipped in passing.
 */
export const HARD: DifficultyDef = {
  id: "difficulty.hard",
  label: "HARD",
  hullScale: 0.75,
  enemyDamageScale: 1.4,
  contactDamageScale: 1.4,
  hazardRateScale: 1.35,
  enemyHealthScale: 1.5,
  // Not negative: the bolt is already a point, and there is nothing below that.
  playerHitRadiusBonus: 0,
};

export const DIFFICULTIES: DifficultyCatalog = {
  [EASY.id]: EASY,
  [NORMAL.id]: NORMAL,
  [HARD.id]: HARD,
};

/**
 * Presentation order, easiest first. This is what the chips render from, so it is the
 * order the player sees rather than an arbitrary object-key order.
 */
export const DIFFICULTY_ORDER: readonly DifficultyDef[] = [EASY, NORMAL, HARD];

/** What a player gets before they have chosen anything. */
export const DEFAULT_DIFFICULTY = NORMAL;

/** Resolves a stored or URL-supplied id, falling back rather than throwing. */
export const difficultyById = (id: string | null | undefined): DifficultyDef =>
  (id ? DIFFICULTIES[id] : undefined) ?? DEFAULT_DIFFICULTY;
