// The ambient hazard spawner.
//
// Seeds the field ahead of the party as they travel. Two properties matter more than
// the placement itself:
//
//   1. The rate accrues from TICKS, never from a wall clock. The old spawner
//      multiplied a per-second rate by a variable frame delta, so a player on a
//      slower machine met a different number of asteroids.
//   2. Each placement consumes a FIXED number of RNG draws (see `chooseSpawnPoint`),
//      so a run is reproducible and six clients agree.

import { Vec3 } from "@core/math/index.js";
import type { Entity } from "@core/ecs.js";
import type { HazardDef } from "@content/schemas/hazard.js";
import { chooseSpawnPoint, type SpawnTableEntry, type SpawnViewer } from "../spawn.js";
import type { SimWorld } from "../world.js";

/**
 * How far behind the party a hazard must be before it is culled.
 *
 * Generous on purpose. It has to be well past any chance of being seen — including in
 * the chase camera, which sits behind the ship — and well past the swept-collision
 * reach of a projectile still travelling. Cheap to be conservative: the cost of a
 * lingering rock is one row.
 */
const CULL_BEHIND = 120;

const center = new Vec3();
const spawnAt = new Vec3();
const viewerPosition = new Vec3();
const viewerDirection = new Vec3();
const hazardPosition = new Vec3();
const toHazard = new Vec3();

/**
 * Picks an archetype by weight in exactly ONE draw.
 *
 * A loop that re-rolled until it liked the answer would consume a variable number of
 * draws, which is the precise failure the old spawner had — so the weights are walked
 * against a single sample instead. The final `??` covers a table of zero total weight
 * rather than returning undefined into a spawn.
 */
function pickFromTable(roll: number, table: readonly SpawnTableEntry[]): HazardDef | null {
  if (table.length === 0) return null;
  const total = table.reduce((sum, entry) => sum + entry.weight, 0);
  if (total <= 0) return table[table.length - 1]!.def;

  let cursor = roll * total;
  for (const entry of table) {
    cursor -= entry.weight;
    if (cursor < 0) return entry.def;
  }
  return table[table.length - 1]!.def;
}

export function spawnSystem(world: SimWorld): void {
  const config = world.spawnConfig;
  const rail = world.rail;
  if (!config || !rail) return;

  const course = rail.courses[world.courseId];
  if (!course) return;

  // Culling runs even while parked and even after the run is decided: hazards behind
  // the party are dead weight regardless, and leaving them to accumulate is what makes
  // `maxAlive` throttle spawning long before the level ends.
  cullPassedHazards(world, course);

  // Ambient spawning pauses during a stop. The stop's own burst is the authored
  // content there, and an omni stop lets ships face any direction — which would make
  // a single representative viewer (below) the wrong approximation.
  if (world.railHolding) return;

  // ...and stops entirely once the run is decided. Without this the spawner keeps
  // running after the rail has stopped advancing, with `lead` pinned at the rail's
  // end — so rocks pile up around one fixed point while the player sits still
  // watching them appear. Reported from the first playtest; the rail-advance check in
  // `flightSystem` had the outcome guard and this did not.
  if (world.outcome !== "running") return;

  world.spawnAccrual += config.ratePerSecond * world.dt;

  const hazard = world.components.hazard;
  while (world.spawnAccrual >= 1) {
    world.spawnAccrual -= 1;
    if (hazard.count >= config.maxAlive) continue;

    // Seed ahead along the rail, so hazards approach rather than materialise beside
    // the party. Clamped to the rail's end near the finish.
    const lead = Math.min(course.length, world.railS + config.leadDistance);
    course.sample(lead, center);

    // One representative viewer for the whole party: the rail centre, looking
    // down-track. Every ship rides the travel box around that point — a few units
    // off at most — and the cone test is deliberately conservative, so a placement
    // safe for the centre is safe for all six. Approximating here rather than
    // testing six viewers keeps the draw count fixed, which is the property that
    // actually matters for determinism.
    course.sample(world.railS, viewerPosition);
    course.tangentAt(world.railS, viewerDirection);
    const viewer: SpawnViewer = { position: viewerPosition, direction: viewerDirection };

    chooseSpawnPoint(world.rng, center, viewer, config, spawnAt);

    // Two further draws, taken UNCONDITIONALLY — before the null check, not after —
    // so an empty table consumes the same stream as a full one. A draw that happens
    // only sometimes is the bug this whole module is shaped around avoiding.
    const roll = world.rng.float();
    const variantRoll = world.rng.uint32();

    const def = pickFromTable(roll, config.table);
    if (!def) continue;
    world.spawnHazard(def, spawnAt, def.variants > 0 ? variantRoll % def.variants : 0);
  }
}

/**
 * Removes hazards the party has travelled well past.
 *
 * Nothing else ever removed a hazard — they died only by being shot or rammed — so the
 * field accreted until `maxAlive` was reached, at which point ambient spawning silently
 * stopped for the rest of the run. That was latent before splitting and acute after it,
 * since one large rock can now become seven.
 *
 * The test is "behind the party's current rail position along the rail's own forward
 * direction", which is a pure function of world state and therefore deterministic. It
 * is deliberately NOT a distance test: a rail that doubles back would cull rocks the
 * party is about to meet again.
 */
function cullPassedHazards(world: SimWorld, course: { sample(s: number, out: Vec3): Vec3; tangentAt(s: number, out: Vec3): Vec3 }): void {
  const { hazard } = world.components;
  if (hazard.count === 0) return;

  course.sample(world.railS, viewerPosition);
  course.tangentAt(world.railS, viewerDirection);

  // Backwards: destruction is deferred, but the reverse walk keeps this correct if
  // that ever changes.
  for (let row = hazard.count - 1; row >= 0; row--) {
    const entity = hazard.dense[row]! as Entity;
    if (!world.readPosition(entity, hazardPosition)) continue;

    toHazard.copy(hazardPosition).sub(viewerPosition);
    if (toHazard.dot(viewerDirection) >= -CULL_BEHIND) continue;

    // No credit and no split: this is bookkeeping, not a kill. Splitting here would
    // spawn debris out of sight behind the player and defeat the whole point.
    world.ecs.destroyLater(entity);
  }
}
