// The shop, as a pure model over the meta-save.
//
// Same split as `hud.ts` / `hudView.ts` and `touch.ts` / `touchView.ts`: everything
// decidable is decided here and specced headlessly, and `shopView.ts` only draws it.
// It earns the split for a reason the HUD does not — a shop that is WRONG about what a
// row costs or what it does is indistinguishable, from the player's side, from a shop
// that is lying, and both are found by reading numbers rather than by looking at pixels.
//
// ── Why the effect text lives here ───────────────────────────────────────────
//
// A modifier is `{ stat, op, value }`, which is the right shape to fold and the wrong
// shape to read. Turning `{ fireIntervalTicks, mul, 0.8 }` into "+25% FIRE RATE" is
// arithmetic — an inversion and a percentage — and arithmetic in a view is arithmetic
// nobody tests. It matters most in exactly the case shown: the content counts TICKS
// BETWEEN SHOTS, so the number goes DOWN as the gun gets better, and a shop that printed
// the raw factor would advertise an upgrade as a 20% cut to something. The debug menu
// makes the same inversion in the same direction and for the same reason.

import type { StatKey, StatModifier, UpgradeCatalog, UpgradeDef } from "@content/schemas/upgrade.js";
import type { MetaSave } from "./metaStore.js";

/**
 * How each stat is named and read on a shop row.
 *
 * `inverted` means the CONTENT number moves opposite to the quality: a smaller
 * `fireIntervalTicks` is a faster gun. It is the only entry that needs it, and it is
 * flagged rather than special-cased so adding a second cooldown-shaped stat is a table
 * edit rather than a new branch.
 */
const STATS: Readonly<Record<StatKey, { readonly label: string; readonly inverted?: true }>> = {
  maxHealth: { label: "HULL" },
  radius: { label: "HITBOX" },
  boxSpeed: { label: "SLIDE" },
  aimRate: { label: "TURN" },
  damage: { label: "DAMAGE" },
  fireIntervalTicks: { label: "FIRE RATE", inverted: true },
  projectileSpeed: { label: "MUZZLE" },
  projectileLifetimeTicks: { label: "RANGE" },
  spread: { label: "SPREAD" },
};

/** Stats where a SMALLER resolved value is the better ship. Drives the colour, nothing else. */
const LOWER_IS_BETTER: ReadonlySet<StatKey> = new Set<StatKey>(["radius", "spread"]);

export interface ShopEffect {
  /** One modifier, in the player's units. */
  readonly text: string;
  /** Whether this reads as a gain. `HEAVY_SLUGS` carries one of each. */
  readonly good: boolean;
}

export interface ShopRow {
  readonly upgrade: UpgradeDef;
  readonly owned: boolean;
  /** Affordable AND not already owned — what the BUY button follows. */
  readonly buyable: boolean;
  readonly effects: readonly ShopEffect[];
  /**
   * What pressing this row's button does.
   *
   * A row is a TOGGLE: an owned upgrade sells back at full price, so the same control
   * that bought it puts it away. Derived here rather than in the view, because "which of
   * two actions does this button perform" is precisely the kind of decision that becomes
   * an untested `if` in a click handler — and the failure mode is a button that charges
   * you when you meant to refund.
   *
   * `"none"` is an unowned row you cannot afford: the button is shown (a price you cannot
   * meet is the information that makes a credit worth collecting) but does nothing.
   */
  readonly action: "buy" | "sell" | "none";
}

export interface ShopModel {
  readonly credits: number;
  readonly rows: readonly ShopRow[];
  /** True when every catalog entry is owned. The view shows a done note instead of a list. */
  readonly complete: boolean;
}

/** `1.25` -> `"+25%"`, `0.4` -> `"−60%"`. Rounded, because a shop is not a spec sheet. */
const percent = (factor: number): string => {
  const delta = Math.round((factor - 1) * 100);
  return `${delta >= 0 ? "+" : "−"}${Math.abs(delta)}%`;
};

/** `40` -> `"+40"`, `-1` -> `"−1"`. */
const signed = (value: number): string =>
  `${value >= 0 ? "+" : "−"}${Math.abs(Math.round(value * 100) / 100)}`;

export function describeModifier(modifier: StatModifier): ShopEffect {
  const stat = STATS[modifier.stat];
  // An inverted stat's FACTOR inverts too: ×0.8 ticks between shots is ×1.25 shots per
  // second. Only the multiplicative case can be inverted this way — an `add` of ticks
  // has no clean rate equivalent, so it is reported in the content's own units under a
  // label that says so, rather than converted approximately and silently.
  if (modifier.op === "mul") {
    const factor = stat.inverted ? 1 / modifier.value : modifier.value;
    const better = LOWER_IS_BETTER.has(modifier.stat) ? factor < 1 : factor > 1;
    return { text: `${percent(factor)} ${stat.label}`, good: better };
  }
  const label = stat.inverted ? "FIRE INTERVAL" : stat.label;
  const raw = modifier.value;
  // On an inverted stat, ADDING is worse; on a lower-is-better stat, adding is worse too.
  const better = stat.inverted || LOWER_IS_BETTER.has(modifier.stat) ? raw < 0 : raw > 0;
  return { text: `${signed(raw)} ${label}`, good: better };
}

/**
 * Builds the rows for a save.
 *
 * Sorted by COST and then by id — cheapest first, so the next thing a player can afford
 * is near the top, and the order never depends on how the catalog file happens to be
 * arranged. Owned rows stay in place rather than sinking to the bottom: a list that
 * reorders itself after a purchase makes the player re-find everything they were
 * comparing.
 */
export function shopModel(save: MetaSave, catalog: UpgradeCatalog): ShopModel {
  const rows = Object.values(catalog)
    .slice()
    .sort((a, b) => a.cost - b.cost || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
    .map((upgrade): ShopRow => {
      const owned = save.owned.includes(upgrade.id);
      const buyable = !owned && save.credits >= upgrade.cost;
      return {
        upgrade,
        owned,
        buyable,
        effects: upgrade.modifiers.map(describeModifier),
        action: owned ? "sell" : buyable ? "buy" : "none",
      };
    });

  return {
    credits: save.credits,
    rows,
    complete: rows.length > 0 && rows.every((row) => row.owned),
  };
}
