/**
 * What a world is FOR, which is the only thing that differs between the two.
 *
 * `attract` is the flight behind the title screen: the same rail, the same ship, the
 * same handling — and an empty sky. See `createRun` for why that is the whole change.
 */
export type RunMode = "run" | "attract";

/**
 * Whether a finished run's credits should be added to the meta-save.
 *
 * Pulled out of the frame loop and exported so it can be specced: the loop itself needs
 * a canvas, a renderer and a `requestAnimationFrame`, so a condition left inline there
 * is a condition no headless test can reach. Every one of the four answers below is a
 * decision somebody could reasonably make differently, which is the definition of
 * something that belongs in a spec rather than in a comment.
 */
export function shouldBank(
  mode: RunMode,
  outcome: RunOutcome,
  alreadyBanked: boolean,
  debug: DebugOverrides,
): boolean {
  // Once per run. Without this the loop banks the same credits on every frame a finished
  // run sits on screen — which is every frame until RETRY, so a player who read the
  // outcome screen for ten seconds would bank six hundred times over.
  if (alreadyBanked) return false;
  if (outcome === "running") return false;
  // ATTRACT flights never bank. Nothing in an empty sky drops a pickup, so the amount
  // would be zero anyway — but relying on that would make this correct by accident, and
  // it would stop being correct the day the attract world gets something in it.
  if (mode !== "run") return false;
  // A run built from non-default DEBUG values never banks. The menu can put the fire rate
  // up and the enemy health down, which is exactly what it is for and exactly what makes
  // the credits it earns meaningless. `isDefaultDebug` is already the predicate every
  // fold uses to decide whether it is on the shipped path, so this reuses that answer
  // rather than inventing a second one.
  return isDefaultDebug(debug);
}

/**
 * Everything a world is built from.
 *
 * An options object rather than positional parameters, and the change came with the
 * level: there were already five of them and the specs were reaching `mode` by writing
 * `createRun(1, undefined, undefined, "attract")`. A sixth — the most important one —
 * behind two more `undefined`s is a call site nobody can read.
 */
export interface RunOptions {
  readonly seed: number;
  /** The level to fly. `DEFAULT_LEVEL` when unstated. */
  readonly level?: LevelSpec;
  readonly difficulty?: DifficultyDef;
  readonly debug?: DebugOverrides;
  readonly mode?: RunMode;
  readonly loadout?: readonly UpgradeDef[];
}

/**
 * Builds a world seeded with a level and one ship on the rail.
 *
 * The level is an ARGUMENT rather than an import, which it was not until PARITY step 1:
 * `DEMO_LEVEL` was named directly in five places here, so "the level" was a
 * compile-time constant and a second one was unsayable. Progress, unlocking and a level
 * select all need this seam before they can exist, which is why the step that adds it
 * blocks the three after it.
 *
 * Exported for `__tests__/attract.spec.test.ts`, which pins the one property this file
 * is otherwise free to break silently: that the attract world cannot end a run.
 */
export function createRun(options: RunOptions): SimWorld {
  const {
    seed,
    level = DEFAULT_LEVEL,
    difficulty = DEFAULT_DIFFICULTY,
    debug = DEFAULT_DEBUG,
    mode = "run",
    loadout = [],
  } = options;
  const world = new SimWorld({ seed });
  world.rail = buildRailNetwork(level.rail);
  // The DEBUG fold wraps the difficulty fold everywhere below, and always in that
  // order: difficulty describes the game being played, debug is a tester overriding it,
  // and a tester who sets the rail to 2× means 2× whatever difficulty is selected. On
  // an untouched debug document every one of these calls returns its input unchanged —
  // by reference, not merely by value — so the shipped path is exactly what it was.
  world.railSpeed = applyDebugToRailSpeed(level.speed, debug);

  // The DIFFICULTY fold, alongside the loadout fold below and for the same reason: the
  // simulation is handed content that has already been scaled, and never learns that
  // scaling happened. Every scale is 1 on NORMAL, so this is an identity there and the
  // golden replays keep meaning what they meant.
  const enemies = applyDebugToEnemies(scaleEnemies(ENEMY_ORDER, difficulty), debug);
  world.enemyCatalog = enemies;
  // Enemies only — the player's weapon comes from resolved stats, not this catalog.
  // See the header of `sim/difficulty.ts`. The debug fold keeps that separation: it has
  // a player function and an enemy function, applied to the two catalogs respectively.
  world.weaponCatalog = applyDebugToEnemyWeapons(scaleEnemyWeapons(WEAPONS, difficulty), debug);

  // ── The attract flight ──────────────────────────────────────────────────────
  // The world behind the title screen is this same world with an EMPTY SKY: no ambient
  // field, no waves. That is all it takes, and the reason it is all it takes is worth
  // stating — the only two things in this game that can damage a ship are hazards and
  // enemies, so a world with neither cannot reach a losing outcome. The alternative
  // designs were worse in ways that are easy to miss: an invulnerable ship needs a flag
  // the simulation reads, which is a branch inside the determinism boundary; a paused
  // world needs a pause concept in the fixed-step loop, which is M5's business and the
  // reason the title gates attention rather than the clock in the first place.
  //
  // Everything else is untouched, deliberately. It is the real flight model on the real
  // rail, so what a player sees behind the menu is the game they are about to press
  // PLAY on — and they can fly it while they read.
  world.spawnConfig =
    mode === "attract"
      ? null
      : {
          leadDistance: LEAD_DIST,
          minDistance: SPAWN_MIN_DIST,
          viewConeAngle: SPAWN_VIEW_CONE,
          spread: level.ambient.spread,
          maxAlive: applyDebugToMaxAlive(level.ambient.maxAlive, debug),
          ratePerSecond: applyDebugToHazardRate(
            scaleHazardRate(level.ambient.ratePerSecond, difficulty),
            debug,
          ),
          table: AMBIENT_ROCKS,
        };
  // Resolved once at load, not per tick: `buildWaves` looks each enemy id up in the
  // catalog, resolves each wave's branch name to the courses it covers, and sorts by
  // trigger — which is what lets the runtime walk them with a cursor. Built from the
  // SCALED catalog so a wave's members carry the difficulty's numbers.
  world.waves = mode === "attract" ? [] : buildWaves(level.waves, enemies, world.rail);

  // The loadout fold, run ONCE here rather than anywhere inside the simulation. This is
  // the seam the whole progression layer plugs into, and it is now plugged in: the list
  // comes from the meta-save via `equipped()`, and nothing below this line changed to
  // make that work — which was the claim this seam existed to make good on. An empty
  // list still resolves to exactly the hull's authored numbers, so a new player and
  // every existing spec get the shipped ship.
  //
  // The ATTRACT flight is folded the same way, deliberately. What is behind the menu
  // should be the ship you are about to press PLAY on, and a player who has just bought
  // something has earned the right to watch it fly.
  // The PLAYER's catalog is widened here and the enemies' above, from two different
  // functions into two different places. That is what keeps "only the player's bolt
  // gets wider on EASY" a structural fact rather than a convention.
  world.statsBySlot.fill(
    resolveShipStats(
      applyDebugToShip(scaleShip(DEFAULT_SHIP, difficulty), debug),
      applyDebugToPlayerWeapons(scalePlayerWeapons(WEAPONS, difficulty), debug),
      loadout,
    ),
  );

  const frame: MutableRailFrame = {
    position: new Vec3(),
    tangent: new Vec3(),
    normal: new Vec3(),
    binormal: new Vec3(),
  };
  world.rail.courses[0]!.frameAt(0, frame);
  const facing = new Quat().setFromBasis(
    frame.tangent,
    frame.normal,
    new Vec3().crossVectors(frame.tangent, frame.normal).normalize(),
  );
  world.spawnShip(0, frame.position.clone(), facing);
  return world;
}

export interface GameHandle {
  readonly world: SimWorld;
  readonly clock: FixedStepClock;
  readonly view: View;
  readonly controls: Controls;
  /** The level the current run is flying. Fixed for the session — see `GameOptions`. */
  readonly level: LevelSpec;
  /** The difficulty the current run is being played on. */
  readonly difficulty: DifficultyDef;
  /** Starts a new run, optionally on a different difficulty. */
  setDifficulty(difficulty: DifficultyDef): void;
  /** Changes stick sensitivity. Applies live — no restart. */
  setSensitivity(sensitivity: StickSensitivity): void;
  /** Whether the world behind the screen is the empty attract flight or a real run. */
  readonly mode: RunMode;
  /**
   * Leaves the attract flight and starts a real run. What PLAY does.
   *
   * Separate from `restart` because they answer different questions: `restart` rebuilds
   * whatever kind of world is up (RETRY on a finished run rebuilds a run; a debug knob
   * turned behind the title rebuilds the attract flight), and this one CHANGES which
   * kind it is. Collapsing them would mean PLAY and RETRY shared a definition that has
   * to be right for both.
   */
  startRun(): void;
  /**
   * Leaves a finished run for the attract flight. What QUIT does.
   *
   * The exact inverse of `startRun`, and it exists for the same reason that one does:
   * `restart` rebuilds whichever KIND of world is up, and this changes which kind. The
   * caller is then responsible for putting the title screen back — the handle knows
   * nothing about that screen, which is `boot`'s.
   */
  quitToTitle(): void;
  /** Stick sensitivity in force. Read when the title screen is rebuilt after a QUIT. */
  readonly sensitivity: StickSensitivity;
  /** The upgrades the current run was built from. */
  readonly loadout: readonly UpgradeDef[];
  /**
   * Changes the upgrades the NEXT run will be folded from. Rebuilds nothing.
   *
   * Upgrades are still baked into resolved stats when a world is built, so this cannot
   * affect the run on screen — but unlike `setDifficulty` and `setDebugOverrides` it does
   * not force one either. The shop opens over the title and over the outcome screen, and
   * rebuilding under the second one destroys the very screen the player is standing on.
   * See the implementation for the whole of that argument.
   */
  setLoadout(loadout: readonly UpgradeDef[]): void;
  /** The hidden overrides the current run was built from. */
  readonly debugOverrides: DebugOverrides;
  /**
   * Changes the hidden overrides, which necessarily means a new run.
   *
   * Same shape as `setDifficulty` and for the same reason — the values are folded into
   * content when a world is built — but it does NOT persist the document here, because
   * the debug document also carries the unlock flag, which this handle knows nothing
   * about. `boot` owns that file.
   */
  setDebugOverrides(debug: DebugOverrides): void;
  /**
   * Shows or hides the debug rail readout and the fork markers.
   *
   * A setter rather than a boot-time option alone, because the debug flag can be turned
   * on MID-SESSION with the Konami code — and a readout that only appeared on the next
   * reload would be missed by the person who just unlocked it.
   */
  setDebugReadout(visible: boolean): void;
  stop(): void;
  restart(): void;
  readonly recentEvents: readonly SimEvent[];
}

/**
 * Everything `startGame` needs, as a record rather than a positional list.
 *
 * It was seven positional parameters and the loadout would have made it nine, at which
 * point the call site is a row of values whose meaning is their index. Every field is
 * optional and defaulted, so the shape is also what the smoke and the specs would build
 * against if they ever construct a game directly.
 */
export interface GameOptions {
  readonly seed?: number;
  readonly assets?: AssetBundle;
  /**
   * The level every world this handle builds is flown on. `DEFAULT_LEVEL` when unstated.
   *
   * Fixed for the life of the handle, deliberately: there is no setter, because
   * CHANGING level mid-session is a progression question — which levels are unlocked,
   * what a player has completed, where they choose one — and that is PARITY step 2 and
   * step 3. `boot` reads `?level=` once and passes it in.
   */
  readonly level?: LevelSpec;
  /**
   * Whether the debug rail readout and the fork markers are on. Defaults to false.
   *
   * Separate from `debug`, which is the OVERRIDES — content multipliers that change the
   * run. This changes nothing about the world, only what is drawn over it, which is why
   * it restarts nothing and does not disqualify a run from banking its credits.
   */
  readonly showDebugReadout?: boolean;
  readonly difficulty?: DifficultyDef;
  readonly sensitivity?: StickSensitivity;
  readonly debug?: DebugOverrides;
  readonly mode?: RunMode;
  /** Upgrades the first run is folded from. From the meta-save; empty for a new player. */
  readonly loadout?: readonly UpgradeDef[];
  /**
   * Called once when a real run reaches a terminal outcome, with the credits it earned.
   *
   * The handle raises the fact and banks nothing: the meta-save is `boot`'s, the same
   * way the debug document is. Two conditions are already applied before it fires, and
   * both are stated at the call site.
   */
  readonly onRunFinished?: (credits: number) => void;
  /**
   * Opens the shop from the outcome screen. The HUD's button is only mounted when set.
   *
   * A thunk rather than the `Shop` itself, because the shop is built AFTER the game —
   * it renders the meta-save, which `onRunFinished` writes to — so passing the object
   * would be a cycle. Calling through a closure resolves it at press time, by which
   * point both exist.
   */
  readonly onShop?: () => void;
  /**
   * Mounts QUIT on the outcome screen and is called when it is pressed.
   *
   * A thunk for the same reason `onShop` is: putting the title screen back is `boot`'s
   * job, and the screen is built after the game it reads its state from.
   */
  readonly onQuit?: () => void;
}

export function startGame(canvas: HTMLCanvasElement, options: GameOptions = {}): GameHandle {
  const seed = options.seed ?? 1;
  const level = options.level ?? DEFAULT_LEVEL;
  let showDebugReadout = options.showDebugReadout ?? false;
  const clock = new FixedStepClock({ hz: 60 });
  const transport = new LocalTransport();
  const controls = createControls(window);
  const view = createView(canvas, options.assets);

  let difficulty = options.difficulty ?? DEFAULT_DIFFICULTY;
  let settings: Settings = {
    difficulty,
    sensitivity: options.sensitivity ?? DEFAULT_SENSITIVITY,
  };
  controls.setSensitivity(settings.sensitivity);
  let debugOverrides = options.debug ?? DEFAULT_DEBUG;
  let mode: RunMode = options.mode ?? "run";
  let loadout: readonly UpgradeDef[] = options.loadout ?? [];
  const build = (): SimWorld =>
    createRun({ seed, level, difficulty, debug: debugOverrides, mode, loadout });
  let world = build();
  // Whether THIS run's credits have already been banked. Reset by every rebuild, so a
  // RETRY earns again and a finished run left on screen banks exactly once however many
  // frames it sits there.
  let banked = false;

  /**
   * Rebuilds the run from scratch.
   *
   * Declared before the HUD so the retry button can be wired to it directly, and
   * shared with the handle's own `restart` so there is exactly one definition of what
   * starting again means.
   */
  const restart = (): void => {
    world = build();
    recentEvents = [];
    banked = false;
    clock.reset();
    // The new world reuses entity handles from zero, so a capture from the old one
    // would be mistaken for this entity's previous transform for one frame.
    view.interpolator.reset();
  };

  /**
   * Rebuilds the run, unless the player is on the outcome screen deciding what to do.
   *
   * The rule, stated once because two menus need it: **a rebuild replaces the world you
   * are looking at, and on a finished run what you are looking at is a CHOICE** — RETRY,
   * UPGRADES, QUIT. Taking that away, from underneath a modal the player opened, reads as
   * the game starting a run they never asked for.
   *
   * Deferring costs nothing, because every exit from the outcome screen builds a world
   * anyway and all of them read the current values when they do.
   *
   * `setDifficulty` deliberately does NOT use this: its picker on that screen confirms
   * first, and the confirmation says it restarts from the beginning. A player who agreed
   * to that should get it.
   */
  const restartUnlessChoosing = (): void => {
    if (world.outcome === "running") restart();
  };

  /**
   * Changes difficulty, which necessarily means a new run.
   *
   * There is no way to apply a difficulty to a run in progress and no attempt to
   * pretend otherwise: the scaled values are baked into the world's catalogs and the
   * ship's resolved stats when the run is built. That is the price of keeping the
   * simulation ignorant of difficulty, and it is why both pickers restart rather than
   * offering to switch mid-flight.
   */
  const setDifficulty = (next: DifficultyDef): void => {
    difficulty = next;
    settings = { ...settings, difficulty: next };
    saveSettings(settings);
    hud.setDifficulty(next);
    restart();
  };

  /**
   * Changes stick sensitivity, which does NOT restart.
   *
   * The contrast with `setDifficulty` is the whole reason settings did not need a
   * pause: difficulty is baked into the world's catalogs when a run is built, so
   * changing it means building another one. Sensitivity is a `ui/` number that decides
   * how a thumb's travel maps to an axis, and the simulation never sees it — so it
   * takes effect on the next sampled tick with nothing rebuilt and nothing lost.
   */
  const setSensitivity = (next: StickSensitivity): void => {
    settings = { ...settings, sensitivity: next };
    saveSettings(settings);
    controls.setSensitivity(next);
    hud.setSensitivity(next);
  };

  /**
   * Changes the hidden overrides, and builds a new run to see them in — unless the
   * player is standing on the outcome screen.
   *
   * The values are baked into the world's catalogs and the ship's resolved stats when
   * the run is built, so there is no way to apply one mid-flight that does not also put
   * a mutating second path into the same numbers. Mid-run a tester turning a knob is
   * asking to see the difference NOW, and a clean run at the new value is the whole
   * purpose of the control.
   *
   * A FINISHED run is the exception, and it is the same lesson the shop taught: the
   * outcome screen is not a run, it is a place where the player is choosing what to do
   * next. Rebuilding under it makes that choice for them and throws away RETRY and QUIT
   * on the way. The new values are still stored, so whichever they pick is built with
   * them.
   */
  const setDebugOverrides = (next: DebugOverrides): void => {
    debugOverrides = next;
    restartUnlessChoosing();
  };

  /**
   * Changes the equipped upgrades. Takes effect on the NEXT run, and rebuilds nothing.
   *
   * ── This used to restart, and that was a bug ─────────────────────────────────
   *
   * The original reasoning was that rebuilding the attract flight on a purchase was "not
   * a side effect to be worked around but the point" — the world behind the title should
   * be the ship you are about to fly. That is a fair thing to want and it was still
   * wrong, because the shop is reachable from TWO screens and the argument only ever
   * considered one of them.
   *
   * From the outcome screen a rebuild is destructive: the new world's outcome is
   * `running`, so the game-over overlay the player opened the shop FROM is torn down
   * underneath the modal. Closing the shop then revealed a run already in progress —
   * they never chose RETRY, and RETRY and QUIT were both gone. Buying something silently
   * committed you to a flight.
   *
   * Deferring is also what the shop has been telling the player all along: every row is
   * captioned "Applies to your next run." The code now says the same thing. Every path
   * that starts a world — PLAY, RETRY, QUIT — reads `loadout` at `createRun` time, so
   * the next run is built with it whichever of the three the player picks.
   *
   * Contrast `setDebugOverrides`, which still rebuilds immediately and should: a tester
   * turning a knob is asking to see the difference NOW, and that is the entire purpose
   * of the control. The asymmetry is between a tool for inspecting the current run and a
   * menu that promises to change the next one.
   */
  const setLoadout = (next: readonly UpgradeDef[]): void => {
    loadout = next;
  };

  /**
   * Leaves the attract flight for a real one.
   *
   * The HUD comes back with it: behind the title it describes a run nobody is playing —
   * a full hull bar, and counters that can only ever read zero.
   */
  const startRun = (): void => {
    mode = "run";
    hud.setVisible(true);
    restart();
  };

  /**
   * Back to the empty sky behind the title.
   *
   * The HUD goes with it, exactly as it arrives with `startRun`: behind the title it
   * describes a run nobody is playing. Rebuilding as an attract world also clears the
   * outcome overlay for free — the new world's outcome is `running`, so the next
   * `hud.update` hides it without anything here having to know it was up.
   */
  const quitToTitle = (): void => {
    mode = "attract";
    hud.setVisible(false);
    restart();
  };

  // Four digits of the commit, bottom right. Mounted here rather than in `shell.html`
  // so it carries the SHA the BUNDLE was built from — a tag written into the page
  // template would date the template, and the two are deployed by the same step but
  // are not the same artifact.
  const version = createVersionTag();

  const hud: Hud = createHud(document.body, {
    onRestart: restart,
    // Hidden behind the title, where it would describe a run nobody is playing: a full
    // hull bar and four counters that can only read zero.
    visible: mode === "run",
    difficulty,
    onDifficultyChange: setDifficulty,
    sensitivity: settings.sensitivity,
    onSensitivityChange: setSensitivity,
    // Spread rather than assigned: under `exactOptionalPropertyTypes` an explicit
    // `undefined` is not the same as an absent field, and the HUD mounts its button on
    // the field being PRESENT.
    ...(options.onShop ? { onShop: options.onShop } : {}),
    ...(options.onQuit ? { onQuit: options.onQuit } : {}),
  });
  // Everything that has to move when the on-screen controls appear, in one place.
  // Subscribing rather than reading `touchActive` once is what handles the first touch
  // on a device the boot sniff called a desktop: `onTouchActive` fires immediately when
  // the controls are already up, and later if a finger arrives. The title screen adds
  // its own listener in `boot` — it does not exist yet here.
  controls.onTouchActive(() => {
    version.setTouchActive(true);
    hud.setSensitivityVisible(true);
  });

  // The other half of the debug-overlay seam. `showDebugReadout` alone only reaches the
  // HUD, which reads it every frame; the view is told ONCE, so a boot that arrives with
  // the flag already set — `?debug=1`, or the unlock persisted in `localStorage` — put
  // the readout on screen and left the ring and the ghost courses switched off. Setting
  // it here rather than only in `setDebugReadout` is what makes the two halves agree.
  view.setDebugMarkers(showDebugReadout);

  const inputs: (InputFrame | undefined)[] = new Array(MAX_PLAYERS).fill(undefined);
  let recentEvents: SimEvent[] = [];
  let running = true;
  let previous = 0;
  let raf = 0;

  // Three sources, because on a phone `resize` alone is not enough. Rotating fires
  // `orientationchange` before `resize` reports the new dimensions on iOS, and the
  // browser chrome sliding away as you scroll-lock changes the VISUAL viewport without
  // always firing a window resize — which leaves the canvas the height of the page as
  // it was when the URL bar was still showing, and a band of background along the
  // bottom. Coalescing into one rAF keeps the triple subscription from costing three
  // renderer resizes per rotation.
  let resizePending = 0;
  const applyResize = () => {
    resizePending = 0;
    view.resize(window.innerWidth, window.innerHeight);
    controls.resize();
  };
  const resize = () => {
    if (resizePending) return;
    resizePending = requestAnimationFrame(applyResize);
  };
  view.resize(window.innerWidth, window.innerHeight);
  window.addEventListener("resize", resize);
  window.addEventListener("orientationchange", resize);
  window.visualViewport?.addEventListener("resize", resize);

  const frame = (now: number) => {
    if (!running) return;
    raf = requestAnimationFrame(frame);

    const deltaSeconds = previous === 0 ? 0 : (now - previous) / 1000;
    previous = now;

    for (let step = 0, steps = clock.advance(deltaSeconds); step < steps; step++) {
      // Sample -> encode -> send -> receive -> decode -> apply. In multiplayer the
      // middle of that chain becomes a data channel; nothing on either end changes.
      transport.send(HOST_PEER, encodeInputFrames([controls.sample(world.tick)]), "unreliable");

      inputs.fill(undefined);
      for (const message of transport.receive()) {
        for (const decoded of decodeInputFrames(message.data)) {
          inputs[slotForPeer(message.from)] = decoded;
        }
      }

      // Capture BEFORE stepping, inside the loop: "previous" must mean one tick back
      // even when several ticks run between two rendered frames.
      view.interpolator.capture(world);
      stepSim(world, inputs as TickInputs);
    }

    // The attract flight is endless: the demo rail is finite, so a title screen left up
    // long enough reaches the end and the world's outcome becomes "won" — an outcome
    // screen behind a menu, which is exactly the thing this mode exists to avoid.
    // Rebuilding is the whole of the loop; there is nothing to preserve.
    if (mode === "attract" && world.outcome !== "running") restart();

    // A finished run hands its credits to the meta-save exactly once — on a LOSS as well
    // as a win, deliberately: what the player collected, they collected, and a rail
    // shooter that pays nothing for a run that ended two thirds of the way down makes the
    // third attempt at a hard stop feel like punishment rather than progress. The rest of
    // the conditions, and why each one is there, live in `shouldBank`.
    if (shouldBank(mode, world.outcome, banked, debugOverrides)) {
      banked = true;
      options.onRunFinished?.(world.credits);
    }

    const drained = world.events.drain();
    if (drained.length > 0) recentEvents = recentEvents.concat(drained).slice(-256);

    // The frame's events go to the renderer as well as to the log: a rock breaking is
    // a MOMENT, and the debris burst it throws cannot be derived from the state left
    // behind — by then the rock is gone.
    view.render(world, clock.alpha, drained);
    // After the render, and from the SAME world the frame drew: reading it before
    // would show the player the state of the previous frame, which is visible on the
    // hull bar the moment anything hits them.
    hud.update(hudModel(world, 0));
    // Only while the flag is on: `railReadout` evaluates a selector and walks the fork
    // list. That is nothing on its own, and it is also nothing the shipped path should
    // pay for sixty times a second.
    hud.setRailReadout(showDebugReadout ? railReadout(world) : null);
    // Once per RENDERED frame rather than per tick: the stick's position is a display
    // concern, and several ticks can run between two frames.
    controls.draw();
  };

  raf = requestAnimationFrame(frame);

  return {
    get world() {
      return world;
    },
    clock,
    view,
    controls,
    level,
    get difficulty() {
      return difficulty;
    },
    setDifficulty,
    setSensitivity,
    get mode() {
      return mode;
    },
    startRun,
    quitToTitle,
    get sensitivity() {
      return settings.sensitivity;
    },
    get loadout() {
      return loadout;
    },
    setLoadout,
    get debugOverrides() {
      return debugOverrides;
    },
    setDebugOverrides,
    setDebugReadout(visible) {
      showDebugReadout = visible;
      view.setDebugMarkers(visible);
    },
    get recentEvents() {
      return recentEvents;
    },
    restart,
    stop() {
      running = false;
      cancelAnimationFrame(raf);
      if (resizePending) cancelAnimationFrame(resizePending);
      controls.dispose();
      window.removeEventListener("resize", resize);
      window.removeEventListener("orientationchange", resize);
      window.visualViewport?.removeEventListener("resize", resize);
      transport.close();
      hud.dispose();
      version.dispose();
      view.dispose();
    },
  };
}

/** Peer-to-slot mapping. Trivial today; the lobby owns it from M5. */
const slotForPeer = (peer: number): number => peer;

// ── Debug surface ─────────────────────────────────────────────────────────────
// The previous game exposed an ad-hoc `window.__sunWeasel` that the Playwright
// smokes reached into, and it grew whatever each test happened to need. This one is
// declared as a type up front, so the smoke contract is explicit and typechecked.

export interface DebugSurface {
  readonly game: GameHandle;
  /** Ids of assets that failed to load. Empty on a clean boot. */
  missingAssets(): readonly string[];
  fingerprint(): string;
  tick(): number;
  entityCount(): number;
  outcome(): string;
  shipPosition(slot: number): [number, number, number] | null;
  cameraPosition(): [number, number, number];
  viewMode(slot: number): string | null;
  aliveHazards(): number;
  aliveEnemies(): number;
  alivePickups(): number;
  credits(): number;
  /** Waves released so far, and how many the level authors in total. */
  waveProgress(): [number, number];
  /**
   * Instances drawn in each projectile bucket, `[player, enemy]`.
   *
   * The pair matters rather than either alone: a smoke asserting only that bolts are
   * drawn cannot tell whether hostile fire ever reaches the screen, which is the half
   * a player has to react to.
   */
  projectileCounts(): [number, number];
  /** Draw calls in the last rendered frame — proof the renderer is actually drawing. */
  drawCalls(): number;
  /**
   * Chips currently in the air from a break-up.
   *
   * Cosmetic and view-only, which is exactly why it is worth a smoke: nothing in the
   * simulation would notice if the debris pool silently stopped drawing.
   */
  debrisCount(): number;
  /** Chips thrown since boot, monotonic — what a smoke can compare across an event. */
  debrisSpawned(): number;
  /**
   * Instances drawn per hazard variant bucket.
   *
   * Exposed so the smoke can assert that shape VARIETY actually reaches the screen.
   * Draw-call count alone cannot: the buckets exist whether or not anything lands in
   * more than one of them, so a variant that was always 0 would look identical.
   */
  hazardVariantCounts(): number[];
  /**
   * Whether the on-screen touch controls are up.
   *
   * The mobile smoke forces them on with `?touch=1` and asserts this rather than
   * asserting the sniff itself — a headless Chromium in a phone-shaped viewport is not
   * a touchscreen, so the sniff is exactly the part a browser cannot honestly test.
   */
  touchActive(): boolean;
  /**
   * The build tag in the corner, e.g. `#f901`.
   *
   * Exposed so a smoke can assert the page is running the build it just built rather
   * than a cached one — the failure this tag exists to make visible to a human.
   */
  buildVersion(): string;
  /** The hidden overrides the current run was built from. */
  debugOverrides(): DebugOverrides;
  /** Whether the debug menu is on screen. */
  debugMenuOpen(): boolean;
  /** Whether the shop is on screen. */
  shopOpen(): boolean;
  /**
   * Banked credits and owned upgrade ids — the meta-save as it stands.
   *
   * The banked balance is what a smoke can compare across a run ending, which is the one
   * assertion the headless specs cannot make: `bank` is pure and tested directly, but
   * whether anything actually CALLS it when a run finishes is a property of the frame
   * loop.
   */
  meta(): { credits: number; owned: readonly string[] };
  /** Ids of the upgrades the current run was folded from. */
  loadout(): readonly string[];
  /** Id of the difficulty the current run is on. */
  difficulty(): string;
  /**
   * The party's rail state: current course, the next fork, and which way it is leaning.
   *
   * The same model the debug HUD block renders. Exposed so a smoke can assert the fork
   * state without reading pixels — the role `waveProgress()` already plays, and the one
   * a marker drawn inside a canvas cannot play for itself.
   */
  railReadout(): RailReadout;
  /**
   * Whether the fork overlay's commit ring is drawn.
   *
   * A smoke cannot read a line's colour out of a canvas, but drawn versus not drawn is
   * the half that broke: the overlay shipped enabled on one side of its seam, so the
   * readout appeared and the ring never did.
   */
  forkMarkerVisible(): boolean;
  /**
   * Id of the level the current run is flying.
   *
   * Exposed for the one assertion no headless spec can make: that `?level=` reaches the
   * game. `levelFromSearch` is pure and specced, `createRun` is specced against the
   * level it is handed — and neither notices if `boot` forgets to connect them, which
   * is exactly the seam this step exists to build.
   */
  level(): string;
  /** `"attract"` while the title screen's empty flight is up, `"run"` once PLAY is pressed. */
  mode(): string;
  /**
   * Angle between a ship's reticle and rail-forward, in radians.
   *
   * RAIL-RELATIVE on purpose. The reticle's world position moves with the ship and
   * swings with every bend in the rail, so a world-space measurement of "has the
   * player turned" mostly measures the level. This is the quantity the aim cone
   * clamps, and the one a smoke can compare across a slide and a drag.
   */
  aimOffset(slot: number): number | null;
  reticleVisible(): boolean;
  reticlePosition(): [number, number, number] | null;
  /** World point to viewport pixels, mirroring the old `__sunWeaselApp.project`. */
  project(point: [number, number, number]): [number, number, number];
}

declare global {
  interface Window {
    __sw?: DebugSurface;
  }
}

if (typeof window !== "undefined") {
  const canvas = document.getElementById("game") as HTMLCanvasElement | null;
  if (!canvas) throw new Error('no <canvas id="game"> on the page');

  void boot(canvas);
}

/**
 * Loads the manifest behind a loading screen, then starts the game.
 *
 * `window.__sw` is published only once the game exists, so anything reaching for it —
 * the smoke, the console — gets a whole handle or nothing, never a half-built one.
 * The smoke waits for it rather than assuming a fixed settle time.
 */
async function boot(canvas: HTMLCanvasElement): Promise<void> {
  const loading = createLoadingScreen();
  const assets = await loadAssets(ASSETS, browserFetcher, (progress) => {
    loading.setProgress(progress.fraction);
    if (progress.id) loading.setNote(progress.id);
  });

  if (assets.missing.length > 0) {
    // Reported rather than fatal. The run starts without them; without this line the
    // only symptom would be something quietly looking wrong with no clue which file.
    loading.setNote(`missing: ${assets.missing.join(", ")}`, true);
    console.warn(`[sun-weasel] assets failed to load: ${assets.missing.join(", ")}`);
  }
  loading.dismiss();

  // URL, then whatever was chosen last, then NORMAL. Read BEFORE the game is built so
  // the first run of a session is already on the player's difficulty rather than
  // starting on NORMAL and restarting itself.
  const stored = loadSettings();
  // Read before the game is built for the same reason the settings are: the first run
  // of a session should already be on the tester's numbers rather than starting on the
  // authored ones and restarting itself the moment the menu is opened.
  let debugDocument = loadDebug();
  // The meta-save, read once here for the same reason the other two documents are: the
  // first world of a session should already carry what the player owns rather than being
  // built bare and rebuilt the moment anything reads the save.
  let meta = loadMeta(UPGRADES);
  // `boot` owns the meta-save the same way it owns the debug document — the game handle
  // raises facts, this decides what they mean and what gets written.
  //
  // `shop` is declared BELOW and referenced here, which works because nothing in this
  // closure runs during boot: a run cannot finish, and no button can be pressed, before
  // this function returns. Reaching it early would be a `ReferenceError` rather than a
  // silent no-op, which is the failure mode worth having.
  //
  // Every mutation of the save goes through `applyToSave` — banking, granting, buying,
  // selling — because each has the same three obligations (persist, redraw, refold) and
  // four copies of that would eventually be three copies plus one with a step missing.
  // `bank`, `purchase` and `sell` all return the SAME OBJECT when they decline, so the
  // identity check doubles as the "nothing happened" guard: a press on a button that
  // should not have been live costs no write and no rebuild.
  const applyToSave = (next: MetaSave): void => {
    if (next === meta) return;
    meta = next;
    saveMeta(meta);
    shop.set(meta);
    // Hands over the list the NEXT run is folded from. Safe to call unconditionally now
    // that it rebuilds nothing — when it restarted, this line was what tore the outcome
    // screen out from under an open shop, and it did it for banking and granting too.
    game.setLoadout(equipped(meta, UPGRADES));
  };

  /** Banks a finished run's credits. Also what GRANT calls. */
  const bankRun = (credits: number): void => applyToSave(bank(meta, credits));

  // Started in ATTRACT mode: the world behind the title screen is the same flight with
  // an empty sky, so the menu has something moving behind it and nothing that can end
  // a run the player has not started. PLAY swaps it for a real one.
  const game = startGame(canvas, {
    seed: 1,
    assets,
    // Read once, here, and fixed for the session. There is no way to change level from
    // inside the game yet, and deliberately so — see `GameOptions.level`.
    level: levelFromSearch(window.location.search),
    // The debug flag as it stands at boot. `unlockDebug` below turns it on for a
    // session that types the code rather than arriving with `?debug=1`.
    showDebugReadout: debugDocument.unlocked,
    difficulty: stored.difficulty,
    sensitivity: stored.sensitivity,
    debug: debugDocument.overrides,
    mode: "attract",
    loadout: equipped(meta, UPGRADES),
    onRunFinished: bankRun,
    onShop: () => shop.open(),
    // Two steps, and they belong to different owners: the handle swaps the world back to
    // an attract flight, and `boot` puts the screen back over it.
    onQuit: () => {
      game.quitToTitle();
      showTitle();
    },
  });

  // One shop, opened by both screens. See the header of `shopView.ts` for why this is a
  // modal mounted once rather than a panel mounted twice like the difficulty picker.
  const shop: Shop = createShop({
    initial: meta,
    catalog: UPGRADES,
    onPurchase: (upgrade) => applyToSave(purchase(meta, upgrade)),
    onSell: (upgrade) => applyToSave(sell(meta, upgrade)),
  });

  // The debug menu is mounted whether or not it has been unlocked — it costs one hidden
  // element, and mounting it lazily would mean the backtick shortcut and the title
  // button had two different construction paths to keep in step.
  const debugMenu = createDebugMenu({
    initial: debugDocument.overrides,
    onChange: (overrides) => {
      // Persisted HERE rather than inside `setDebugOverrides`, because the document
      // also carries the unlock flag and the game handle knows nothing about it.
      debugDocument = { ...debugDocument, overrides };
      saveDebug(debugDocument);
      game.setDebugOverrides(overrides);
    },
    // Reuses `bankRun` rather than reaching into the save itself: granting is banking
    // with a different source, and two paths that both add credits would be two places to
    // get the persist-and-refresh wrong. Note this does NOT restart the run — credits
    // are not folded into anything, which is exactly what separates them from every knob
    // above.
    onGrantCredits: bankRun,
  });

  const unlockDebug = () => {
    if (debugDocument.unlocked) return;
    debugDocument = { ...debugDocument, unlocked: true };
    saveDebug(debugDocument);
    // Immediately, not on the next reload: whoever just typed the code is looking at
    // the screen now, and a readout that waited would be missed by the one person who
    // asked for it.
    game.setDebugReadout(true);
  };

  // Once unlocked, backtick opens the menu from anywhere — including mid-run, which is
  // where a tuning value is actually judged. The title screen's button is the way in
  // the first time; this is the way back in without reloading.
  window.addEventListener("keydown", (event) => {
    if (event.code !== "Backquote" || !debugDocument.unlocked) return;
    event.preventDefault();
    debugMenu.toggle();
  });

  // The title gates attention, not the clock — the world is already ticking behind it,
  // so `window.__sw` below is live whether or not PLAY has been pressed. When PLAY is,
  // the run restarts so the player gets a clean one rather than however many seconds
  // elapsed while they were reading the screen.
  /**
   * Puts the title screen up. Called once at boot, and again on every QUIT.
   *
   * A function rather than a value because the screen DISPOSES ITSELF on PLAY — it is
   * torn down, not hidden — so coming back from a finished run means building another
   * one. It reads the CURRENT difficulty and sensitivity off the handle rather than the
   * boot-time stored ones, or a player who changed either from the outcome screen would
   * find the title disagreeing with the run they just flew.
   */
  const showTitle = (): void => {
    const title = createTitleScreen({
      initialDifficulty: game.difficulty,
      initialSensitivity: game.sensitivity,
      onDifficultyChange: (difficulty) => game.setDifficulty(difficulty),
      onSensitivityChange: (sensitivity) => game.setSensitivity(sensitivity),
      onPlay: () => game.startRun(),
      debugUnlocked: debugDocument.unlocked,
      onDebugUnlock: unlockDebug,
      onDebug: () => debugMenu.open(),
      onShop: () => shop.open(),
    });
    // The sliders scale an on-screen stick and nothing else, so on a keyboard they are
    // two controls that visibly do not work on the first screen anyone sees. Fires
    // straight away on a phone; on a touchscreen laptop it fires when a finger arrives,
    // at the same moment the stick does.
    //
    // Re-subscribed per screen. `onTouchActive` fires immediately when the controls are
    // already up, so a title rebuilt after a QUIT on a phone gets its sliders at once
    // rather than waiting for a finger that has already arrived.
    game.controls.onTouchActive(() => title.setSensitivityVisible(true));
  };
  showTitle();

  const scratch = new Vec3();
  const flight = createFlightState();

  window.__sw = {
    game,
    missingAssets: () => assets.missing,
    fingerprint: () => game.world.fingerprint(),
    tick: () => game.world.tick,
    entityCount: () => game.world.ecs.entityCount,
    outcome: () => game.world.outcome,
    aliveHazards: () => game.world.components.hazard.count,
    aliveEnemies: () => game.world.components.enemy.count,
    alivePickups: () => game.world.components.pickup.count,
    credits: () => game.world.credits,
    waveProgress: () => [game.world.nextWave, game.world.waves.length],
    level: () => game.level.id,
    railReadout: () => railReadout(game.world),
    forkMarkerVisible: () => game.view.debugMarkerVisible(),
    projectileCounts: () => [game.view.field.projectiles.count, game.view.field.hostileProjectiles.count],

    shipPosition: (slot) => {
      const entity = game.world.shipBySlot[slot];
      if (entity === undefined || !game.world.readPosition(entity, scratch)) return null;
      return scratch.toArray();
    },

    cameraPosition: () => {
      const p = game.view.camera.position;
      return [p.x, p.y, p.z];
    },

    viewMode: (slot) => {
      const entity = game.world.shipBySlot[slot];
      if (entity === undefined || !readFlight(game.world, entity, flight)) return null;
      return flight.viewMode;
    },

    touchActive: () => game.controls.touchActive,
    buildVersion: () => buildTag(injectedSha()),
    debugOverrides: () => game.debugOverrides,
    debugMenuOpen: () => debugMenu.isOpen,
    shopOpen: () => shop.isOpen,
    meta: () => ({ credits: meta.credits, owned: meta.owned }),
    loadout: () => game.loadout.map((upgrade) => upgrade.id),
    difficulty: () => game.difficulty.id,
    mode: () => game.mode,

    aimOffset: (slot) => {
      const entity = game.world.shipBySlot[slot];
      const rail = game.world.rail;
      if (entity === undefined || !rail) return null;
      if (!readFlight(game.world, entity, flight)) return null;
      const course = rail.courses[game.world.courseId];
      if (!course) return null;
      course.tangentAt(game.world.railS, scratch);
      const cos = Math.max(-1, Math.min(1, flight.aim.dot(scratch)));
      return Math.acos(cos);
    },
    drawCalls: () => game.view.renderer.info.render.calls,
    hazardVariantCounts: () => game.view.field.hazardMeshes.map((mesh) => mesh.count),
    debrisCount: () => game.view.field.debris.activeCount(),
    debrisSpawned: () => game.view.field.debris.spawnedTotal(),
    reticleVisible: () => game.view.reticle.mesh.visible,
    reticlePosition: () => {
      const p = game.view.reticle.mesh.position;
      return [p.x, p.y, p.z];
    },

    project: ([x, y, z]) => game.view.project(scratch.set(x, y, z)),
  };

  console.info(`[sun-weasel] booted at ${game.clock.hz} Hz — window.__sw is available`);
}
