// The cheat sequence, as a pure matcher.
//
// ↑↑↓↓←→←→BA on the title screen reveals the debug menu. The old game had the same
// code on its overworld (`pewpew/sunweasel/overworld.js`) where it unlocked every
// world, and keeping the gesture is deliberate: whoever is testing this already knows
// it, and a hidden feature that needs to be documented is not hidden, it is just
// undiscoverable.
//
// A matcher rather than a listener, for the reason every other `ui/` model here is
// split that way: "which keys, in which order, with what happens on a wrong one" is
// arithmetic over a string of inputs, and the DOM half has nothing left to decide.

/** ↑ ↑ ↓ ↓ ← → ← → B A, as `KeyboardEvent.code` values. */
export const KONAMI: readonly string[] = [
  "ArrowUp",
  "ArrowUp",
  "ArrowDown",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "ArrowLeft",
  "ArrowRight",
  "KeyB",
  "KeyA",
];

/**
 * Tracks progress through a key sequence.
 *
 * Stateful because the whole question is stateful, but the state is one integer and
 * nothing here touches an event or an element.
 */
export class SequenceMatcher {
  private index = 0;

  constructor(private readonly sequence: readonly string[] = KONAMI) {}

  /** How many keys of the sequence have matched so far. Exposed for the spec. */
  get progress(): number {
    return this.index;
  }

  /** Forgets any partial progress. */
  reset(): void {
    this.index = 0;
  }

  /**
   * Feeds one key. Returns true on the key that COMPLETES the sequence.
   *
   * A wrong key restarts — except when the wrong key is itself the first key of the
   * sequence, which then counts as a fresh start rather than being thrown away. That
   * case is not hypothetical here: the code begins ↑↑, so a third ↑ before the ↓↓ has
   * to leave two ups matched rather than zero, or the sequence becomes impossible to
   * enter for anyone who taps one key too many.
   */
  push(code: string): boolean {
    if (code === this.sequence[this.index]) {
      this.index++;
    } else {
      this.index = code === this.sequence[0] ? 1 : 0;
    }
    if (this.index < this.sequence.length) return false;
    // Cleared on completion so the next entry starts over rather than firing again on
    // the following keypress.
    this.index = 0;
    return true;
  }
}
