// A dependency-free mutable 3-vector.
//
// Deliberately NOT Three.js's Vector3: the simulation must not depend on the
// renderer (see eslint.config.js). The API is intentionally close to Three's so
// that porting the flight model from `pewpew/docs/FLIGHT_AND_AIM.md` reads naturally,
// and so `view` can copy into a Three Vector3 in one line.
//
// Every method mutates `this` and returns `this` for chaining. Allocation in the
// per-tick hot loop is a real cost at 60 Hz × 6 players, so use `tv3()` scratch
// vectors rather than `new Vec3()` inside systems.

import { clamp, EPSILON } from "./scalar.js";

export class Vec3 {
  constructor(
    public x = 0,
    public y = 0,
    public z = 0,
  ) {}

  set(x: number, y: number, z: number): this {
    this.x = x;
    this.y = y;
    this.z = z;
    return this;
  }

  copy(v: Vec3): this {
    return this.set(v.x, v.y, v.z);
  }

  clone(): Vec3 {
    return new Vec3(this.x, this.y, this.z);
  }

  setScalar(s: number): this {
    return this.set(s, s, s);
  }

  add(v: Vec3): this {
    return this.set(this.x + v.x, this.y + v.y, this.z + v.z);
  }

  addVectors(a: Vec3, b: Vec3): this {
    return this.set(a.x + b.x, a.y + b.y, a.z + b.z);
  }

  sub(v: Vec3): this {
    return this.set(this.x - v.x, this.y - v.y, this.z - v.z);
  }

  subVectors(a: Vec3, b: Vec3): this {
    return this.set(a.x - b.x, a.y - b.y, a.z - b.z);
  }

  addScaledVector(v: Vec3, s: number): this {
    return this.set(this.x + v.x * s, this.y + v.y * s, this.z + v.z * s);
  }

  multiplyScalar(s: number): this {
    return this.set(this.x * s, this.y * s, this.z * s);
  }

  negate(): this {
    return this.set(-this.x, -this.y, -this.z);
  }

  dot(v: Vec3): number {
    return this.x * v.x + this.y * v.y + this.z * v.z;
  }

  cross(v: Vec3): this {
    return this.crossVectors(this, v);
  }

  crossVectors(a: Vec3, b: Vec3): this {
    // Read all six components before writing — `crossVectors(this, b)` is legal.
    const ax = a.x, ay = a.y, az = a.z;
    const bx = b.x, by = b.y, bz = b.z;
    return this.set(ay * bz - az * by, az * bx - ax * bz, ax * by - ay * bx);
  }

  lengthSq(): number {
    return this.x * this.x + this.y * this.y + this.z * this.z;
  }

  length(): number {
    return Math.sqrt(this.lengthSq());
  }

  distanceToSq(v: Vec3): number {
    const dx = this.x - v.x, dy = this.y - v.y, dz = this.z - v.z;
    return dx * dx + dy * dy + dz * dz;
  }

  distanceTo(v: Vec3): number {
    return Math.sqrt(this.distanceToSq(v));
  }

  /** Normalizes in place. A zero-length vector is left at zero rather than NaN. */
  normalize(): this {
    const lsq = this.lengthSq();
    if (lsq < EPSILON * EPSILON) return this.set(0, 0, 0);
    return this.multiplyScalar(1 / Math.sqrt(lsq));
  }

  setLength(l: number): this {
    return this.normalize().multiplyScalar(l);
  }

  lerp(target: Vec3, t: number): this {
    return this.set(
      this.x + (target.x - this.x) * t,
      this.y + (target.y - this.y) * t,
      this.z + (target.z - this.z) * t,
    );
  }

  lerpVectors(a: Vec3, b: Vec3, t: number): this {
    return this.set(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, a.z + (b.z - a.z) * t);
  }

  /** Angle in radians between two vectors. Both are assumed non-degenerate. */
  angleTo(v: Vec3): number {
    const denom = Math.sqrt(this.lengthSq() * v.lengthSq());
    if (denom < EPSILON) return 0;
    return Math.acos(clamp(this.dot(v) / denom, -1, 1));
  }

  /**
   * Rodrigues rotation about a UNIT axis. The flight model leans on this heavily
   * (carrying aim through the rail's tangent rotation, cone clamping, view-relative
   * steering), so it is worth keeping allocation-free.
   */
  applyAxisAngle(axis: Vec3, angle: number): this {
    const c = Math.cos(angle);
    const s = Math.sin(angle);
    const d = axis.dot(this) * (1 - c);
    const { x, y, z } = this;
    return this.set(
      x * c + (axis.y * z - axis.z * y) * s + axis.x * d,
      y * c + (axis.z * x - axis.x * z) * s + axis.y * d,
      z * c + (axis.x * y - axis.y * x) * s + axis.z * d,
    );
  }

  /** Removes the component of `this` along the UNIT vector `n` (Gram-Schmidt). */
  orthogonalize(n: Vec3): this {
    return this.addScaledVector(n, -this.dot(n));
  }

  /** Reflects `this` about the plane with UNIT normal `n`. */
  reflect(n: Vec3): this {
    return this.addScaledVector(n, -2 * this.dot(n));
  }

  isFinite(): boolean {
    return Number.isFinite(this.x) && Number.isFinite(this.y) && Number.isFinite(this.z);
  }

  equals(v: Vec3, eps = EPSILON): boolean {
    return (
      Math.abs(this.x - v.x) <= eps &&
      Math.abs(this.y - v.y) <= eps &&
      Math.abs(this.z - v.z) <= eps
    );
  }

  // ── Typed-array interop ──────────────────────────────────────────────────────
  // Component columns are flat TypedArrays (see core/ecs). These are the bridge
  // between "readable vector math" and "snapshottable storage".

  readFrom(arr: ArrayLike<number>, base: number): this {
    return this.set(arr[base] ?? 0, arr[base + 1] ?? 0, arr[base + 2] ?? 0);
  }

  writeTo(arr: { [i: number]: number }, base: number): this {
    arr[base] = this.x;
    arr[base + 1] = this.y;
    arr[base + 2] = this.z;
    return this;
  }

  toArray(): [number, number, number] {
    return [this.x, this.y, this.z];
  }

  static from(a: ArrayLike<number>): Vec3 {
    return new Vec3(a[0] ?? 0, a[1] ?? 0, a[2] ?? 0);
  }
}

export const V3_ZERO = Object.freeze(new Vec3(0, 0, 0)) as Readonly<Vec3>;
export const V3_UP = Object.freeze(new Vec3(0, 1, 0)) as Readonly<Vec3>;
export const V3_RIGHT = Object.freeze(new Vec3(1, 0, 0)) as Readonly<Vec3>;
export const V3_FORWARD = Object.freeze(new Vec3(0, 0, -1)) as Readonly<Vec3>;

// ── Scratch ring ──────────────────────────────────────────────────────────────
// Systems run every tick; allocating vectors there is the classic source of GC
// hitching in a 60 Hz loop. `tv3()` hands out a zeroed vector from a fixed ring.
//
// The contract: a scratch vector is valid only until RING_SIZE further `tv3()`
// calls have happened. Never store one on an entity, in a closure, or across a
// function boundary you do not control. When in doubt, `new Vec3()`.
const RING_SIZE = 64;
const RING: Vec3[] = Array.from({ length: RING_SIZE }, () => new Vec3());
let ringIndex = 0;

export function tv3(x = 0, y = 0, z = 0): Vec3 {
  ringIndex = (ringIndex + 1) % RING_SIZE;
  return RING[ringIndex]!.set(x, y, z);
}
