// The hidden tuning menu.
//
// Opened by the DEBUG button the Konami code reveals on the title screen, and by the
// backtick key once unlocked — because the values worth turning are the ones you want
// to turn while looking at the thing they affect, and there is no pause to hang a menu
// off yet (see `sunweasel/CLAUDE.md`, "No pause").
//
// It renders entirely from `DEBUG_FIELDS`, so a knob added to the fold appears here
// with its own range and hint and nothing in this file has to learn about it.
//
// ── Why a change restarts the run ────────────────────────────────────────────
//
// Every knob here is folded into content when a run is BUILT — the enemy catalog, the
// resolved ship stats, the spawn config. There is no way to apply one to a run already
// in flight without a second, mutating path into the same numbers, which is exactly
// the debug branch inside the determinism boundary that `sim/debug.ts` exists to avoid.
// So the menu does what the difficulty picker does, for the same reason: it starts a
// new run. That is also what a tester wants — a clean run at the new numbers rather
// than a hybrid of two.
//
// The restart fires on `change` (the pointer coming up), not on `input`. Dragging a
// slider would otherwise rebuild the world on every pixel of travel.

import {
  DEBUG_FIELDS,
  DEFAULT_DEBUG,
  type DebugField,
  type DebugOverrides,
} from "@sim/debug.js";
import { debugJson, parseDebugJson } from "./debugStore.js";

const STYLE = `
.sw-debug {
  /* 10 — above the shop's 9, which is itself above the title screen's 8. Backtick opens
     this from anywhere, including over an open shop, so it has to be the topmost thing
     on the page or the tester's way out would be behind the panel they are trying to
     leave. */
  position: fixed; inset: 0; z-index: 10;
  display: flex; align-items: center; justify-content: center;
  background: rgba(3,6,12,0.86);
  font: 12px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #cddcf0; pointer-events: auto; touch-action: manipulation;
  user-select: none; -webkit-user-select: none;
}
.sw-debug.sw-debug-hidden { display: none; }
.sw-debug-panel {
  width: min(560px, 94vw); max-height: 88vh; overflow-y: auto;
  /* Momentum scrolling, and a scroll that does not escape into the page behind it —
     the page is scroll-locked for the canvas's sake and would otherwise swallow the
     drag once this list hits its end. */
  -webkit-overflow-scrolling: touch; overscroll-behavior: contain;
  padding: 16px 18px calc(16px + env(safe-area-inset-bottom, 0px));
  background: rgba(8,14,26,0.96); border: 1px solid #2b3d5a; border-radius: 12px;
}
.sw-debug-head {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
  margin-bottom: 4px;
}
.sw-debug-title { font-size: 14px; letter-spacing: 0.24em; color: #ffd479; }
.sw-debug-note { color: #63728c; font-size: 11px; letter-spacing: 0.06em; }
.sw-debug-group {
  margin-top: 14px; margin-bottom: 4px;
  font-size: 11px; letter-spacing: 0.22em; color: #7e8ea8;
  border-bottom: 1px solid #1d2c44; padding-bottom: 3px;
}
.sw-debug-row { display: flex; align-items: center; gap: 10px; margin: 7px 0; }
.sw-debug-name { width: 96px; flex: none; color: #9fb2cc; letter-spacing: 0.08em; font-size: 11px; }
.sw-debug-slider {
  flex: 1 1 auto; min-width: 0;
  -webkit-appearance: none; appearance: none;
  height: 26px; background: transparent; cursor: pointer;
  touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.sw-debug-slider::-webkit-slider-runnable-track {
  height: 3px; border-radius: 2px; background: rgba(60,90,135,0.9);
}
.sw-debug-slider::-moz-range-track { height: 3px; border-radius: 2px; background: rgba(60,90,135,0.9); }
.sw-debug-slider::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 22px; height: 22px; margin-top: -10px; border-radius: 50%;
  background: #6fa2dd; border: 1px solid #a8ccf0;
}
.sw-debug-slider::-moz-range-thumb {
  width: 22px; height: 22px; border-radius: 50%; background: #6fa2dd; border: 1px solid #a8ccf0;
}
.sw-debug-value { width: 46px; flex: none; text-align: right; color: #cddcf0; }
/* A knob that is not at its default is the thing you most want to see when the run
   behaves strangely and you have forgotten what you left turned. */
.sw-debug-row.changed .sw-debug-name,
.sw-debug-row.changed .sw-debug-value { color: #ffd479; }
.sw-debug-actions {
  display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px;
  border-top: 1px solid #1d2c44; padding-top: 14px;
}
.sw-debug-btn {
  pointer-events: auto;
  font: 600 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.16em; color: #cddcf0;
  background: rgba(14,26,46,0.9); border: 1px solid #3d5f8c; border-radius: 8px;
  /* 44px: these are pressed with a thumb on the device the tuning is being flown on. */
  padding: 0 16px; min-height: 44px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.sw-debug-btn:hover { background: rgba(24,44,74,0.95); }
.sw-debug-btn:active { transform: scale(0.97); }
.sw-debug-btn.primary { color: #eaf3ff; background: rgba(30,70,120,0.9); border-color: #6fa2dd; }
.sw-debug-json {
  width: 100%; margin-top: 10px; min-height: 92px; resize: vertical;
  font: 11px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #9fb2cc; background: rgba(4,8,16,0.9);
  border: 1px solid #2b3d5a; border-radius: 8px; padding: 8px;
  user-select: text; -webkit-user-select: text;
}
`;

export interface DebugMenuOptions {
  readonly initial: DebugOverrides;
  /**
   * Called when a knob is COMMITTED — a slider released, or RESET pressed.
   *
   * Not on every input event: the handler rebuilds the run, and a drag fires input on
   * every pixel. The readout still updates live, so the control does not feel laggy.
   */
  readonly onChange: (overrides: DebugOverrides) => void;
  /**
   * Called by GRANT CREDITS, with the amount to add to the meta-save.
   *
   * An ACTION rather than a knob, and that distinction is load-bearing: `DEBUG_FIELDS`
   * is the single source of truth for the sliders and a spec asserts it covers
   * `DebugOverrides` exactly, so a one-shot that grants something is not a field and must
   * not become one. It also folds into no content — the credits go to the SAVE, not to
   * the run — which is the other reason it cannot ride the overrides document.
   *
   * It exists because the shop is otherwise untestable on the device it most needs
   * testing on. Evaluating whether a price feels right takes credits, earning them takes
   * flying the level several times, and a phone tester will not do that before telling
   * you the shop looks fine.
   */
  readonly onGrantCredits?: (amount: number) => void;
}

export interface DebugMenu {
  readonly root: HTMLElement;
  open(): void;
  close(): void;
  toggle(): void;
  readonly isOpen: boolean;
  /** Reflects values changed elsewhere (an import, a reset from another surface). */
  set(overrides: DebugOverrides): void;
  dispose(): void;
}

/**
 * What one press of GRANT hands over.
 *
 * 1000 buys the three cheapest upgrades outright (250 + 300 + 400) with a little over,
 * which is enough to judge whether the shop reads well and whether a bought upgrade
 * changes how the ship flies — the two questions it exists to answer. Deliberately not
 * the catalog total of 2200: "can I afford everything" is a different screen from the one
 * being tested, and pressing it three times is not hard.
 */
const GRANT_AMOUNT = 1000;

/** Enough decimals to read, without `1.2000000000000002` from a float step. */
const format = (field: DebugField, value: number): string =>
  value.toFixed(field.step < 0.1 ? 2 : field.step < 1 ? 1 : 0);

export function createDebugMenu(
  options: DebugMenuOptions,
  parent: HTMLElement = document.body,
): DebugMenu {
  const style = document.createElement("style");
  style.dataset.swDebug = "";
  style.textContent = STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-debug sw-debug-hidden";
  root.dataset.debugMenu = "";

  const panel = document.createElement("div");
  panel.className = "sw-debug-panel";
  root.appendChild(panel);

  const head = document.createElement("div");
  head.className = "sw-debug-head";
  head.innerHTML = `
    <span class="sw-debug-title">DEBUG</span>
    <span class="sw-debug-note">changes restart the run · kept until you clear them</span>
  `;
  panel.appendChild(head);

  let current: DebugOverrides = options.initial;

  interface Row {
    readonly field: DebugField;
    readonly row: HTMLElement;
    readonly slider: HTMLInputElement;
    readonly value: HTMLElement;
    detach(): void;
  }
  const rows: Row[] = [];

  let group = "";
  for (const field of DEBUG_FIELDS) {
    if (field.group !== group) {
      group = field.group;
      const heading = document.createElement("div");
      heading.className = "sw-debug-group";
      heading.textContent = group;
      panel.appendChild(heading);
    }

    const row = document.createElement("div");
    row.className = "sw-debug-row";
    row.title = field.hint;

    const name = document.createElement("span");
    name.className = "sw-debug-name";
    name.textContent = field.label;

    const slider = document.createElement("input");
    slider.type = "range";
    slider.className = "sw-debug-slider";
    slider.dataset.debugKey = field.key;
    slider.min = String(field.min);
    slider.max = String(field.max);
    slider.step = String(field.step);
    slider.value = String(current[field.key]);

    const value = document.createElement("span");
    value.className = "sw-debug-value";
    value.dataset.debugValue = field.key;
    value.textContent = format(field, current[field.key]);

    // Live readout, committed change. The split is what keeps a drag from rebuilding
    // the world sixty times while still letting the tester see where the slider is.
    const onInput = (event: Event) => {
      event.stopPropagation();
      const next = Number.parseFloat(slider.value);
      if (!Number.isFinite(next)) return;
      value.textContent = format(field, next);
      row.classList.toggle("changed", next !== field.default);
    };
    const onCommit = (event: Event) => {
      event.stopPropagation();
      const next = Number.parseFloat(slider.value);
      if (!Number.isFinite(next)) return;
      current = { ...current, [field.key]: next };
      refreshJson();
      options.onChange(current);
    };
    slider.addEventListener("input", onInput);
    slider.addEventListener("change", onCommit);

    row.append(name, slider, value);
    row.classList.toggle("changed", current[field.key] !== field.default);
    panel.appendChild(row);
    rows.push({
      field,
      row,
      slider,
      value,
      detach: () => {
        slider.removeEventListener("input", onInput);
        slider.removeEventListener("change", onCommit);
      },
    });
  }

  const actions = document.createElement("div");
  actions.className = "sw-debug-actions";
  panel.appendChild(actions);

  // `data-debug-action` rather than position: the smoke drives these, and a selector
  // that counts children breaks the moment a button is added in the middle.
  const button = (action: string, label: string, primary = false): HTMLButtonElement => {
    const el = document.createElement("button");
    el.type = "button";
    el.className = `sw-debug-btn${primary ? " primary" : ""}`;
    el.dataset.debugAction = action;
    el.textContent = label;
    actions.appendChild(el);
    return el;
  };

  const closeButton = button("close", "CLOSE", true);
  const resetButton = button("reset", "RESET");
  const exportButton = button("export", "EXPORT JSON");
  const copyButton = button("copy", "COPY");
  const importButton = button("import", "APPLY JSON");
  // Only mounted when something is listening. Every other button here changes the run in
  // front of you; this one changes a stored document, so it is worth it being visibly a
  // different kind of thing rather than sitting in the row unexplained.
  const grantButton = options.onGrantCredits ? button("grant", `GRANT ${GRANT_AMOUNT} CR`) : null;

  // The document, always visible rather than behind the export button. Downloading is
  // the part that fails silently in the places this gets used — a phone browser, a page
  // added to the home screen — so the text is on screen to select and paste into a bug
  // report whether or not the file ever lands.
  //
  // EDITABLE, because the export is only worth anything if the tuning can come back:
  // paste what someone else was flying, press APPLY JSON, fly the same run.
  const json = document.createElement("textarea");
  json.className = "sw-debug-json";
  json.dataset.debugJson = "";
  json.spellcheck = false;
  panel.appendChild(json);

  const refreshJson = () => {
    json.value = debugJson(current);
  };
  refreshJson();

  const applyToControls = (overrides: DebugOverrides) => {
    current = overrides;
    for (const { field, row, slider, value } of rows) {
      slider.value = String(overrides[field.key]);
      value.textContent = format(field, overrides[field.key]);
      row.classList.toggle("changed", overrides[field.key] !== field.default);
    }
    refreshJson();
  };

  const onClose = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    root.classList.add("sw-debug-hidden");
  };
  closeButton.addEventListener("click", onClose);

  const onReset = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    applyToControls(DEFAULT_DEBUG);
    options.onChange(current);
  };
  resetButton.addEventListener("click", onReset);

  const onExport = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    const blob = new Blob([debugJson(current)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "sun-weasel-debug.json";
    link.click();
    // Revoked on the next turn rather than immediately: revoking synchronously after
    // `click()` races the browser's own fetch of the blob in some engines and the file
    // arrives empty.
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };
  exportButton.addEventListener("click", onExport);

  const onCopy = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    const text = debugJson(current);
    // `writeText` needs a secure context and rejects when the document is not focused;
    // the select-and-`execCommand` path still works in both cases, so it is the
    // fallback rather than the other way round.
    void navigator.clipboard?.writeText(text).catch(() => {
      json.select();
    });
    copyButton.textContent = "COPIED";
    setTimeout(() => (copyButton.textContent = "COPY"), 1200);
  };
  copyButton.addEventListener("click", onCopy);

  const onImport = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    const parsed = parseDebugJson(json.value);
    if (!parsed) {
      // Said on the button rather than in a dialog: the text is right there to fix,
      // and a modal over a debug menu is a second thing to dismiss.
      importButton.textContent = "NOT JSON";
      setTimeout(() => (importButton.textContent = "APPLY JSON"), 1400);
      return;
    }
    // `applyToControls` rewrites the textarea from the clamped document, so what is on
    // screen after an import is what the run is actually using — not the text that was
    // pasted, which may have carried out-of-range or unknown values.
    applyToControls(parsed);
    options.onChange(current);
  };
  importButton.addEventListener("click", onImport);

  // Grants and stays open: the point is to press it and then walk to the shop, and a
  // menu that dismissed itself would put the tester back in front of the title with no
  // sign anything happened.
  const onGrant = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    options.onGrantCredits?.(GRANT_AMOUNT);
  };
  grantButton?.addEventListener("click", onGrant);

  // Keystrokes inside the menu must not reach the game. The keyboard sampler listens
  // on `window`, so an arrow key nudging a slider would also steer the ship. BOTH
  // halves are stopped: swallowing only keydown would leave the key permanently in the
  // sampler's held set the moment focus was inside the panel.
  const swallow = (event: KeyboardEvent) => {
    if (event.key === "Escape") {
      root.classList.add("sw-debug-hidden");
    }
    event.stopPropagation();
  };
  root.addEventListener("keydown", swallow);
  root.addEventListener("keyup", swallow);

  // A click on the backdrop closes, which is what everyone tries first. Guarded on the
  // target being the backdrop itself so a drag that ends outside a slider does not.
  const onBackdrop = (event: MouseEvent) => {
    if (event.target === root) root.classList.add("sw-debug-hidden");
  };
  root.addEventListener("click", onBackdrop);

  parent.appendChild(root);

  return {
    root,
    get isOpen() {
      return !root.classList.contains("sw-debug-hidden");
    },
    open() {
      refreshJson();
      root.classList.remove("sw-debug-hidden");
    },
    close() {
      root.classList.add("sw-debug-hidden");
    },
    toggle() {
      root.classList.toggle("sw-debug-hidden");
    },
    set: applyToControls,
    dispose() {
      for (const row of rows) row.detach();
      closeButton.removeEventListener("click", onClose);
      resetButton.removeEventListener("click", onReset);
      exportButton.removeEventListener("click", onExport);
      copyButton.removeEventListener("click", onCopy);
      importButton.removeEventListener("click", onImport);
      grantButton?.removeEventListener("click", onGrant);
      root.removeEventListener("keydown", swallow);
      root.removeEventListener("keyup", swallow);
      root.removeEventListener("click", onBackdrop);
      root.remove();
      style.remove();
    },
  };
}
