// The HUD's DOM half.
//
// Deliberately thin: every decision is made in `hudModel`, and this only writes what it
// is given. The test for that split is whether anything here would be worth asserting —
// setting a width to a fraction that was already clamped is not, and that is the point.
//
// DOM rather than canvas overlay, for three reasons that all matter later: text stays
// crisp at any device pixel ratio without a second renderer, accessibility is possible
// at all, and the HUD does not cost a draw call or contend with the WebGL context.
//
// Styles are injected rather than living in `shell.html`, so the HUD arrives complete
// when it is imported and the page template stays the page template.

import { DEFAULT_DIFFICULTY, type DifficultyDef } from "@content/difficulty/index.js";
import { createDifficultyPicker, type DifficultyPicker } from "./difficultyPicker.js";
import { createSettingsPanel, type SettingsPanel } from "./settingsPanel.js";
import { DEFAULT_SENSITIVITY, type StickSensitivity } from "./settingsStore.js";
import type { HudModel, RailReadout } from "./hud.js";
import { TRUNK_COURSE } from "@sim/rail.js";

const STYLE = `
.sw-hud {
  position: fixed; inset: 0; pointer-events: none; user-select: none;
  font: 13px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #cddcf0; text-shadow: 0 1px 2px rgba(0,0,0,0.8);
  /* Above the touch overlay's 5. A fixed-position element is its own stacking
     context, so a z-index on the retry button alone would be confined here and the
     button would sit UNDER the on-screen controls — visible, and unpressable with a
     thumb. The root stays pointer-events: none, so only the button itself takes
     input and the controls below keep working during a run. */
  z-index: 6;
}
.sw-hud-corner { position: absolute; top: 14px; left: 14px; min-width: 190px; }
.sw-hud-hull-track {
  height: 9px; background: rgba(10,16,28,0.75); border: 1px solid #2b3d5a;
  border-radius: 2px; overflow: hidden; margin-top: 4px;
}
.sw-hud-hull-fill {
  height: 100%; width: 100%; background: #49d0a0;
  transition: width 90ms linear, background-color 200ms linear;
}
.sw-hud-hull-fill.warn { background: #e0b552; }
.sw-hud-hull-fill.critical { background: #e05a5a; }
.sw-hud-label { color: #7e8ea8; letter-spacing: 0.08em; font-size: 11px; }
/* The mode row sits under the hull block: top-LEFT is the only corner free on both a
   desktop and a phone. Top-right is the stats block, and the bottom-right is where the
   touch chips go — including the one that toggles this very mode. */
.sw-hud-modes { display: flex; gap: 6px; margin-top: 7px; }
.sw-hud-mode {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 7px; border-radius: 3px;
  border: 1px solid #2b3d5a; background: rgba(10,16,28,0.6);
  font-size: 11px; letter-spacing: 0.1em; color: #7e8ea8;
  transition: color 120ms linear, border-color 120ms linear, background-color 120ms linear;
}
/* Inherits the chip's colour rather than taking the muted label grey, so the whole
   chip lights as one thing. */
.sw-hud-mode-name { opacity: 0.7; }
.sw-hud-mode-key {
  /* The key that toggles it, on the chip itself — the legend under the canvas is
     hidden on a phone, and this is the only other place the binding is written down. */
  font-size: 9px; padding: 0 3px; border-radius: 2px;
  border: 1px solid currentColor; opacity: 0.75;
}
/* ENGAGED is the state worth seeing from the corner of an eye, so it is the one that
   changes colour rather than merely text — the caption alone would be unreadable at a
   glance while something is shooting at you. */
.sw-hud-mode.engaged { color: #ffd479; border-color: #7a6330; background: rgba(58,42,12,0.6); }
/* Forced by a stop, not by the player. A different colour because pressing F here
   changes the stored preference and nothing visible happens; an indicator that looked
   identical to a self-selected mode would read as a stuck control. */
.sw-hud-mode.forced { color: #7fe3ff; border-color: #2f6d84; background: rgba(12,44,58,0.6); }
.sw-hud-stats { position: absolute; top: 14px; right: 14px; text-align: right; }
/* Under the stats, sharing their corner. That corner is HUD-owned: the touch chip
   block is kept out of it deliberately (see CLAUDE.md), so this is the one place a
   second readout can go without fighting a thumb for the hit test. */
.sw-hud-rail {
  position: absolute; top: 92px; right: 14px; text-align: right;
  font-size: 11px; line-height: 1.5; color: #7e8ea8;
  border-right: 2px solid rgba(126,142,168,0.35); padding-right: 8px;
}
.sw-hud-rail-head { color: #9fb4d4; letter-spacing: 0.14em; }
/* Amber for the route the fork takes by DEFAULT, green for the one that has to be
   earned. The same two colours the in-world ring uses, so the readout and the marker
   ahead of the ship say the same thing in the same language. */
.sw-hud-rail-default { color: #ffd479; }
.sw-hud-rail-earned { color: #5fe0a0; }
.sw-hud-progress-track {
  position: absolute; left: 14px; right: 14px; bottom: 34px;
  height: 3px; background: rgba(10,16,28,0.7);
}
.sw-hud-progress-fill { height: 100%; width: 0; background: #1f6f8f; }
.sw-hud-objective {
  position: absolute; top: 84px; left: 0; right: 0; text-align: center;
  font-size: 18px; letter-spacing: 0.18em; color: #ffd479;
}
.sw-hud-outcome {
  position: absolute; inset: 0; display: flex; flex-direction: column; gap: 28px;
  align-items: center; justify-content: center;
  font-size: 42px; letter-spacing: 0.3em; background: rgba(3,6,12,0.55);
}
.sw-hud-outcome.won { color: #7dffb0; }
.sw-hud-outcome.lost { color: #ff8080; }
.sw-hud-retry {
  /* The one element in the HUD that takes input. */
  pointer-events: auto;
  font: 600 15px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.2em; color: #cddcf0;
  background: rgba(14,26,46,0.9); border: 1px solid #3d5f8c; border-radius: 10px;
  /* 48px is the smallest reliably tappable target; the run is over, so there is no
     reason to make this small. touch-action: manipulation skips the 300ms
     double-tap-zoom wait that would otherwise sit between the tap and the restart. */
  padding: 0 34px; min-height: 52px; min-width: 180px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  text-shadow: none;
  transition: background-color 100ms linear, transform 100ms ease-out;
}
.sw-hud-retry:hover { background: rgba(24,44,74,0.95); }
.sw-hud-retry:active { transform: scale(0.96); background: rgba(80,150,225,0.7); }
/* The secondary row, side by side under RETRY. Wraps rather than overflowing, because on
   a phone in portrait two 44px buttons plus their gap can exceed the width. */
.sw-hud-outcome-actions {
  display: flex; flex-wrap: wrap; gap: 12px; justify-content: center;
}
/* Smaller than RETRY on purpose. Flying again is what this screen is for; spending what
   the run earned and going back to the title are the other two things you might do, and
   the sizes should say which is which. */
.sw-hud-shop {
  pointer-events: auto;
  font: 600 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.2em; color: #7fd6a2;
  background: rgba(12,34,26,0.85); border: 1px solid #2f6b50; border-radius: 9px;
  padding: 0 22px; min-height: 44px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  text-shadow: none;
}
.sw-hud-shop:hover { background: rgba(18,50,38,0.9); }
.sw-hud-shop:active { transform: scale(0.97); }
.sw-hud-hidden { display: none; }
`;

export interface HudOptions {
  /**
   * Called when the player asks to run it again.
   *
   * The HUD raises the intent and does not act on it: restarting means rebuilding the
   * world, which is the composition root's job. Without this the only way out of a
   * finished run was to reload the page — and on a phone, where there is no visible
   * address bar, that is close to no way out at all.
   */
  readonly onRestart?: () => void;
  /** The difficulty the finished run was played on, for the picker's initial state. */
  readonly difficulty?: DifficultyDef;
  /**
   * Called when the player picks a different difficulty from the outcome screen, after
   * they have confirmed. A change here always means a new run.
   */
  readonly onDifficultyChange?: (difficulty: DifficultyDef) => void;
  /** Sensitivity the run was played with, for the panel's initial state. */
  readonly sensitivity?: StickSensitivity;
  /**
   * Called as a sensitivity slider moves.
   *
   * No confirm and no restart, unlike `onDifficultyChange`: sensitivity is a `ui/`
   * number the simulation never sees, so it applies live.
   */
  readonly onSensitivityChange?: (sensitivity: StickSensitivity) => void;
  /**
   * Called when UPGRADES is pressed on the outcome screen.
   *
   * The button is only mounted when this is supplied. Like `onRestart` it raises an
   * intent rather than acting: the shop is a modal the composition root owns, because it
   * is the same one the title screen opens and there is deliberately only one of it.
   */
  readonly onShop?: () => void;
  /**
   * Called when QUIT is pressed on the outcome screen. Back to the title.
   *
   * The button is only mounted when this is supplied. Before it existed the only way out
   * of a finished run was to fly another one or reload the page — and on a phone, with no
   * visible address bar, reloading is close to no way out at all. That was tolerable when
   * the title screen was a splash; it stopped being so once the title became where you
   * browse and buy upgrades.
   */
  readonly onQuit?: () => void;
  /**
   * Whether the HUD starts on screen. Defaults to true.
   *
   * False behind the title screen's attract flight, where every readout describes a run
   * nobody is playing — a full hull bar and counters that can only read zero.
   */
  readonly visible?: boolean;
}

export interface Hud {
  readonly root: HTMLElement;
  update(model: HudModel): void;
  /** Reflects a difficulty chosen elsewhere (the title screen) on the outcome picker. */
  setDifficulty(difficulty: DifficultyDef): void;
  /** Reflects a sensitivity chosen elsewhere, so the two screens cannot disagree. */
  setSensitivity(sensitivity: StickSensitivity): void;
  /** Shows or hides the sensitivity sliders — see the note in `settingsPanel.ts`. */
  setSensitivityVisible(visible: boolean): void;
  /** Shows or hides the whole HUD. Hidden during the attract flight. */
  setVisible(visible: boolean): void;
  /**
   * Shows the debug rail readout, or hides it with `null`.
   *
   * Every number arrives already computed by `railReadout`; this only formats. The
   * split is the same one `hudModel`/`createHud` makes and it matters more here, because
   * the readout exists to be TRUSTED against the simulation — arithmetic done in the
   * view is arithmetic nobody tests, and a preview that quietly disagrees with the fork
   * system would be worse than no readout at all.
   */
  setRailReadout(readout: RailReadout | null): void;
  dispose(): void;
}

/** Only touch the DOM when the value actually moved — most frames change nothing. */
const setText = (el: HTMLElement, value: string): void => {
  if (el.textContent !== value) el.textContent = value;
};

/** Same guard for the one block that is markup rather than a value. */
const setHtml = (el: HTMLElement, value: string): void => {
  if (el.innerHTML !== value) el.innerHTML = value;
};

/**
 * Escapes text going into that markup.
 *
 * Every string it receives is an authored id from a level file, so nothing hostile can
 * reach it today — but they are CONTENT, the editor will eventually let a person type
 * them, and a readout whose safety depends on nobody naming a branch `<b>` is a footgun
 * left lying about. Cheaper to close now than to remember later.
 */
const escape_ = (value: string): string =>
  value.replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`);

export function createHud(parent: HTMLElement = document.body, options: HudOptions = {}): Hud {
  const style = document.createElement("style");
  style.textContent = STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-hud";
  root.innerHTML = `
    <div class="sw-hud-corner">
      <div class="sw-hud-label">HULL</div>
      <div class="sw-hud-hull-track"><div class="sw-hud-hull-fill" data-hull></div></div>
      <div data-hull-text style="margin-top:3px"></div>
      <div class="sw-hud-modes">
        <span class="sw-hud-mode" data-aim-mode>
          <span class="sw-hud-mode-key">F</span>
          <span class="sw-hud-mode-name">AIM</span>
          <span data-aim-mode-text>FREE</span>
        </span>
      </div>
    </div>
    <div class="sw-hud-stats">
      <div><span class="sw-hud-label">ROCKS</span> <span data-rocks>0</span></div>
      <div><span class="sw-hud-label">KILLS</span> <span data-kills>0</span></div>
      <div><span class="sw-hud-label">WAVES</span> <span data-waves>0/0</span></div>
      <div><span class="sw-hud-label">CREDITS</span> <span data-credits>0</span></div>
    </div>
    <div class="sw-hud-progress-track"><div class="sw-hud-progress-fill" data-progress></div></div>
    <div class="sw-hud-rail sw-hud-hidden" data-rail-debug></div>
    <div class="sw-hud-objective sw-hud-hidden" data-objective></div>
    <div class="sw-hud-outcome sw-hud-hidden" data-outcome>
      <div data-outcome-text></div>
      <button class="sw-hud-retry" type="button" data-retry>RETRY</button>
      <div class="sw-hud-outcome-actions">
        <button class="sw-hud-shop sw-hud-hidden" type="button" data-shop-open>UPGRADES</button>
        <button class="sw-hud-shop sw-hud-hidden" type="button" data-quit>QUIT</button>
      </div>
    </div>
  `;
  parent.appendChild(root);

  const pick = <T extends HTMLElement>(attr: string): T =>
    root.querySelector(`[${attr}]`) as T;

  const hull = pick("data-hull");
  const hullText = pick("data-hull-text");
  const rocks = pick("data-rocks");
  const kills = pick("data-kills");
  const waves = pick("data-waves");
  const credits = pick("data-credits");
  const aimMode = pick("data-aim-mode");
  const aimModeText = pick("data-aim-mode-text");
  const progress = pick("data-progress");
  const objective = pick("data-objective");
  const railDebug = pick("data-rail-debug");
  const outcome = pick("data-outcome");
  const outcomeText = pick("data-outcome-text");
  const retry = pick<HTMLButtonElement>("data-retry");
  const shop = pick<HTMLButtonElement>("data-shop-open");
  const quit = pick<HTMLButtonElement>("data-quit");

  const onRetry = (event: Event) => {
    // The button lives inside a full-screen overlay; without this the same tap can
    // also reach whatever is beneath once the overlay is hidden on the next frame.
    event.preventDefault();
    event.stopPropagation();
    options.onRestart?.();
  };
  retry.addEventListener("click", onRetry);

  // Revealed only when something can open. Same reasoning as the title screen's copy: a
  // button that does nothing is worse on this screen than no button at all, and every
  // existing spec builds a HUD without one.
  const onShop = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    options.onShop?.();
  };
  if (options.onShop) {
    shop.classList.remove("sw-hud-hidden");
    shop.addEventListener("click", onShop);
  }

  const onQuit = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    options.onQuit?.();
  };
  if (options.onQuit) {
    quit.classList.remove("sw-hud-hidden");
    quit.addEventListener("click", onQuit);
  }

  // Changing difficulty here restarts from the beginning, so it asks first — unlike
  // the title screen's copy of the same picker, where there is no run to lose.
  const picker: DifficultyPicker = createDifficultyPicker({
    initial: options.difficulty ?? DEFAULT_DIFFICULTY,
    confirmChange: true,
    onChange: (difficulty) => options.onDifficultyChange?.(difficulty),
  });
  outcome.appendChild(picker.root);

  const settings: SettingsPanel = createSettingsPanel({
    initial: options.sensitivity ?? DEFAULT_SENSITIVITY,
    onChange: (sensitivity) => options.onSensitivityChange?.(sensitivity),
  });
  outcome.appendChild(settings.root);

  if (options.visible === false) root.classList.add("sw-hud-hidden");

  let wasFinished = false;

  return {
    root,

    setVisible(visible) {
      root.classList.toggle("sw-hud-hidden", !visible);
    },

    setRailReadout(readout) {
      railDebug.classList.toggle("sw-hud-hidden", readout === null);
      if (readout === null) return;

      const lines = [
        `<div class="sw-hud-rail-head">RAIL ${readout.railS.toFixed(0)} / ${readout.courseLength.toFixed(0)}</div>`,
        `<div>COURSE <b>${escape_(readout.courseBranch)}</b> · ${readout.forksResolved} FORK${readout.forksResolved === 1 ? "" : "S"} PASSED</div>`,
      ];

      const fork = readout.nextFork;
      if (fork === null) {
        lines.push("<div>NO FORK AHEAD</div>");
      } else {
        // Counted to `commitS`, which is one full segment BEFORE the visible split —
        // see `ForkReadout.distance`. Rounded down so the number never reads as
        // remaining distance the player does not actually have.
        lines.push(`<div>DECIDES IN <b>${Math.max(0, Math.floor(fork.distance))}</b> (${escape_(fork.key)})</div>`);
        if (fork.triggerId !== null) {
          lines.push(
            `<div>${escape_(fork.triggerId)} <b class="${fork.triggerFired ? "sw-hud-rail-earned" : "sw-hud-rail-default"}">${fork.triggerFired ? "FIRED" : "NOT FIRED"}</b></div>`,
          );
        }
        // The line the whole readout is for: not what the fork COULD do, but where this
        // party goes if it commits on this tick.
        lines.push(
          `<div>WOULD TAKE <b class="${fork.wouldTakeBranch === TRUNK_COURSE ? "sw-hud-rail-default" : "sw-hud-rail-earned"}">${escape_(fork.wouldTakeBranch)}</b></div>`,
        );
      }

      if (readout.firedTriggers.length > 0) {
        lines.push(`<div>TRIGGERS ${readout.firedTriggers.map(escape_).join(" ")}</div>`);
      }

      setHtml(railDebug, lines.join(""));
    },

    setDifficulty(difficulty) {
      picker.select(difficulty);
    },

    setSensitivity(sensitivity) {
      settings.set(sensitivity);
    },

    setSensitivityVisible(visible) {
      settings.setVisible(visible);
    },

    update(model) {
      hull.style.width = `${(model.healthFraction * 100).toFixed(1)}%`;
      // Colour by fraction, not by absolute health: an upgraded hull on 110 points is
      // healthy and a base one on 110 does not exist.
      hull.className = `sw-hud-hull-fill${
        model.healthFraction <= 0.25 ? " critical" : model.healthFraction <= 0.5 ? " warn" : ""
      }`;
      setText(hullText, `${Math.max(0, Math.round(model.health))} / ${model.maxHealth}`);

      setText(rocks, String(model.hazardKills));
      setText(kills, String(model.enemyKills));
      setText(waves, `${model.wavesReleased}/${model.wavesTotal}`);
      setText(credits, String(model.credits));

      setText(aimModeText, model.aimModeLabel);
      // `forced` wins the colour: while a stop is imposing a mode, that is the fact the
      // player needs, and both classes together would just be two borders arguing.
      aimMode.classList.toggle("forced", model.aimModeForced);
      aimMode.classList.toggle("engaged", model.aimModeEngaged && !model.aimModeForced);
      aimMode.title = model.aimModeForced
        ? "Aim mode imposed by this stop"
        : "F toggles free aim and forward lock";

      progress.style.width = `${(model.progress * 100).toFixed(1)}%`;

      objective.classList.toggle("sw-hud-hidden", !model.heldLabel);
      if (model.heldLabel) setText(objective, model.heldLabel);

      const finished = model.outcome !== "running";
      if (finished !== wasFinished) {
        // Reopening the overlay must not show a confirm the player abandoned on the
        // previous run.
        if (finished) picker.reset();
        wasFinished = finished;
      }
      outcome.classList.toggle("sw-hud-hidden", !finished);
      if (finished) {
        // classList rather than assigning className, which used to be safe only
        // because the element had no other classes and no children to keep.
        outcome.classList.toggle("won", model.outcome === "won");
        outcome.classList.toggle("lost", model.outcome === "lost");
        setText(outcomeText, model.outcome === "won" ? "ARRIVED" : "DESTROYED");
      }
    },

    dispose() {
      retry.removeEventListener("click", onRetry);
      shop.removeEventListener("click", onShop);
      quit.removeEventListener("click", onQuit);
      picker.dispose();
      settings.dispose();
      root.remove();
      style.remove();
    },
  };
}
