// Whether touch is in play — before anyone has touched anything, and after.
//
// Two questions, and they are not the same one:
//
//   1. Does this device LOOK like a touch device? A static sniff, answered at boot.
//   2. Has the player actually touched the screen? Answered whenever it happens.
//
// The second exists because the first is wrong on real hardware in one direction that
// matters: a laptop with a touchscreen reports touch points while being driven with a
// trackpad, so the sniff correctly says "no controls" — and then someone reaches up and
// taps the screen. The controls should appear at that point, and so should the
// sensitivity sliders that scale them.
//
// ── This is `lib/lastInputSource.js`, restated ──────────────────────────────────
//
// The repo already has this: `lib/deviceInput.js` (the sniff) and
// `lib/lastInputSource.js` (which source was used last), shared by orca — it is what
// swaps orca's "Options > Keyboard" for "Options > Touch" mid-session. The RULES here
// are deliberately the same ones, including the one that is easy to get wrong: a MOUSE
// or a STYLUS moves nothing, because a precise pointer is not a thumb and a desktop
// player clicking a menu must not be handed thumb controls.
//
// It is restated rather than imported because this workspace ships ONE self-contained
// ESM chunk with `three` as its only external, and the preview deploys to
// `games/sun-weasel-next/` with no `games/lib` beside it (see the deploy section of
// `sunweasel/CLAUDE.md`). Importing the shared module would put a second chunk and a
// runtime path that does not exist behind the Service Worker into the ship build. When
// the parity gate lands and this game deploys the encrypted way, `lib/` is beside it
// and the two should become one module again.

/**
 * The device facts the sniff reads, behind an interface so it can be specced.
 *
 * `matchMedia` and `maxTouchPoints` are the whole of it. Injecting them is what lets a
 * headless spec describe a phone, a trackpad laptop, and a touchscreen laptop — three
 * cases no browser under test can be talked into being.
 */
export interface DeviceProbe {
  readonly maxTouchPoints: number;
  matches(query: string): boolean;
}

export const browserProbe = (): DeviceProbe => ({
  maxTouchPoints: typeof navigator === "undefined" ? 0 : navigator.maxTouchPoints,
  matches: (query) =>
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia(query).matches,
});

/**
 * `?touch=1` / `?touch=0`, or null when the decision is left to the device.
 *
 * Not only a debugging convenience: it is how the mobile smoke drives the controls in a
 * desktop-shaped browser, and how someone on a laptop looks at the layout without a
 * phone. A forced `0` also has to survive a stray touch — see `shouldUseTouch`.
 */
export function forcedTouch(search: string): boolean | null {
  const forced = new URLSearchParams(search).get("touch");
  if (forced === "1" || forced === "true") return true;
  if (forced === "0" || forced === "false") return false;
  return null;
}

/**
 * The static sniff: `maxTouchPoints` AND a coarse pointer.
 *
 * Either alone is wrong in a way that shows up on real hardware. A touchscreen laptop
 * reports touch points while being driven with a trackpad — controls would appear over
 * a game nobody is touching. Some Android browsers report `pointer: coarse` with a
 * mouse plugged in. Requiring both is the combination that holds, and the laptop case
 * it deliberately excludes is the one `trackFirstTouch` picks up afterwards.
 */
export function looksLikeTouch(probe: DeviceProbe = browserProbe()): boolean {
  return probe.maxTouchPoints > 0 && probe.matches("(pointer: coarse)");
}

/** Whether to put the on-screen controls up at boot. */
export function shouldUseTouch(
  search = typeof window === "undefined" ? "" : window.location.search,
  probe: DeviceProbe = browserProbe(),
): boolean {
  return forcedTouch(search) ?? looksLikeTouch(probe);
}

/**
 * Calls `onTouch` the first time a finger goes down. Returns a detach function.
 *
 * Three details, all of them load-bearing:
 *
 * - **`pointerType === "touch"` only.** A mouse click and a stylus are not thumbs. This
 *   is the rule `lib/lastInputSource.js` states and the one that keeps a desktop
 *   player from being handed an on-screen stick by clicking PLAY.
 * - **Capture phase.** The menus and the game stop propagation on their own pointer
 *   events; without capture, a first touch that landed on a button would be invisible.
 * - **Passive.** This never calls `preventDefault`, and saying so keeps it off the
 *   critical path of a scroll or a tap the game does handle.
 *
 * It detaches itself after firing: the question is "has touch been used at all", asked
 * once, and staying subscribed for the life of the page would be a listener on every
 * tap for an answer that cannot change.
 */
export function trackFirstTouch(target: Window, onTouch: () => void): () => void {
  const options = { capture: true, passive: true } as const;
  const onPointerDown = (event: PointerEvent) => {
    if (event.pointerType !== "touch") return;
    detach();
    onTouch();
  };
  const detach = () => target.removeEventListener("pointerdown", onPointerDown, options);
  target.addEventListener("pointerdown", onPointerDown, options);
  return detach;
}
