// Resolved per-run ship stats.
//
// The seam the whole progression layer hangs off, stated as the roadmap states it:
// **the simulation never knows what an upgrade is.** It sees a `ShipStats`, folded once
// at run start, and nothing else. Adding an upgrade is an edit to a catalog plus at
// most a new `StatKey`; it is never an edit to a system.
//
// ── Why adds run before muls ─────────────────────────────────────────────────────
//
// `+50 then ×2` is 300; `×2 then +50` is 250. Some order has to be chosen, and the
// obvious candidates are both wrong in the same way:
//
//   * CATALOG ORDER makes the result depend on how the file is arranged.
//   * SORTED BY ID — which the roadmap proposed — is deterministic, but it means
//     buying a NEW upgrade can change what the ones you already own are worth, purely
//     because its id sorts earlier. The shop would be lying about every number on it.
//
// Applying every add and then every mul makes the result a function of the SET of
// upgrades, not of their order or their ids. Determinism falls out rather than being
// arranged. The ids are still sorted within each pass, so floating-point summation
// order is fixed too — that matters less, but it costs one comparator and removes the
// last way two clients could disagree.
//
// This is also why `StatOp` has no "set": an override reintroduces exactly the
// order-sensitivity this avoids.
//
// ── Why rounding happens here ────────────────────────────────────────────────────
//
// `fireIntervalTicks` is a tick count that ends up in a `u16` cooldown column, and a
// ×0.8 on 9 lands on 7.2. Rounding where the value is USED would let two code paths
// reading the same loadout disagree about the fire rate — and the sim writing 7.2 into
// a `u16` would truncate silently. Resolving once, rounding once, is what makes the
// resolved def the single answer.

import type { ShipDef } from "@content/schemas/ship.js";
import type { StatKey, UpgradeDef } from "@content/schemas/upgrade.js";
import type { WeaponCatalog, WeaponDef } from "@content/schemas/weapon.js";

export interface ShipStats {
  readonly maxHealth: number;
  readonly radius: number;
  readonly boxSpeed: number;
  readonly aimRate: number;
  /**
   * Fully resolved — base weapon with every modifier already folded in. The only form
   * the simulation ever sees a weapon in, which is what lets two ships in the same
   * party carry differently-tuned versions of one authored gun with no catalog of
   * variants and no per-tick lookup.
   */
  readonly weapon: WeaponDef;
}

/**
 * The last-resort weapon.
 *
 * Reached only when a hull names a weapon the catalog does not have, which validated
 * content cannot do. A ship with no gun is worse than a ship with a dull one, and a
 * throw here would take down a run over a content typo.
 */
const FALLBACK_WEAPON: WeaponDef = {
  id: "weapon.fallback",
  fireIntervalTicks: 12,
  projectileLifetimeTicks: 90,
  projectileSpeed: 100,
  damage: 1,
  spread: 0.03,
  muzzleForward: 1.5,
  hitRadius: 0,
};

/** Working set: every modifiable stat as a plain number, before rounding. */
type StatBag = Record<StatKey, number>;

export function resolveShipStats(
  ship: ShipDef,
  weapons: WeaponCatalog,
  upgrades: readonly UpgradeDef[],
): ShipStats {
  const base = weapons[ship.weapon] ?? FALLBACK_WEAPON;

  // A copy, always. Folding in place would write back into loaded content — the bug
  // class from the old engine, where the editor mutated the live world object the run
  // was reading, and whose symptom here would be a second run starting with the first
  // run's upgrades already applied.
  const bag: StatBag = {
    maxHealth: ship.maxHealth,
    radius: ship.radius,
    boxSpeed: ship.boxSpeed,
    aimRate: ship.aimRate,
    damage: base.damage,
    fireIntervalTicks: base.fireIntervalTicks,
    projectileSpeed: base.projectileSpeed,
    projectileLifetimeTicks: base.projectileLifetimeTicks,
    spread: base.spread,
  };

  // Sorted by id so summation order is fixed. `slice()` first: sorting the caller's
  // array in place would reorder the loadout they handed us.
  const sorted = upgrades.slice().sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));

  for (const upgrade of sorted) {
    for (const modifier of upgrade.modifiers) {
      if (modifier.op === "add") bag[modifier.stat] += modifier.value;
    }
  }
  for (const upgrade of sorted) {
    for (const modifier of upgrade.modifiers) {
      if (modifier.op === "mul") bag[modifier.stat] *= modifier.value;
    }
  }

  return {
    // Floors rather than assertions: a stat driven to zero by stacked reductions is a
    // balance problem, not a crash, and the run should still be playable while someone
    // notices. CI rejects the authoring that would need these, so reaching one is a
    // signal rather than a routine event.
    maxHealth: Math.max(1, Math.round(bag.maxHealth)),
    radius: Math.max(1e-3, bag.radius),
    boxSpeed: Math.max(0, bag.boxSpeed),
    aimRate: Math.max(0, bag.aimRate),
    weapon: {
      ...base,
      damage: Math.max(1, Math.round(bag.damage)),
      // A cooldown of 0 fires every tick — 60 shots a second — which is not an upgrade.
      fireIntervalTicks: Math.max(1, Math.round(bag.fireIntervalTicks)),
      projectileLifetimeTicks: Math.max(1, Math.round(bag.projectileLifetimeTicks)),
      projectileSpeed: Math.max(1e-3, bag.projectileSpeed),
      // Negative would flip the sign of every random offset — the same cone mirrored,
      // which would read as an accuracy fix rather than as the bug it is.
      spread: Math.max(0, bag.spread),
    },
  };
}

/** Stats for a hull with nothing equipped. The default every slot starts from. */
export const baseShipStats = (ship: ShipDef, weapons: WeaponCatalog): ShipStats =>
  resolveShipStats(ship, weapons, []);
