/** Every knob at its identity value. What a player who never opens the menu flies. */
export const DEFAULT_DEBUG: DebugOverrides = {
  railSpeedScale: 1,
  boxSpeedScale: 1,
  aimRateScale: 1,
  hullScale: 1,
  playerFireRateScale: 1,
  playerDamageScale: 1,
  playerHitRadiusBonus: 0,
  enemyTurnRateScale: 1,
  enemyAimConeScale: 1,
  enemyFireRateScale: 1,
  enemyHealthScale: 1,
  enemySpeedScale: 1,
  enemyDamageScale: 1,
  hazardRateScale: 1,
  hazardMaxAliveScale: 1,
};

/** True when nothing has been turned, so the composition root can skip the fold. */
export const isDefaultDebug = (debug: DebugOverrides): boolean =>
  DEBUG_FIELDS.every((field) => debug[field.key] === field.default);

/**
 * Turns a fire-RATE multiplier into a fire-INTERVAL one, which means dividing.
 *
 * The menu says "FIRE RATE" and a player expects 2 to mean twice as many shots; the
 * content says `fireIntervalTicks` and twice as many shots is half the interval. Doing
 * that inversion in one named place is the only defence against the sign error, which
 * is invisible in code review and obvious in ten seconds of play — in the wrong
 * direction.
 *
 * A scale of 0 is "never fire" and cannot be expressed as an interval, so it becomes
 * the longest one this can produce rather than a division by zero.
 */
const scaleFireInterval = (ticks: number, rateScale: number): number =>
  rateScale <= 0 ? MUTE_INTERVAL_TICKS : Math.max(1, Math.round(ticks / rateScale));

/**
 * The interval a fire rate of 0 folds to: 10 minutes at 60 Hz.
 *
 * Not `Infinity` and not a huge number: the cooldown column is a `u16`, so anything
 * over 65535 wraps and a "ceasefire" becomes a machine gun. This is comfortably inside
 * that and comfortably longer than any run.
 */
const MUTE_INTERVAL_TICKS = 36000;

/** The rail's forward speed. Not rounded — it is a rate. */
export const applyDebugToRailSpeed = (speed: number, debug: DebugOverrides): number =>
  speed * debug.railSpeedScale;

/** How densely the ambient field seeds. Not rounded — it is a rate, not a count. */
export const applyDebugToHazardRate = (rate: number, debug: DebugOverrides): number =>
  rate * debug.hazardRateScale;

/** The cap on ambient hazards. A count, so rounded, and at least one. */
export const applyDebugToMaxAlive = (maxAlive: number, debug: DebugOverrides): number =>
  scaleInt(maxAlive, debug.hazardMaxAliveScale);

// The three folds below return their input BY REFERENCE when nothing has been turned,
// which is the same identity guarantee `difficulty.ts` gives NORMAL and it is load
// bearing for the same reason: an untouched debug document must leave the run building
// from the authored objects themselves, not from copies that happen to match.
//
// The guarantee is per-DOCUMENT rather than per-knob — turning the rail speed up still
// allocates a fresh ship def carrying the authored numbers. Refining it to per-knob
// would buy nothing: an allocation per run is not a cost, and a run built from a
// modified document is by definition not the shipped path.

/**
 * The hull the player flies with.
 *
 * Applied to the ship DEF, before `resolveShipStats` — same position as `scaleShip`, so
 * an upgrade that adds flat hull is worth the same however the knob is set.
 */
export function applyDebugToShip(ship: ShipDef, debug: DebugOverrides): ShipDef {
  if (isDefaultDebug(debug)) return ship;
  return {
    ...ship,
    maxHealth: scaleInt(ship.maxHealth, debug.hullScale),
    boxSpeed: ship.boxSpeed * debug.boxSpeedScale,
    aimRate: ship.aimRate * debug.aimRateScale,
  };
}

/**
 * The PLAYER's weapons.
 *
 * Kept separate from the enemy catalog and handed to `resolveShipStats` rather than to
 * `world.weaponCatalog`, which is what makes "the player's fire rate knob cannot reach
 * an enemy" structural rather than a promise. `difficulty.ts` explains the split at
 * length and this fold sits in exactly the same seam.
 */
export function applyDebugToPlayerWeapons(
  weapons: WeaponCatalog,
  debug: DebugOverrides,
): WeaponCatalog {
  if (isDefaultDebug(debug)) return weapons;
  const folded: Record<string, WeaponCatalog[string]> = {};
  for (const [id, weapon] of Object.entries(weapons)) {
    folded[id] = {
      ...weapon,
      fireIntervalTicks: scaleFireInterval(weapon.fireIntervalTicks, debug.playerFireRateScale),
      damage: scaleInt(weapon.damage, debug.playerDamageScale),
      hitRadius: weapon.hitRadius + debug.playerHitRadiusBonus,
    };
  }
  return folded;
}

/** The ENEMIES' weapons. Only the world catalog — see `applyDebugToPlayerWeapons`. */
export function applyDebugToEnemyWeapons(
  weapons: WeaponCatalog,
  debug: DebugOverrides,
): WeaponCatalog {
  if (isDefaultDebug(debug)) return weapons;
  const folded: Record<string, WeaponCatalog[string]> = {};
  for (const [id, weapon] of Object.entries(weapons)) {
    folded[id] = {
      ...weapon,
      fireIntervalTicks: scaleFireInterval(weapon.fireIntervalTicks, debug.enemyFireRateScale),
      damage: scaleInt(weapon.damage, debug.enemyDamageScale),
    };
  }
  return folded;
}

/** Enemy toughness, speed, and how quickly they can bring guns to bear. */
export function applyDebugToEnemies(
  enemies: readonly EnemyDef[],
  debug: DebugOverrides,
): readonly EnemyDef[] {
  if (isDefaultDebug(debug)) return enemies;
  // Mapped in place, never filtered or reordered: this array's ORDER is the `defId`
  // stored on every enemy instance and folded into the replay fingerprint.
  return enemies.map((def) => ({
    ...def,
    health: scaleInt(def.health, debug.enemyHealthScale),
    speed: def.speed * debug.enemySpeedScale,
    turnRate: def.turnRate * debug.enemyTurnRateScale,
    // Clamped to π, which is the whole sphere. A cone wider than that is not a wider
    // cone, and `canReturnFire` compares against it as an angle.
    aimCone: Math.min(Math.PI, def.aimCone * debug.enemyAimConeScale),
  }));
}
