// Per-rock pose, silhouette and tint — everything that makes a field of instances stop
// looking like a field of instances.
//
// Rocks were drawn at a fixed hash-derived orientation, at uniform scale, in one shared
// colour. Three consequences, and the first is the one that reads as "wrong" rather
// than merely "plain": **nothing tumbled**. A rock frozen in attitude while the ship
// flies past it does not look like a rock in space; it looks like scenery on a rail,
// which is exactly what it is and exactly what the renderer's job is to hide. Debris
// from a break-up is worse, because a piece that was just knocked off something is the
// one object a viewer expects to be spinning.
//
// ── Why this is derived and not stored ───────────────────────────────────────
//
// None of it is simulation state. It is computed from the ENTITY HANDLE, which is
// already replicated, so every client draws the same rock without a byte on the wire
// and without a column in the snapshot — the same argument the old `orientationFor`
// made, extended to the rest of the look. Generation is mixed in with the index
// throughout: entity slots are recycled, and without it a new rock would inherit the
// pose, shape and colour of the one whose slot it took.
//
// The clock is `world.tick`, never `performance.now()`. Two reasons and both matter:
// the tumble is then identical on every client rather than a function of how long each
// one has had its tab open, and a replay drawn at a checkpoint shows the rocks in the
// attitude they actually had.
//
// ── Why the silhouette never exceeds the collision sphere ────────────────────
//
// `HazardDef.radius` is what the simulation collides with, so a rock drawn wider than
// its radius on any axis would be visibly missed by shots that pass through it. Every
// scale factor here is therefore ≤ 1, and the anisotropy squashes rather than stretches
// — a rock is made narrower on two axes, never fatter on one. `rockGeometry.ts` holds
// the matching constraint for the baked vertex jitter.

import type { Color} from "three";
import { Quaternion, Vector3 } from "three";
import { entityGeneration, entityIndex, type Entity } from "@core/ecs.js";
import { lerp } from "@core/math/index.js";
import { mixSeed } from "@core/rng.js";
import { directionFromUniforms } from "./sampling.js";

/**
 * Salts, so one entity's several derived values are independent.
 *
 * `mixSeed` is a good hash but it is one 32-bit word, and four unrelated quantities do
 * not fit in 32 bits without correlating — a rock whose colour predicted its spin axis
 * would produce a field with a visible pattern in it, which is the failure this whole
 * module exists to avoid.
 */
const SALT = { rest: 1, tumble: 2, shape: 3, tint: 4 } as const;

const hash = (entity: Entity, salt: number): number =>
  mixSeed(entityIndex(entity), entityGeneration(entity), salt);

/** A `[0, 1)` sample from a 10-bit slice of a hash. Three disjoint slices fit. */
const unit = (h: number, shift: number): number => ((h >>> shift) & 0x3ff) / 0x400;

// ── Tumble ────────────────────────────────────────────────────────────────────

/**
 * Spin rate of a rock at `REFERENCE_RADIUS`, radians per second.
 *
 * Slow on purpose. The rail already moves the world past the player at 17 u/s, and a
 * rock spinning fast enough to notice on its own reads as debris from an explosion
 * rather than as a body that has been drifting for a very long time.
 */
const REFERENCE_SPIN = 0.35;

/** The radius `REFERENCE_SPIN` describes — the shipped medium rock. */
const REFERENCE_RADIUS = 1.4;

/**
 * Spread on the rate, as a multiplier range.
 *
 * Without it every rock of a given size turns at the same speed, which is a subtler
 * version of the problem this module fixes: the field reads as one animation rather
 * than as many objects.
 */
const SPIN_MIN = 0.45;
const SPIN_MAX = 1.7;

/**
 * Ceiling on the derived rate, radians per second.
 *
 * Smaller bodies spin faster — conservation of angular momentum through a break-up is
 * why real debris does — but the relationship is `1/r` and the small rock is a quarter
 * the reference radius, so without a cap the smallest debris strobes. 2.2 rad/s is
 * about a third of a second per turn: quick, still readable.
 */
const SPIN_MAX_RATE = 2.2;

const axis = new Vector3();
const spin = new Quaternion();
const rest = new Quaternion();

/** The attitude a rock rests at before it starts turning. Arbitrary, stable, uniform. */
function restingOrientation(entity: Entity, out: Quaternion): Quaternion {
  const h = hash(entity, SALT.rest);
  const a = unit(h, 0) * Math.PI * 2;
  const b = unit(h, 10) * Math.PI * 2;
  const c = unit(h, 20) * Math.PI * 2;
  // Written out rather than via `Euler` to keep a path that runs for every rock every
  // frame allocation-free.
  const [s1, c1] = [Math.sin(a / 2), Math.cos(a / 2)];
  const [s2, c2] = [Math.sin(b / 2), Math.cos(b / 2)];
  const [s3, c3] = [Math.sin(c / 2), Math.cos(c / 2)];
  return out.set(
    s1 * c2 * c3 + c1 * s2 * s3,
    c1 * s2 * c3 - s1 * c2 * s3,
    c1 * c2 * s3 + s1 * s2 * c3,
    c1 * c2 * c3 - s1 * s2 * s3,
  );
}

/** How fast this rock turns, radians per second. Smaller bodies turn faster. */
export function spinRateFor(entity: Entity, radius: number): number {
  const h = hash(entity, SALT.tumble);
  const spread = SPIN_MIN + unit(h, 20) * (SPIN_MAX - SPIN_MIN);
  // Guarded rather than trusted: a radius of 0 is not reachable from the catalog, and
  // an infinite spin rate from one bad def would be a NaN quaternion and an invisible
  // rock rather than a legible bug.
  const scale = REFERENCE_RADIUS / Math.max(radius, 0.05);
  return Math.min(SPIN_MAX_RATE, REFERENCE_SPIN * spread * scale);
}

/**
 * The orientation to draw a rock at, `seconds` into the run.
 *
 * A rotation about the rock's own axis, applied to its resting attitude. One axis
 * rather than a full inertia tensor: a free rigid body genuinely does tumble about more
 * than one axis, but the difference is invisible on a body that crosses the screen in
 * two seconds, and the cost is state this module deliberately does not keep.
 */
export function tumbleFor(
  entity: Entity,
  radius: number,
  seconds: number,
  out: Quaternion,
): Quaternion {
  const h = hash(entity, SALT.tumble);
  // Two disjoint slices of the hash, through the shared sampler — see `sampling.ts`
  // for why the obvious "sample both angles" version is wrong.
  directionFromUniforms(unit(h, 0), unit(h, 10), axis);
  // A phase offset from the resting hash, so rocks spawned on the same tick are not in
  // lockstep — visible when a split drops three pieces at once, which is the moment
  // this module is most on show.
  const phase = unit(hash(entity, SALT.rest), 0) * Math.PI * 2;
  spin.setFromAxisAngle(axis, phase + spinRateFor(entity, radius) * seconds);
  return out.multiplyQuaternions(spin, restingOrientation(entity, rest));
}

// ── Silhouette ────────────────────────────────────────────────────────────────

/**
 * How far from spherical a rock may be drawn.
 *
 * Applied as a SQUASH on two axes — the scale factors are ≤ 1 — so the drawn body stays
 * inside the collision sphere the simulation uses. Stretching one axis instead would
 * put geometry outside the hitbox, and "my shot went through it" is a far worse bug
 * than "that rock is round".
 */
const SQUASH_MIN = 0.75;

/**
 * The per-axis scale for one rock, before its radius is applied.
 *
 * Real asteroids are lumpy ellipsoids rather than spheres, and this is most of what
 * makes a small set of baked shapes stop reading as a small set: the same geometry
 * squashed on two different axes has two different outlines.
 */
export function silhouetteFor(entity: Entity, out: Vector3): Vector3 {
  const h = hash(entity, SALT.shape);
  // One axis stays at full radius so the body still fills its collision sphere in at
  // least one direction; the other two are squashed independently.
  const a = SQUASH_MIN + unit(h, 0) * (1 - SQUASH_MIN);
  const b = SQUASH_MIN + unit(h, 10) * (1 - SQUASH_MIN);
  // Which axis keeps full length is itself varied, or every rock would be an ellipsoid
  // pointing the same way in its own frame — invisible on one rock, obvious on fifty.
  switch ((h >>> 20) % 3) {
    case 0:
      return out.set(1, a, b);
    case 1:
      return out.set(a, 1, b);
    default:
      return out.set(a, b, 1);
  }
}

// ── Tint ──────────────────────────────────────────────────────────────────────

/**
 * The palette rocks vary within, as HSL ranges around the material's base brown-grey.
 *
 * A field in one flat colour is the other half of what made these read as instances: at
 * a distance, identical shading is a stronger clone signal than identical shape, and it
 * is what makes a rock look like painted plastic rather than stone. The range is
 * deliberately narrow — this is one asteroid field, not a bag of marbles.
 */
const HUE = { min: 0.05, max: 0.11 };
const SATURATION = { min: 0.04, max: 0.16 };
const LIGHTNESS = { min: 0.3, max: 0.62 };

/** A stable per-rock tint, multiplied into the shared material's colour. */
export function tintFor(entity: Entity, out: Color): Color {
  const h = hash(entity, SALT.tint);
  return out.setHSL(
    lerp(HUE.min, HUE.max, unit(h, 0)),
    lerp(SATURATION.min, SATURATION.max, unit(h, 10)),
    lerp(LIGHTNESS.min, LIGHTNESS.max, unit(h, 20)),
  );
}
