// The HUD, as a pure model over simulation state.
//
// Split deliberately in two. `hudModel` reads the world and returns numbers and
// strings; `createHud` (in `hudView.ts`) draws them. Nothing in this file touches the
// DOM, which is what lets the interesting half be tested headlessly — and the
// interesting half really is all of it, because everything a HUD does is arithmetic
// over state the simulation already holds.
//
// It is a READ. The HUD is downstream of everything, and a model that nudged state
// would make the replay fingerprint depend on whether anyone was looking at the
// screen — which in multiplayer means a host and a headless client diverge.

import { ticksToSeconds } from "@core/loop.js";
import { clamp } from "@core/math/index.js";
import { AIM_MODES, VIEW_MODES, type AimMode, type ViewMode } from "@sim/flight.js";
import { chooseCourse, TRUNK_COURSE, type Fork, type RailNetwork } from "@sim/rail.js";
import { selectionContext } from "@sim/systems/forks.js";
import type { BranchSelector } from "@content/schemas/level.js";
import type { RunOutcome, SimWorld } from "@sim/world.js";

export interface HudModel {
  readonly health: number;
  readonly maxHealth: number;
  /** `health / maxHealth`, clamped to [0, 1] — a bar width, not a raw ratio. */
  readonly healthFraction: number;
  readonly hazardKills: number;
  readonly enemyKills: number;
  /** Distance along the CURRENT course, as [0, 1]. */
  readonly progress: number;
  readonly outcome: RunOutcome;
  readonly held: boolean;
  /** What the stop is asking for, or null. Live — a destroy-N counts down. */
  readonly heldLabel: string | null;
  /** The EFFECTIVE aim mode, including one a stop is forcing over the player's. */
  readonly aimMode: AimMode;
  /**
   * Whether the aim mode is anything other than the resting one.
   *
   * F is a TOGGLE, and a toggle with no indicator is a control the player has to
   * discover by flying into the cone limit and inferring which side of it they are on.
   * Named in the model rather than derived in the renderer so the meaning of "engaged"
   * has one definition — an omni stop engages it too, and it is not the mode F selects.
   */
  readonly aimModeEngaged: boolean;
  /**
   * Whether a STOP is imposing the mode over the player's own toggle.
   *
   * The distinction matters at exactly the moment it is confusing: while parked at an
   * omni stop, pressing F changes the stored preference and nothing visible happens.
   * An indicator that did not say why would look broken.
   */
  readonly aimModeForced: boolean;
  /** Short caption for the aim indicator. Presentation, but pinned by a spec. */
  readonly aimModeLabel: string;
  readonly viewMode: ViewMode;
  readonly wavesReleased: number;
  readonly wavesTotal: number;
  /** Banked this run. What M3's shop will spend. */
  readonly credits: number;
}

/**
 * What each aim mode is called on screen.
 *
 * "LOCK FWD" rather than "FORWARD": the mode is a restriction, and naming it after the
 * restriction is what tells a player why their reticle stopped moving. The old engine
 * called the same control `toggleAimLock` and that word is the one testers use.
 */
const AIM_MODE_LABELS: Readonly<Record<AimMode, string>> = {
  free: "FREE",
  forward: "LOCK FWD",
  omni: "OMNI",
};

/** Reads the world into a HUD model. Pure. */
export function hudModel(world: SimWorld, slot = 0): HudModel {
  const { ship, viewState } = world.components;
  const entity = world.shipBySlot[slot];
  const s = entity === undefined ? -1 : ship.row(entity);
  const v = entity === undefined ? -1 : viewState.row(entity);

  const stats = world.statsFor(slot);
  const maxHealth = stats.maxHealth;
  // An empty slot reads as an empty hull rather than throwing: the HUD is drawn every
  // frame including the ones where a player has not joined yet.
  const health = s < 0 ? 0 : ship.columns.health[s]!;

  // The EFFECTIVE mode. A stop overrides the player's own toggle while parked, and
  // showing the preference instead would tell them the opposite of what is true.
  const aimMode: AimMode =
    world.forcedAimMode ?? (v < 0 ? "free" : AIM_MODES[viewState.columns.aimMode[v]!] ?? "free");

  const course = world.rail?.courses[world.courseId];
  // Guarding the length as well as the rail: a zero-length course would divide to
  // Infinity and paint a full bar on a run that has not started.
  const progress =
    course && course.length > 0 ? clamp(world.railS / course.length, 0, 1) : 0;

  return {
    health,
    maxHealth,
    // Clamped here rather than in the renderer, so every renderer gets it right.
    // Health is signed so overkill is representable; a bar of negative width is not.
    healthFraction: maxHealth > 0 ? clamp(health / maxHealth, 0, 1) : 0,
    hazardKills: world.hazardsDestroyed,
    enemyKills: world.enemiesDestroyed,
    progress,
    outcome: world.outcome,
    held: world.stop.active,
    heldLabel: world.stop.active ? stopLabel(world) : null,
    aimMode,
    // "Engaged" is about the LIMIT the player is flying under, not about which key was
    // pressed — so an omni stop lights the indicator as surely as F does.
    aimModeEngaged: aimMode !== "free",
    aimModeForced: world.forcedAimMode !== null,
    aimModeLabel: AIM_MODE_LABELS[aimMode],
    viewMode: v < 0 ? "cockpit" : VIEW_MODES[viewState.columns.viewMode[v]!] ?? "cockpit",
    wavesReleased: world.nextWave,
    wavesTotal: world.waves.length,
    credits: world.credits,
  };
}

/**
 * What the parked rail is asking for, counted down live.
 *
 * A static caption would be worse than useless on a destroy-N stop: the player needs
 * to know how many are LEFT, and the number the stop measures against is a baseline
 * captured on arrival rather than the raw kill count.
 */
function stopLabel(world: SimWorld): string | null {
  const course = world.rail?.courses[world.courseId];
  const spec = course?.waypointAt(world.stop.waypoint).stop;
  if (!spec) return null;

  switch (spec.advance.type) {
    case "destroyed": {
      const done = world.hazardsDestroyed - world.stop.killBaseline;
      return `DESTROY ${Math.max(0, spec.advance.count - done)}`;
    }
    case "time": {
      const elapsed = ticksToSeconds(world.stop.elapsedTicks, world.hz);
      return `HOLD ${Math.max(0, Math.ceil(spec.advance.seconds - elapsed))}`;
    }
    case "damage":
      return "TAKE A HIT";
  }
}

// ── The debug rail readout ──────────────────────────────────────────────────────
//
// Why this exists: The Narrows ships the game's first authored TRIGGER fork — clear the
// gate wave and the rail takes the low route — and flown by hand, clearing the wave and
// ignoring it were indistinguishable. The fork commits SILENTLY: `courseId` changes, the
// rail guide quietly rebuilds for the new course, and nothing on screen ever named the
// decision, said where it was, or said whether the trigger had fired.
//
// Deliberately NOT a field on `HudModel`. `hudModel` runs every frame on the shipped
// path and this builds a set of fired triggers and evaluates a selector; keeping it
// separate means the shipped path pays nothing and no existing HUD assertion moves.
// `app/main.ts` calls it only while the debug flag is on.

/** The next fork ahead, and what would happen if it committed right now. */
export interface ForkReadout {
  /** `"<parent|trunk>:<atWaypoint>"` — the key the level's `selectors` are keyed by. */
  readonly key: string;
  readonly commitS: number;
  /**
   * Rail distance still to run before the choice locks in.
   *
   * Measured to `commitS`, NOT to the fork waypoint, and the difference is the whole
   * commit rule: the choice is made one full segment early, where every course through
   * the fork still has identical geometry. A readout counting down to the visible split
   * would tell the player they still had a decision to make for the ~66 units after it
   * had already been taken.
   */
  readonly distance: number;
  readonly selectorKind: BranchSelector["kind"];
  /** The trigger a `trigger` selector waits on, or null for `partyLateral`. */
  readonly triggerId: string | null;
  readonly triggerFired: boolean;
  /** Course `chooseCourse` would pick if the fork committed on this tick. */
  readonly wouldTakeCourse: number;
  /** ...named: the branch id that course ends on, or `"trunk"`. */
  readonly wouldTakeBranch: string;
}

export interface RailReadout {
  readonly courseId: number;
  /** Branch id the current course ends on, or `"trunk"`. */
  readonly courseBranch: string;
  readonly railS: number;
  readonly courseLength: number;
  /** Forks on this course already behind the party. */
  readonly forksResolved: number;
  readonly nextFork: ForkReadout | null;
  readonly firedTriggers: readonly string[];
}

/**
 * Reads the party's rail state into a debug readout. Pure.
 *
 * The line that matters is `wouldTakeCourse`: it answers "if this committed right now,
 * where would I go?", which is the question a player standing in front of an invisible
 * fork actually has. It calls the same `chooseCourse` the simulation calls, through the
 * same `selectionContext` — see the note on that export for why a second copy would be
 * worse than no readout at all.
 */
export function railReadout(world: SimWorld): RailReadout {
  const rail = world.rail;
  const course = rail?.courses[world.courseId];
  const empty: RailReadout = {
    courseId: world.courseId,
    courseBranch: TRUNK_COURSE,
    railS: world.railS,
    courseLength: 0,
    forksResolved: 0,
    nextFork: null,
    firedTriggers: world.firedTriggers,
  };
  if (!rail || !course) return empty;

  const forks = rail.forksOn(world.courseId);
  // `lastForkS` is the single float the fork system resolves everything against — a
  // fork is decided exactly when its commit point is at or behind it. Counting the same
  // way here means the readout cannot disagree with the system about what is left.
  const forksResolved = forks.filter((fork) => fork.commitS <= world.lastForkS).length;
  const next = rail.nextForkOn(world.courseId, Math.max(world.railS, world.lastForkS + 1e-9));

  return {
    courseId: world.courseId,
    courseBranch: rail.courseBranch(world.courseId) ?? TRUNK_COURSE,
    railS: world.railS,
    courseLength: course.length,
    forksResolved,
    nextFork: next === null ? null : forkReadout(world, rail, next),
    firedTriggers: world.firedTriggers,
  };
}

function forkReadout(world: SimWorld, rail: RailNetwork, fork: Fork): ForkReadout {
  const selector = fork.selector;
  const wouldTakeCourse = chooseCourse(fork, selectionContext(world));

  return {
    key: fork.key,
    commitS: fork.commitS,
    distance: fork.commitS - world.railS,
    selectorKind: selector.kind,
    triggerId: selector.kind === "trigger" ? selector.triggerId : null,
    triggerFired: selector.kind === "trigger" && world.hasTrigger(selector.triggerId),
    wouldTakeCourse,
    wouldTakeBranch: rail.courseBranch(wouldTakeCourse) ?? TRUNK_COURSE,
  };
}
