// The enemy catalog.
//
// Authored in TypeScript for the same reason the hazards are: versioned JSON with a
// migration chain is later M2 work, and moving this twice costs more than moving it
// once. What matters now is that the SHAPE is the authored shape — validated by
// `content/validation/enemy.ts`, consumed by `sim` through a def id, never hardcoded
// in a system.
//
// Three archetypes, one per movement behaviour, so every branch of `EnemyBehavior` is
// exercised by shipped content rather than only by a fixture. Their numbers are first
// guesses: nothing here has been flown yet, and the tuning pass belongs after it has.

import type { EnemyCatalog, EnemyDef } from "../schemas/enemy.js";
import { ENEMY_BLASTER } from "../weapons/index.js";
import { CREDITS, REPAIR } from "../pickups/index.js";

/**
 * Sits on the rail and waits. The cheap one, and the one a level uses to make a
 * corridor dangerous rather than to make a fight.
 */
export const DRONE: EnemyDef = {
  id: "enemy.drone",
  radius: 1.1,
  health: 3,
  variants: 2,
  speed: 26,
  turnRate: 2.2,
  behavior: { kind: "station" },
  // 150 ticks is 2.5s a cycle, slowed from 90 after flying it. The weave exists to
  // make a drone a moving target, not to make it a coin flip: at 1.5s the lateral
  // travel outran a thumb, so hitting one was mostly a matter of firing enough. The
  // AMPLITUDE is untouched — the dodge is still the same size, it just takes longer.
  weave: { amplitude: 2.5, periodTicks: 150 },
  weapon: ENEMY_BLASTER.id,
  aimCone: 0.35,
  fireRange: 120,
  contactDamage: 20,
  // The common enemy pays out rarely; the run's hull economy is meant to be tight.
  drops: { pickup: CREDITS.id, chance: 0.35 },
};

/**
 * Runs ahead of the party at a fixed lead, firing back.
 *
 * Faster than any rail speed the levels use, which is a requirement rather than a
 * flourish: an escort slower than the party is overtaken immediately and the behaviour
 * degenerates into a station.
 */
export const INTERCEPTOR: EnemyDef = {
  id: "enemy.interceptor",
  radius: 1.2,
  health: 4,
  variants: 2,
  speed: 52,
  turnRate: 2.6,
  behavior: { kind: "escort" },
  // Slowed from 70 for the same reason, and still the quicker of the two: an
  // interceptor is meant to read as the more agile archetype, so the gap between the
  // two periods is preserved rather than flattened.
  weave: { amplitude: 3.5, periodTicks: 120 },
  weapon: ENEMY_BLASTER.id,
  aimCone: 0.4,
  fireRange: 100,
  contactDamage: 22,
  drops: { pickup: REPAIR.id, chance: 0.3 },
};

/**
 * Closes head-on and passes through the party.
 *
 * No weave: it is only in front of the player for a couple of seconds, and a lateral
 * oscillation on top of a closing approach reads as noise rather than as movement.
 */
export const LANCER: EnemyDef = {
  id: "enemy.lancer",
  radius: 1.4,
  health: 5,
  variants: 1,
  speed: 70,
  turnRate: 3,
  behavior: { kind: "charger", closeSpeed: 26 },
  weapon: ENEMY_BLASTER.id,
  aimCone: 0.45,
  fireRange: 90,
  contactDamage: 30,
  // The most dangerous archetype is the most reliable repair — the reward for taking
  // the fight rather than dodging it.
  drops: { pickup: REPAIR.id, chance: 0.6 },
};

export const ENEMIES: EnemyCatalog = {
  [DRONE.id]: DRONE,
  [INTERCEPTOR.id]: INTERCEPTOR,
  [LANCER.id]: LANCER,
};

/**
 * The catalog as an ORDERED list. This order is the `defId` stored on every enemy
 * instance, so it is part of the wire format and part of every replay fingerprint:
 * appending is safe, reordering or removing is not. Same rule as component
 * registration order and `HAZARD_ORDER`, for the same reason.
 */
export const ENEMY_ORDER: readonly EnemyDef[] = [DRONE, INTERCEPTOR, LANCER];
