// Stick sensitivity, as two sliders.
//
// One component mounted by BOTH the title screen and the game-over overlay, for the
// same reason the difficulty picker is: two copies of a control would eventually
// disagree about the range, the labels, or which value is showing.
//
// A range input rather than the chip row difficulty uses, because this is a continuous
// quantity and three named steps would be a worse answer to "a little less sensitive"
// than a slider is. It is also the one native control that is already thumb-friendly
// and already accessible.
//
// Unlike difficulty, a change here needs NO confirm and NO restart: it is a `ui/`
// number that decides how far a thumb travels for a full axis, and the simulation
// never hears about it. That asymmetry is the point of putting settings on these two
// screens rather than behind a pause — see the header of `settingsStore.ts`.
//
// ── It is hidden until there is a stick to scale ──────────────────────────────
//
// What these sliders divide is the RADIUS of an on-screen stick (`ui/touch.ts`), so on
// a keyboard they scale nothing and offering them is worse than offering nothing: two
// controls that visibly do not work, on the first screen anyone sees. Visibility
// follows `controls.touchActive` rather than a second sniff — including when that
// becomes true mid-session on a first touch, which is why it is a method and not a
// constructor argument. See `ui/inputSource.ts`.

import {
  SENSITIVITY_MAX,
  SENSITIVITY_MIN,
  SENSITIVITY_STEP,
  type StickSensitivity,
} from "./settingsStore.js";

const STYLE = `
.sw-set { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.sw-set-hidden { display: none; }
.sw-set-label {
  font: 600 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.22em; color: #7e8ea8; text-shadow: none;
}
.sw-set-row {
  display: flex; align-items: center; gap: 12px;
  font: 600 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.14em; color: #9fb2cc; text-shadow: none;
}
.sw-set-name { width: 56px; text-align: right; }
.sw-set-value { width: 34px; text-align: left; color: #cddcf0; }
.sw-set-slider {
  pointer-events: auto;
  -webkit-appearance: none; appearance: none;
  width: 190px; height: 32px; background: transparent;
  touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  cursor: pointer;
}
.sw-set-slider::-webkit-slider-runnable-track {
  height: 4px; border-radius: 2px; background: rgba(60,90,135,0.9);
}
.sw-set-slider::-moz-range-track {
  height: 4px; border-radius: 2px; background: rgba(60,90,135,0.9);
}
/* 28px is a thumb-sized grab handle on a 4px track — the track is what you read, the
   handle is what you hit. */
.sw-set-slider::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 28px; height: 28px; margin-top: -12px; border-radius: 50%;
  background: #6fa2dd; border: 1px solid #a8ccf0;
}
.sw-set-slider::-moz-range-thumb {
  width: 28px; height: 28px; border-radius: 50%;
  background: #6fa2dd; border: 1px solid #a8ccf0;
}
`;

let stylesInstalled = false;

function installStyles(): void {
  if (stylesInstalled) return;
  const style = document.createElement("style");
  style.dataset.swSettings = "";
  style.textContent = STYLE;
  document.head.appendChild(style);
  stylesInstalled = true;
}

export interface SettingsPanelOptions {
  readonly initial: StickSensitivity;
  /** Called on every move of either slider. Applies live — there is nothing to rebuild. */
  readonly onChange: (sensitivity: StickSensitivity) => void;
}

export interface SettingsPanel {
  readonly root: HTMLElement;
  /** Reflects a value set on the other screen's copy, without firing `onChange`. */
  set(sensitivity: StickSensitivity): void;
  /** Shows or hides the whole panel. Hidden until there is a stick to scale. */
  setVisible(visible: boolean): void;
  dispose(): void;
}

export function createSettingsPanel(options: SettingsPanelOptions): SettingsPanel {
  installStyles();

  const root = document.createElement("div");
  root.className = "sw-set";

  const heading = document.createElement("div");
  heading.className = "sw-set-label";
  heading.textContent = "STICK SENSITIVITY";
  root.appendChild(heading);

  let current: StickSensitivity = options.initial;

  const build = (key: keyof StickSensitivity, label: string) => {
    const row = document.createElement("div");
    row.className = "sw-set-row";

    const name = document.createElement("span");
    name.className = "sw-set-name";
    name.textContent = label;

    const slider = document.createElement("input");
    slider.type = "range";
    slider.className = "sw-set-slider";
    slider.dataset.sensitivity = key;
    slider.min = String(SENSITIVITY_MIN);
    slider.max = String(SENSITIVITY_MAX);
    slider.step = String(SENSITIVITY_STEP);
    slider.value = String(current[key]);

    const value = document.createElement("span");
    value.className = "sw-set-value";
    value.dataset.sensitivityValue = key;
    value.textContent = current[key].toFixed(1);

    // `input` rather than `change`: a slider dragged with a thumb should take effect as
    // it moves, so the player can feel what they are choosing instead of committing
    // blind and checking afterwards.
    const onInput = (event: Event) => {
      event.stopPropagation();
      const next = Number.parseFloat(slider.value);
      if (!Number.isFinite(next)) return;
      current = { ...current, [key]: next };
      value.textContent = next.toFixed(1);
      options.onChange(current);
    };
    slider.addEventListener("input", onInput);

    row.append(name, slider, value);
    root.appendChild(row);
    return { slider, value, detach: () => slider.removeEventListener("input", onInput) };
  };

  // Aim first: it is the one that prompted the setting, and the one a player is most
  // likely to want to change.
  const aim = build("aim", "AIM");
  const slide = build("slide", "SLIDE");

  // Hidden by default rather than shown: the panel is mounted by screens that exist
  // before anyone knows whether this is a phone, and a panel that flickered away on a
  // desktop would be worse than one that arrives when a finger does.
  root.classList.add("sw-set-hidden");

  return {
    root,
    setVisible(visible) {
      root.classList.toggle("sw-set-hidden", !visible);
    },
    set(sensitivity) {
      current = sensitivity;
      aim.slider.value = String(sensitivity.aim);
      aim.value.textContent = sensitivity.aim.toFixed(1);
      slide.slider.value = String(sensitivity.slide);
      slide.value.textContent = sensitivity.slide.toFixed(1);
    },
    dispose() {
      aim.detach();
      slide.detach();
      root.remove();
    },
  };
}
