// Deterministic hazard splitting.
//
// A large rock breaking apart needs randomness — which way each piece goes — and that
// randomness has to be identical on every client, because the pieces are real entities
// that get shot, rammed, and scored. Getting this wrong is not a cosmetic desync; the
// two players end up with different worlds.
//
// The obvious tool is `world.rng.fork()`. It is the wrong one here, and the reason is
// worth stating because it is not obvious:
//
//   `fork()` derives its child from the parent's CURRENT state, which means it calls
//   `uint32()` and therefore ADVANCES the parent. Splits are conditional — they happen
//   only when a rock with `splitsInto` dies, which depends on where the player aimed.
//   Forking per split would make the ambient spawner's placements depend on how many
//   rocks the player happened to break, because both draw from the same stream. Every
//   later spawn would shift.
//
// So the split stream is derived from STABLE IDENTITY instead — the entity being
// destroyed, the tick, and the run seed — through `mixSeed`, which touches no existing
// stream at all. Consequences worth having:
//
//   * The number of splits in a tick cannot perturb any other system's randomness.
//   * Two rocks splitting on the same tick are independent of each other and of the
//     order they are processed in.
//   * A client that rewinds and replays a tick reproduces the same debris, because the
//     inputs to the derivation are all state it already has.
//
// `fork()` remains the right tool where the derivation happens unconditionally at a
// known point — a wave's stream, say, taken once when the wave begins.

import { entityGeneration, entityIndex, type Entity } from "@core/ecs.js";
import { mixSeed, Rng } from "@core/rng.js";
import { Vec3 } from "@core/math/index.js";
import type { HazardDef, HazardSplit } from "@content/schemas/hazard.js";

/**
 * A random stream belonging to one entity's destruction on one tick.
 *
 * Generation is mixed in alongside the index: entity indices are recycled, so index
 * alone would give a slot's second occupant the same debris as its first.
 */
export function splitRngFor(entity: Entity, tick: number, seed: number): Rng {
  return new Rng(mixSeed(seed, tick, entityIndex(entity), entityGeneration(entity)));
}

/** One child produced by a split: where it starts and how fast it is moving. */
export interface SplitChild {
  readonly position: Vec3;
  readonly velocity: Vec3;
}

/**
 * Computes where a hazard's children go when it breaks.
 *
 * Pure: same arguments, same result, no shared state touched. That is what lets the
 * caller be a plain method on the world rather than a system with ordering constraints,
 * and what makes the property testable directly rather than through a whole run.
 *
 * Children are scattered on a sphere around the parent rather than in a disc, because
 * the rail can be climbing and a disc would need a plane to lie in — which would mean
 * reading the rail frame, coupling splitting to rail geometry for no visible gain.
 */
export function computeSplit(
  parentPosition: Vec3,
  parentVelocity: Vec3,
  split: HazardSplit,
  childDef: HazardDef,
  rng: Rng,
): SplitChild[] {
  const children: SplitChild[] = [];
  const direction = new Vec3();

  for (let i = 0; i < split.count; i++) {
    // Two draws per child, always — the same fixed-draw-count discipline the spawner
    // follows. A rejection loop here would make the stream depend on geometry.
    rng.onUnitSphere(direction);

    children.push({
      // Offset by the child's own radius so the pieces start clear of each other
      // rather than interpenetrating and resolving on the first collision tick.
      position: parentPosition.clone().addScaledVector(direction, childDef.radius),
      // Inherit the parent's motion, then push outward. Inheriting matters once
      // hazards drift: debris from a moving rock should keep travelling with it.
      velocity: parentVelocity.clone().addScaledVector(direction, split.scatterSpeed),
    });
  }

  return children;
}
