// Who a thing belongs to.
//
// Small enough to look like it belongs inline somewhere, and deliberately not: the
// value is stored in a component column, read by collision, written by two different
// firing paths, and will be read by the netcode. A magic 0/1 in five places is how a
// projectile ends up damaging the ship that fired it.
//
// Hazards have no faction. They are not hostile — they are terrain that hurts, and
// giving them one would imply enemy fire should destroy rocks, which it deliberately
// does not (see the note in `systems/collision.ts`).

export const Faction = {
  Player: 0,
  Enemy: 1,
} as const;

export type FactionId = (typeof Faction)[keyof typeof Faction];
