// The difficulty chips, built once and used by both screens.
//
// One component rather than two, because the title screen and the game-over overlay
// must not be able to disagree about what the options are or which one is selected —
// and because the confirm step below is the kind of thing that gets implemented on one
// screen and forgotten on the other.
//
// The styles are injected by `installDifficultyStyles`, called by whichever screen
// mounts first; both screens share one stylesheet so the chips look identical.

import { DIFFICULTY_ORDER, type DifficultyDef } from "@content/difficulty/index.js";

const STYLE = `
.sw-diff { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.sw-diff-label {
  font: 600 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.22em; color: #7e8ea8; text-shadow: none;
}
.sw-diff-row { display: flex; gap: 10px; }
.sw-diff-chip {
  pointer-events: auto;
  font: 600 13px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.16em; color: #9fb2cc;
  background: rgba(12,22,40,0.85); border: 1px solid #2f4a70; border-radius: 9px;
  padding: 0 18px; min-height: 44px; min-width: 88px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  text-shadow: none;
  transition: background-color 100ms linear, color 100ms linear, border-color 100ms linear;
}
.sw-diff-chip[aria-pressed="true"] {
  background: rgba(60,120,190,0.6); color: #f0f7ff; border-color: #6fa2dd;
}
.sw-diff-chip:active { transform: scale(0.96); }
/* Same look, different class: sw-diff-chip must mean "a difficulty option" and
   nothing else, or counting the options also counts these two. */
.sw-diff-confirm-btn {
  pointer-events: auto;
  font: 600 13px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.16em; color: #9fb2cc;
  background: rgba(12,22,40,0.85); border: 1px solid #2f4a70; border-radius: 9px;
  padding: 0 18px; min-height: 44px; min-width: 88px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  text-shadow: none;
}
.sw-diff-confirm-btn[data-confirm="yes"] { color: #f0f7ff; border-color: #6fa2dd; }
.sw-diff-confirm-btn:active { transform: scale(0.96); }

/* The confirm step, shown in place of the chips when a change would cost a run. */
.sw-diff-confirm {
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  font: 600 12px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.1em; color: #cddcf0; text-shadow: none; text-align: center;
}
.sw-diff-confirm-row { display: flex; gap: 10px; }
.sw-diff-hidden { display: none; }
`;

let stylesInstalled = false;

export function installDifficultyStyles(): void {
  if (stylesInstalled) return;
  const style = document.createElement("style");
  style.dataset.swDifficulty = "";
  style.textContent = STYLE;
  document.head.appendChild(style);
  stylesInstalled = true;
}

export interface DifficultyPickerOptions {
  /** The one shown as selected when the picker is built. */
  readonly initial: DifficultyDef;
  /**
   * Whether picking a different one needs confirming first.
   *
   * True on the game-over screen, where a change restarts from the beginning and the
   * player has a result on screen they might not want to throw away. False on the
   * title screen, where there is no run to lose and a confirm would be pure friction.
   */
  readonly confirmChange?: boolean;
  /** Wording for the confirm step. */
  readonly confirmText?: string;
  /** Called once the choice is settled — after confirming, if a confirm was needed. */
  readonly onChange: (difficulty: DifficultyDef) => void;
}

export interface DifficultyPicker {
  readonly root: HTMLElement;
  /** Reflects a choice made elsewhere without firing `onChange`. */
  select(difficulty: DifficultyDef): void;
  /** Drops any half-finished confirm, so reopening a screen starts clean. */
  reset(): void;
  dispose(): void;
}

export function createDifficultyPicker(options: DifficultyPickerOptions): DifficultyPicker {
  installDifficultyStyles();

  const root = document.createElement("div");
  root.className = "sw-diff";

  const label = document.createElement("div");
  label.className = "sw-diff-label";
  label.textContent = "DIFFICULTY";

  const row = document.createElement("div");
  row.className = "sw-diff-row";

  const confirm = document.createElement("div");
  confirm.className = "sw-diff-confirm sw-diff-hidden";
  const confirmMessage = document.createElement("div");
  const confirmRow = document.createElement("div");
  confirmRow.className = "sw-diff-confirm-row";
  const confirmYes = document.createElement("button");
  confirmYes.type = "button";
  confirmYes.className = "sw-diff-confirm-btn";
  confirmYes.dataset.confirm = "yes";
  confirmYes.textContent = "RESTART";
  const confirmNo = document.createElement("button");
  confirmNo.type = "button";
  confirmNo.className = "sw-diff-confirm-btn";
  confirmNo.dataset.confirm = "no";
  confirmNo.textContent = "CANCEL";
  confirmRow.append(confirmYes, confirmNo);
  confirm.append(confirmMessage, confirmRow);

  root.append(label, row, confirm);

  let selected = options.initial;
  let pending: DifficultyDef | null = null;

  const chips = new Map<string, HTMLButtonElement>();
  const paint = () => {
    for (const [id, chip] of chips) chip.setAttribute("aria-pressed", String(id === selected.id));
  };

  const showChips = (show: boolean) => {
    label.classList.toggle("sw-diff-hidden", !show);
    row.classList.toggle("sw-diff-hidden", !show);
    confirm.classList.toggle("sw-diff-hidden", show);
  };

  const commit = (difficulty: DifficultyDef) => {
    selected = difficulty;
    pending = null;
    paint();
    showChips(true);
    options.onChange(difficulty);
  };

  const onChipClick = (difficulty: DifficultyDef) => (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    // Re-picking what is already selected is a no-op, not a restart. Otherwise the
    // confirm would fire for a tap that changes nothing.
    if (difficulty.id === selected.id) return;

    if (!options.confirmChange) {
      commit(difficulty);
      return;
    }
    pending = difficulty;
    confirmMessage.textContent =
      options.confirmText ?? `Start a new run on ${difficulty.label}?`;
    showChips(false);
  };

  for (const difficulty of DIFFICULTY_ORDER) {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "sw-diff-chip";
    chip.dataset.difficulty = difficulty.id;
    chip.textContent = difficulty.label;
    chip.addEventListener("click", onChipClick(difficulty));
    row.appendChild(chip);
    chips.set(difficulty.id, chip);
  }
  paint();

  const onYes = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    if (pending) commit(pending);
  };
  const onNo = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    pending = null;
    showChips(true);
  };
  confirmYes.addEventListener("click", onYes);
  confirmNo.addEventListener("click", onNo);

  return {
    root,
    select(difficulty) {
      selected = difficulty;
      pending = null;
      paint();
      showChips(true);
    },
    reset() {
      pending = null;
      showChips(true);
    },
    dispose() {
      confirmYes.removeEventListener("click", onYes);
      confirmNo.removeEventListener("click", onNo);
      root.remove();
    },
  };
}
