// The upgrade catalog.
//
// Nothing in `sim` imports this. Upgrades are folded into a `ShipStats` before a run
// starts, and the simulation sees only the result — which is what lets the shop, the
// save format and the whole progression layer change without a system knowing.
//
// The numbers are first guesses. Nothing here has been played, and the balance pass
// belongs after the shop exists to buy them from.

import type { UpgradeCatalog, UpgradeDef } from "../schemas/upgrade.js";

export const REINFORCED_HULL: UpgradeDef = {
  id: "upgrade.hull",
  name: "Reinforced Hull",
  cost: 400,
  // Additive rather than multiplicative so stacking it reads as "two more hits" rather
  // than compounding into invulnerability.
  modifiers: [{ stat: "maxHealth", op: "add", value: 40 }],
};

export const RAPID_COILS: UpgradeDef = {
  id: "upgrade.rapidCoils",
  name: "Rapid Coils",
  cost: 550,
  // 0.8 of 9 ticks is 7.2, which rounds to 7 — see `resolveShipStats` on why tick
  // counts are rounded once at resolve time and never at the point of use.
  modifiers: [{ stat: "fireIntervalTicks", op: "mul", value: 0.8 }],
};

export const HEAVY_SLUGS: UpgradeDef = {
  id: "upgrade.heavySlugs",
  name: "Heavy Slugs",
  cost: 700,
  // Damage is a SHOT COUNT against hazard and enemy health, so +1 is a large step:
  // it takes a four-hit rock to two. Paired with a slower muzzle as the trade.
  modifiers: [
    { stat: "damage", op: "add", value: 1 },
    { stat: "projectileSpeed", op: "mul", value: 0.85 },
  ],
};

export const THRUSTER_TRIM: UpgradeDef = {
  id: "upgrade.thrusterTrim",
  name: "Thruster Trim",
  cost: 300,
  modifiers: [
    { stat: "boxSpeed", op: "mul", value: 1.25 },
    { stat: "aimRate", op: "mul", value: 1.15 },
  ],
};

export const BEAM_FOCUS: UpgradeDef = {
  id: "upgrade.beamFocus",
  name: "Beam Focus",
  cost: 250,
  // Toward zero spread, never past it. `resolveShipStats` clamps, but authoring a
  // value that would need the clamp is an authoring error and CI rejects it.
  modifiers: [{ stat: "spread", op: "mul", value: 0.4 }],
};

export const UPGRADES: UpgradeCatalog = {
  [REINFORCED_HULL.id]: REINFORCED_HULL,
  [RAPID_COILS.id]: RAPID_COILS,
  [HEAVY_SLUGS.id]: HEAVY_SLUGS,
  [THRUSTER_TRIM.id]: THRUSTER_TRIM,
  [BEAM_FOCUS.id]: BEAM_FOCUS,
};
