// Player settings, and where they live between runs.
//
// Replaces `difficultyStore.ts`, which held one string. Deliberately still NOT the
// meta-save: M3's save is a versioned document with a migration chain describing what
// a player has EARNED, and a corrupt one must never cost them their control setup. Two
// documents, two lifetimes.
//
// ── Difficulty and sensitivity are not the same kind of setting ───────────────
//
// They sit in one document because they persist the same way, and nowhere else. A
// DIFFICULTY change rewrites the content a run is built from, so it can only take
// effect by starting a new run — which is why both pickers confirm before switching.
// A SENSITIVITY change is a `ui/` number that decides how a thumb's travel maps to an
// axis; the simulation never hears about it, so it applies mid-flight with nothing to
// rebuild and nothing to lose.
//
// That difference is the whole reason settings did not need a pause. The first plan
// coupled them — settings reachable mid-run, therefore pause first, therefore blocked
// on a pause concept that belongs with M5's netcode. Putting them on the title and
// game-over screens instead, where difficulty already lives, gets the useful half now
// and leaves pause to be designed when multiplayer forces the question.

import {
  DEFAULT_DIFFICULTY,
  DIFFICULTIES,
  difficultyById,
  type DifficultyDef,
} from "@content/difficulty/index.js";

const KEY = "sw.settings";

/** Bumped when a stored document can no longer be read as-is. */
const VERSION = 1;

/**
 * Multipliers on how far a thumb has to travel for a full axis.
 *
 * 1 is the tuned default. HIGHER is more sensitive — less travel for the same
 * deflection — because that is the direction a player expects a "sensitivity" control
 * to move. The stick radii divide by it; see `ui/touch.ts`.
 */
export interface StickSensitivity {
  readonly aim: number;
  readonly slide: number;
}

export const DEFAULT_SENSITIVITY: StickSensitivity = { aim: 1, slide: 1 };

/** The range a slider offers. Half as sensitive through twice as sensitive. */
export const SENSITIVITY_MIN = 0.5;
export const SENSITIVITY_MAX = 2;
export const SENSITIVITY_STEP = 0.1;

export interface Settings {
  readonly difficulty: DifficultyDef;
  readonly sensitivity: StickSensitivity;
}

export const DEFAULT_SETTINGS: Settings = {
  difficulty: DEFAULT_DIFFICULTY,
  sensitivity: DEFAULT_SENSITIVITY,
};

const clampSensitivity = (value: unknown): number => {
  const n = typeof value === "number" ? value : Number.NaN;
  if (!Number.isFinite(n)) return 1;
  return Math.min(SENSITIVITY_MAX, Math.max(SENSITIVITY_MIN, n));
};

/**
 * Reads stored settings. Any failure falls back rather than throwing.
 *
 * Every field is validated on the way in, not merely parsed: this is the one input the
 * game takes from something a user can edit by hand, and a sensitivity of 0 would make
 * the stick radius infinite — a control that silently does nothing, which is far harder
 * to diagnose than a boot failure.
 */
export function loadSettings(search = window.location.search): Settings {
  let stored: Partial<{ version: number; difficulty: string; aim: number; slide: number }> = {};
  try {
    const raw = window.localStorage.getItem(KEY);
    if (raw) {
      const parsed: unknown = JSON.parse(raw);
      if (parsed && typeof parsed === "object") stored = parsed as typeof stored;
    }
  } catch {
    // Private browsing, storage disabled, or a document from a future version that
    // this build cannot read. Not worth a broken boot.
  }
  // A document from a version this build does not know is ignored wholesale rather
  // than field-by-field. There is only one version so far, so this is the shape of the
  // decision rather than a migration.
  if (stored.version !== undefined && stored.version !== VERSION) stored = {};

  return {
    difficulty: difficultyFrom(search, stored.difficulty),
    sensitivity: {
      aim: clampSensitivity(stored.aim),
      slide: clampSensitivity(stored.slide),
    },
  };
}

/** URL, then what was last chosen, then the default. */
function difficultyFrom(search: string, stored: string | undefined): DifficultyDef {
  const requested = new URLSearchParams(search).get("difficulty");
  if (requested) {
    // Accepts the bare name as well as the full id, so `?difficulty=easy` works —
    // nobody is going to type `?difficulty=difficulty.easy`. An unrecognised value
    // falls through to the stored choice rather than silently meaning NORMAL.
    const name = requested.toLowerCase();
    const id = name.startsWith("difficulty.") ? name : `difficulty.${name}`;
    const found = DIFFICULTIES[id];
    if (found) return found;
  }
  return stored ? difficultyById(stored) : DEFAULT_DIFFICULTY;
}

export function saveSettings(settings: Settings): void {
  try {
    window.localStorage.setItem(
      KEY,
      JSON.stringify({
        version: VERSION,
        difficulty: settings.difficulty.id,
        aim: settings.sensitivity.aim,
        slide: settings.sensitivity.slide,
      }),
    );
  } catch {
    // Nothing to do and nothing worth telling the player — the run still works, the
    // choice just will not outlive the tab.
  }
}
