// Waypoint stops — the rail parks and the party must clear a condition to advance.
//
// Runs BEFORE the flight system, and that order is deliberate. Flight advances the
// rail; if the stop were evaluated afterwards the party would already have sailed
// past the waypoint by up to one tick's travel before being pulled back, which reads
// as a jolt at every stop. Deciding first lets the arrival tick clamp cleanly onto
// the waypoint instead.
//
// Everything here is counted in TICKS. A stop authored as "one second" is 60 ticks,
// not 1000 milliseconds measured against a wall clock — which is what lets the spec
// assert "still held after 59, released on the 60th" exactly, where the old
// browser-driven smoke had to poll with slack.

import { secondsToTicks } from "@core/loop.js";
import { Vec3, tv3 } from "@core/math/index.js";
import { ROCK_SMALL } from "@content/hazards/index.js";
import { FWD_CONE, OMNI_CONE } from "@content/tuning/flight.js";
import type { MutableRailFrame } from "../rail.js";
import type { StopMode, StopSpec } from "../stops.js";
import type { SimWorld } from "../world.js";

/** Scatter radius for a stop's burst of targets. */
const BURST_MIN_DIST = 8;
const BURST_MAX_DIST = 20;

/**
 * Fraction of the aim cone the burst is scattered into.
 *
 * Not the full cone: a target sitting exactly on the aim limit needs the stick pinned
 * to reach and reads as unfair even when it is technically possible. Inside three
 * quarters of it, every target is comfortably shootable.
 */
const BURST_CONE_FRACTION = 0.75;

const TAU = Math.PI * 2;

/**
 * Half-angle of the cone a stop's burst is scattered into — the SAME cone the stop's
 * mode gives the player to aim within.
 *
 * Tying the two together is the fix for a hard softlock. The burst used to scatter on a
 * full unit sphere regardless of mode, so at a `forward` stop (`FWD_CONE` = 0.28 rad)
 * only about 2% of the sphere's solid angle was reachable — a 5-target burst expected
 * roughly 0.1 aimable targets. A destroy-N stop with no timeout then parks the party at
 * that waypoint FOREVER: ambient spawning pauses while held, nothing culls while the
 * rail is not advancing, and the only targets that count are ones the aim cone cannot
 * reach. Measured on `SHAKEDOWN`, the destroy-two stop at railS 326 was unpassable
 * under every input tried, including sweeping the stick through its full range for
 * twenty seconds.
 *
 * With `OMNI_CONE` (π) the cap below is the whole sphere, so an omni stop scatters
 * exactly as it always did.
 */
const burstCone = (mode: StopMode): number => (mode === "forward" ? FWD_CONE : OMNI_CONE);
/**
 * A stop's targets are the TERMINAL rock, deliberately.
 *
 * A destroy-2 stop should mean two shots, not "two kills, but breaking the first one
 * spawns three more things cluttering the arena". Splitting is a reward for shooting
 * the field; a gated objective wants a countable target. When stops gain their own
 * authored target def, this becomes the default rather than the rule.
 */
const BURST_DEF = ROCK_SMALL;

const scratch = new Vec3();
const burstFrame: MutableRailFrame = {
  position: new Vec3(),
  tangent: new Vec3(),
  normal: new Vec3(),
  binormal: new Vec3(),
};

export function stopSystem(world: SimWorld): void {
  const rail = world.rail;
  if (!rail) return;
  const course = rail.courses[world.courseId];
  if (!course) return;

  // ── Already parked: tick the hold and test its release condition ────────────
  if (world.stop.active) {
    world.stop.elapsedTicks++;
    const spec = currentStopSpec(world);
    if (!isSatisfied(world, spec)) return;

    // Fired on CLEARING, not on arrival: a stop the party reached but did not satisfy
    // has not been earned, and a downstream fork that opened just for showing up would
    // make the whole trigger mechanism decorative.
    if (spec?.firesTrigger) world.fireTrigger(spec.firesTrigger);

    const waypoint = world.stop.waypoint;
    if (!world.clearedStops.includes(waypoint)) {
      world.clearedStops.push(waypoint);
      world.clearedStops.sort((a, b) => a - b);
    }
    world.stop.active = false;
    world.stop.waypoint = -1;
    world.railHolding = false;
    world.forcedAimMode = null;
    world.events.push({ type: "stopEnded", waypoint, tick: world.tick });
    return;
  }

  // ── Not parked: would this tick's travel carry us onto a stop waypoint? ──────
  const reach = world.railS + world.railSpeed * world.dt;
  for (let index = 0; index < course.waypointCount; index++) {
    const distance = course.distanceAtWaypoint(index);
    if (distance <= world.railS || distance > reach) continue;

    const spec = course.waypointAt(index).stop;
    if (!spec || world.clearedStops.includes(index)) continue;

    beginStop(world, index, distance, spec);
    return;
  }
}

function currentStopSpec(world: SimWorld): StopSpec | undefined {
  const course = world.rail?.courses[world.courseId];
  return course?.waypointAt(world.stop.waypoint).stop;
}

function isSatisfied(world: SimWorld, spec: StopSpec | undefined): boolean {
  // A stop whose spec has vanished (a course switch mid-hold) must not strand the
  // party forever — release rather than deadlock.
  if (!spec) return true;

  switch (spec.advance.type) {
    case "time":
      return world.stop.elapsedTicks >= secondsToTicks(spec.advance.seconds, world.hz);
    case "destroyed":
      // Measured against the baseline captured on arrival, so kills made on the
      // approach do not carry the party straight through the next stop.
      return world.hazardsDestroyed - world.stop.killBaseline >= spec.advance.count;
    case "damage":
      return world.stop.damaged;
  }
}

function beginStop(world: SimWorld, index: number, distance: number, spec: StopSpec): void {
  world.railS = distance;
  world.railHolding = true;
  world.forcedAimMode = spec.mode;

  world.stop.active = true;
  world.stop.waypoint = index;
  world.stop.elapsedTicks = 0;
  world.stop.killBaseline = world.hazardsDestroyed;
  world.stop.damaged = false;

  spawnBurst(world, distance, spec.burst ?? 0, spec.mode);

  world.events.push({ type: "stopBegan", waypoint: index, mode: spec.mode, tick: world.tick });
}

/**
 * Scatters `count` targets around the stop, so a destroy-N stop has something to
 * shoot — inside the cone the stop's own mode lets the player aim within.
 *
 * Four RNG draws per hazard, always, exactly as before: two for the direction, one for
 * the distance, one for the variant. The draw count is the contract, not which values
 * the two direction draws feed — a variable count would shift every later random
 * decision in the run.
 *
 * The direction is sampled uniformly on a spherical CAP around the rail tangent rather
 * than on the whole sphere. `cosTheta` is drawn uniformly on `[cos(halfAngle), 1]`,
 * which is what makes it area-uniform on the cap rather than bunched at the axis (the
 * same r² reasoning that the ambient spawner's radius needed). At `halfAngle` = π the
 * range is `[-1, 1]` and this IS a uniform sphere, so omni stops are unchanged in
 * distribution.
 */
function spawnBurst(world: SimWorld, distance: number, count: number, mode: StopMode): void {
  if (count <= 0) return;
  const course = world.rail!.courses[world.courseId]!;
  course.sample(distance, scratch);
  // The frame gives an orthonormal basis to build the cone in: the tangent points down
  // the rail, which is what "forward" means to the player at a stop.
  course.frameAt(distance, burstFrame);

  const cosLimit = Math.cos(burstCone(mode) * BURST_CONE_FRACTION);

  for (let i = 0; i < count; i++) {
    const cosTheta = cosLimit + world.rng.float() * (1 - cosLimit); // 1 draw
    const phi = world.rng.float() * TAU; // 1 draw
    const spread = world.rng.range(BURST_MIN_DIST, BURST_MAX_DIST); // 1 draw
    const variant = world.rng.int(0, BURST_DEF.variants); // 1 draw

    const sinTheta = Math.sqrt(Math.max(0, 1 - cosTheta * cosTheta));
    const direction = tv3()
      .copy(burstFrame.tangent)
      .multiplyScalar(cosTheta)
      .addScaledVector(burstFrame.normal, sinTheta * Math.cos(phi))
      .addScaledVector(burstFrame.binormal, sinTheta * Math.sin(phi));

    world.spawnHazard(BURST_DEF, tv3().copy(scratch).addScaledVector(direction, spread), variant);
  }
}
