// Scalar helpers shared by the simulation and the renderer.
//
// A note on determinism that applies to this whole `math` directory: JS engines are
// NOT required to produce bit-identical results for `Math.sin`, `cos`, `acos`, or
// `exp`. That means replays are reproducible on the SAME engine (which is what the
// golden-replay tests need) but are not guaranteed bit-identical across a Chrome
// host and a Firefox client. That is fine and deliberate — the multiplayer design is
// host-authoritative, so the host's result is definitionally correct and clients
// reconcile to it. If we ever wanted lockstep, this is the file that would have to
// grow fixed-point or polynomial approximations.

export const EPSILON = 1e-6;
export const TAU = Math.PI * 2;
export const DEG = Math.PI / 180;

export const clamp = (v: number, lo: number, hi: number): number =>
  v < lo ? lo : v > hi ? hi : v;

export const clamp01 = (v: number): number => clamp(v, 0, 1);

export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

/** Inverse of `lerp`: where does `v` sit between `a` and `b`? */
export const inverseLerp = (a: number, b: number, v: number): number =>
  a === b ? 0 : (v - a) / (b - a);

/**
 * Frame-rate-independent exponential smoothing factor.
 *
 * The old codebase spelled this inline as `1 - Math.exp(-k * dt)` in half a dozen
 * places. With a fixed timestep `dt` is constant, so every call site should hoist
 * this to a module constant — see `sim/flight` for the pattern. Kept as a function
 * because the view layer smooths at a variable frame delta.
 */
export const expEase = (k: number, dt: number): number => 1 - Math.exp(-k * dt);

/** Shortest signed angular difference, wrapped into (-PI, PI]. */
export const angleDelta = (from: number, to: number): number => {
  let d = (to - from) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d <= -Math.PI) d += TAU;
  return d;
};

/** Move `current` toward `target` by at most `maxDelta`. */
export const moveToward = (current: number, target: number, maxDelta: number): number => {
  const d = target - current;
  return Math.abs(d) <= maxDelta ? target : current + Math.sign(d) * maxDelta;
};

export const nearlyEqual = (a: number, b: number, eps = EPSILON): boolean =>
  Math.abs(a - b) <= eps;
