// The Narrows — the second level, and the reason there is a catalog.
//
// Shakedown was the only level for three milestones, which meant the level FORMAT was
// never exercised by anything but the one document that defined it. This one is chosen
// to fly the parts of it that nothing shipped had ever used:
//
// - **A trigger fork.** `BranchSelector`'s `trigger` variant, `WaveSpec.firesTrigger`,
//   and `world.fireTrigger()` have existed since M1a/M2 and are authored by NOTHING —
//   every shipped fork resolves on `partyLateral`. Here, clearing the gate wave opens
//   the low route; fly past it and the rail carries you over the top instead. That is
//   combat deciding the rail, which is the whole reason the trigger seam exists.
// - **`selectors`.** Same story: the field is read by `buildRailNetwork` and written by
//   no level. A typo in its key used to fall back to `partyLateral` in silence; the
//   validator now rejects a key that does not name a real fork.
//
// It is deliberately SHORTER and TIGHTER than Shakedown — a narrower box, a denser
// field, less room to slide — so the two read as different places rather than as one
// level with the waypoints moved.
//
// The density was measured rather than guessed, because "unflyable" is a real state this
// game has shipped: correcting the ambient spawner's radius distribution once took the
// demo level from a hands-off death in 1.7-6.3 seconds to 5-11. Across eight seeds with
// no input at all, Shakedown survives 8.2-17.2 s and The Narrows 6.6-12.4 s — harder,
// and nowhere near the regime where the field is a wall. What that does NOT measure is
// whether the gate wave can be cleared in the rail before the commit point, which is a
// question about aim and pacing that only a flight answers.
//
// What is NOT here, and why: a `damage` stop. It is the third unauthored corner of the
// format and it cannot be shipped safely yet — see the note at the bottom of this file.

import type { LevelSpec } from "../schemas/level.js";

/**
 * Fired by clearing the gate wave, and read by the fork's selector.
 *
 * Named once and referenced twice — by the wave that fires it and the selector that
 * waits on it. The validator rejects a selector whose trigger nothing in the level
 * fires, and a shared constant is what makes that mistake unauthorable here rather than
 * merely caught. It stays JSON-shaped because it folds to a plain string at author
 * time, which is exactly what a serializer wants; nothing survives into the document
 * but the two identical strings.
 */
const GATE_OPEN = "narrows.gate-open";

export const NARROWS: LevelSpec = {
  schemaVersion: 1,
  id: "level.narrows",
  name: "The Narrows",

  // Faster than Shakedown's 17 and it is the only knob turned up: a tighter box at the
  // same speed is just a smaller target, where a tighter box arriving sooner is the
  // level being harder in the way a rail shooter is supposed to be — what is in front
  // of you, met with less room to answer it.
  speed: 20,

  // Denser than Shakedown (3.5 / 16 / 60) and drawn from a smaller ball, which is what
  // makes it read as a canyon rather than as open space. `spread` is the number to be
  // careful with: placement is `spread * cbrt(u)`, so the fraction of spawns landing
  // inside the ship's collision reach goes as (reach/spread)³ — at reach 3.6 that is
  // 1.1% on Shakedown's 16 and 2.4% here. Below about 12 it stops being a field and
  // starts being a wall.
  ambient: { ratePerSecond: 4.2, spread: 13, maxAlive: 60 },

  waves: [
    // ── Before the fork ───────────────────────────────────────────────────────
    { id: "narrows.picket", enemy: "enemy.drone", count: 4, pattern: { kind: "line", spacing: 4 }, triggerS: 55, lead: 50 },
    { id: "narrows.runner", enemy: "enemy.interceptor", count: 2, pattern: { kind: "column", spacing: 25 }, triggerS: 108, lead: 45 },
    // THE GATE. Clearing it fires the trigger the fork below reads — so this is the
    // one wave in the game whose outcome changes where the rail goes. It is stationed
    // well clear of the commit point on purpose: the party has to finish it with rail
    // to spare, and flying past it is a decision rather than an accident.
    {
      id: "narrows.gate",
      enemy: "enemy.drone",
      count: 4,
      pattern: { kind: "ring", radius: 6 },
      triggerS: 130,
      lead: 50,
      firesTrigger: GATE_OPEN,
    },
    { id: "narrows.lance", enemy: "enemy.lancer", count: 2, pattern: { kind: "column", spacing: 28 }, triggerS: 215, lead: 60 },

    // ── Past the fork ─────────────────────────────────────────────────────────
    // Both routes get an encounter, and each names its course — the same rail distance
    // is a different world point on each, so an unqualified wave here would spawn on
    // whichever side the party took, at a station that means something else there.
    { id: "narrows.ridge", enemy: "enemy.interceptor", count: 3, pattern: { kind: "vee", spacing: 6 }, triggerS: 380, lead: 55, course: "trunk" },
    { id: "narrows.ridge-lance", enemy: "enemy.lancer", count: 2, pattern: { kind: "column", spacing: 26 }, triggerS: 470, lead: 60, course: "trunk" },
    // The low route is the EARNED one — it is opened by clearing the gate — so it pays
    // better, in the same way Shakedown's port branch does. Four drones against the
    // ridge's none is the whole difference, and `economy.spec` names it so nobody
    // levels the two by accident.
    { id: "narrows.deep", enemy: "enemy.drone", count: 4, pattern: { kind: "ring", radius: 7 }, triggerS: 380, lead: 55, course: "under" },
    { id: "narrows.deep-lance", enemy: "enemy.lancer", count: 2, pattern: { kind: "column", spacing: 26 }, triggerS: 460, lead: 60, course: "under" },
  ],

  rail: {
    // Shakedown's box is 8 × 5. Two units narrower and one shorter is enough to feel:
    // `BOX_MOVE` is 7 units/second, so crossing this one takes about six tenths of a
    // second against Shakedown's eight — the slide is still the defensive move, with
    // less of it to make.
    box: { width: 6, height: 4 },
    waypoints: [
      { position: [0, 0, 0] },
      { position: [70, -4, 10] },
      // Dropping and turning at once, so the frame is nowhere near world-up by the
      // time the first stop arrives.
      { position: [140, -10, -10] },
      // A forward stop, tight cone, with its own targets. Timed rather than
      // destroy-N: this level's gate is a WAVE, and two gated objectives before one
      // fork would make the route feel administered rather than flown.
      {
        position: [205, -6, -46],
        stop: { mode: "forward", advance: { type: "time", seconds: 5 }, burst: 4 },
      },
      { position: [268, 4, -78] },
      // ── The fork, waypoint 5 ──────────────────────────────────────────────
      // The choice commits one segment earlier, at waypoint 4's arc length, where
      // every course still has identical geometry. See ROADMAP Addendum 3.
      { position: [330, 14, -96] },
      // Trunk: over the ridge, climbing and swinging back out. The route you get by
      // default — longer, and it pays less.
      { position: [400, 30, -84] },
      { position: [470, 44, -40] },
      { position: [534, 52, 14] },
    ],

    branches: [
      {
        id: "under",
        atWaypoint: 5,
        // Under: dives away below the ridge. Opened by clearing the gate.
        waypoints: [
          { position: [378, -6, -152] },
          { position: [430, -28, -212] },
          { position: [492, -36, -268] },
        ],
      },
    ],

    // The first authored selector in the game. Option 0 is the trunk carrying on over
    // the ridge and option 1 is the `under` branch — options are ordered by course id,
    // and course 0 is always the trunk. So: clear the gate, take the low road.
    selectors: {
      "trunk:5": { kind: "trigger", triggerId: GATE_OPEN, option: 1, defaultOption: 0 },
    },
  },
};

// ── Why there is no `damage` stop here ──────────────────────────────────────────
//
// `StopAdvance` has three variants and this level was meant to author the third. It
// does not, and the reason is the same failure the destroy-N burst cone had: **nothing
// supplies damage while the rail is held.** Ambient spawning pauses on `railHolding`,
// no new wave triggers because `railS` is frozen, and a stop's own burst is scattered
// 8-20 units down the aim cone — further than the ship can reach by sliding inside its
// box. A `damage` stop has no timeout, so a party that clears whatever was already in
// the world without being hit parks there permanently.
//
// It is therefore a softlock waiting for an author, not a feature waiting for a level,
// and it belongs with the stop system rather than here. The fix is a design decision
// somebody has to make — a timeout fallback, or letting waves and ambient keep arriving
// while a damage stop holds — and `docs/ROADMAP.md` Addendum 23 records it as owed work
// rather than leaving the next person to rediscover it by shipping one.
