// Where the debug overrides live between runs.
//
// A third stored document alongside `sw.settings` and (from M3) the meta-save, and
// deliberately not folded into either. Settings are what a player chose about their
// controls; this is a tester's scratch pad that regularly holds numbers no real run
// should ever use. Mixing them would mean a corrupt debug value could cost someone
// their difficulty and stick sensitivity, and it would mean "clear the cheats" had to
// know which half to keep.
//
// The whole document — the unlock and every knob — persists, so a phone tester who
// entered the code once does not have to enter it again after every reload. That is
// the "persists through the session" requirement read the honest way: a session on a
// phone is a sequence of reloads.
//
// ⚠️ Nothing here trusts what it reads. The stored JSON is user-editable by
// construction (that is the point of the export button), so every value goes through
// `clampOverrides` on the way in, and a document from a version this build does not
// know is dropped wholesale rather than merged field by field.

import {
  DEBUG_FIELDS,
  DEFAULT_DEBUG,
  type DebugOverrides,
} from "@sim/debug.js";

const KEY = "sw.debug";

/** Bumped when a stored document can no longer be read as-is. */
const VERSION = 1;

export interface DebugDocument {
  /** Whether the debug button has been revealed. Set by the Konami code or `?debug=1`. */
  readonly unlocked: boolean;
  readonly overrides: DebugOverrides;
}

export const DEFAULT_DEBUG_DOCUMENT: DebugDocument = {
  unlocked: false,
  overrides: DEFAULT_DEBUG,
};

/**
 * Coerces anything at all into a valid override document.
 *
 * Pure, and the only way a value reaches the fold. Three failure modes it has to
 * absorb, in rising order of likelihood: a stored document written by an older build
 * that lacked a knob (missing key → that knob's default), a hand-edited file with a
 * value out of range (clamped to the slider's own bounds, so the menu can always
 * represent what is stored), and a value that is not a number at all — including the
 * `NaN` that `JSON.parse` happily produces from `null` under `Number()`.
 *
 * Unknown keys are dropped rather than carried, which is what stops an exported file
 * from an experimental branch quietly reintroducing a knob this build removed.
 */
export function clampOverrides(raw: unknown): DebugOverrides {
  const source = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
  const out: Record<string, number> = {};
  for (const field of DEBUG_FIELDS) {
    const value = source[field.key];
    const n = typeof value === "number" ? value : Number.NaN;
    out[field.key] = Number.isFinite(n)
      ? Math.min(field.max, Math.max(field.min, n))
      : field.default;
  }
  return out as unknown as DebugOverrides;
}

/** The document a tester exports, as pretty JSON. Also what the import path accepts. */
export const debugJson = (overrides: DebugOverrides): string =>
  JSON.stringify({ version: VERSION, overrides }, null, 2);

/**
 * Reads an exported file back.
 *
 * Accepts both the exported shape (`{version, overrides}`) and a bare map of knobs,
 * because the second is what someone typing a file by hand or pasting a fragment from
 * a bug report will produce, and refusing it would serve nothing. Every value is
 * clamped either way. Returns null only when the text is not JSON at all.
 */
export function parseDebugJson(text: string): DebugOverrides | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== "object") return null;
  const record = parsed as Record<string, unknown>;
  const body = record.overrides && typeof record.overrides === "object" ? record.overrides : record;
  return clampOverrides(body);
}

/** Reads the stored document. Any failure falls back rather than throwing. */
export function loadDebug(search = window.location.search): DebugDocument {
  let stored: Record<string, unknown> = {};
  try {
    const raw = window.localStorage.getItem(KEY);
    if (raw) {
      const parsed: unknown = JSON.parse(raw);
      if (parsed && typeof parsed === "object") stored = parsed as Record<string, unknown>;
    }
  } catch {
    // Private browsing, storage disabled, or a document this build cannot read. A
    // debug menu is the last thing that should be able to stop the game booting.
  }
  if (stored.version !== undefined && stored.version !== VERSION) stored = {};

  return {
    // `?debug=1` is the way in on a device where the Konami code cannot be typed —
    // which is every phone, and phones are where this gets flown.
    unlocked: stored.unlocked === true || new URLSearchParams(search).get("debug") === "1",
    overrides: clampOverrides(stored.overrides),
  };
}

export function saveDebug(document: DebugDocument): void {
  try {
    window.localStorage.setItem(
      KEY,
      JSON.stringify({
        version: VERSION,
        unlocked: document.unlocked,
        overrides: document.overrides,
      }),
    );
  } catch {
    // Nothing worth telling anyone: the values still apply to this run, they just will
    // not outlive the tab.
  }
}
