// Waves — authored groups of enemies, and the formations they arrive in.
//
// Replaces the flat per-enemy placement list from M2 step 2. A wave of one IS a
// placement, so nothing is lost by the swap; two things are gained:
//
//   * A formation is one authored entry rather than N hand-computed offsets, and the
//     arrangement is named (`line`, `vee`) rather than implied by coordinates.
//   * A wave can be OWNED BY A COURSE. That is the gap left open when forks were
//     wired: `triggerS` alone is ambiguous past a split, because the same rail
//     distance is a different world point on each course. The demo level dodged it by
//     keeping every enemy short of the fork, enforced by a test; this closes it
//     properly and that test is gone.
//
// ── Patterns are geometry, not randomness ────────────────────────────────────────
//
// Every slot is a pure function of `(index, count)`. That is not a concession to the
// determinism rules — it is the whole point. A scattered wave is indistinguishable
// from the ambient hazard spawner, and the ambient spawner already exists for scatter.
// A formation reads as a formation because it is regular.
//
// The convenient consequence is that a wave costs zero RNG draws, so it cannot perturb
// any other system's stream — which matters, because a wave spawns as a result of where
// the player flew. Same argument as `sim/split.ts` and `sim/enemy.ts`; here it is free.

import type { EnemyDef } from "@content/schemas/enemy.js";
import type { WavePattern, WaveSpec } from "@content/schemas/level.js";
import type { RailNetwork } from "./rail.js";

/** One member's station offsets, relative to the formation's centre. */
export interface WaveSlot {
  /** Along the rail frame's binormal. */
  readonly ox: number;
  /** Along its normal. */
  readonly oy: number;
  /** Along the rail, added to the wave's lead. Negative is behind the centre. */
  readonly along: number;
}

/** An authored wave with its def resolved and its courses worked out. */
export interface Wave {
  readonly id: string;
  readonly def: EnemyDef;
  readonly count: number;
  readonly pattern: WavePattern;
  readonly triggerS: number;
  readonly lead: number;
  readonly ox: number;
  readonly oy: number;
  /** Course ids this wave may spawn on. */
  readonly courses: readonly number[];
  readonly firesTrigger: string | undefined;
}

/**
 * Where member `index` of `count` sits, relative to the formation's centre.
 *
 * Centred rather than left-anchored throughout: a line of four should straddle the
 * rail, not sit to one side of it. `(index - (count - 1) / 2)` is the centring term
 * and it handles odd and even counts alike, which is why there is no special case for
 * either — and no division by `count`, so a wave of one is not a special case either.
 */
export function patternSlot(pattern: WavePattern, index: number, count: number): WaveSlot {
  const centred = index - (count - 1) / 2;

  switch (pattern.kind) {
    case "line":
      return { ox: centred * pattern.spacing, oy: 0, along: 0 };

    case "column":
      // Descending, so index 0 is the member furthest down the rail — the one the
      // party meets first. Authoring order then matches arrival order, which is what
      // an author means by "first".
      return { ox: 0, oy: 0, along: -centred * pattern.spacing };

    case "vee": {
      // Point first, wings trailing and alternating sides. Index 0 is the point;
      // 1 and 2 are the first pair, 3 and 4 the next, and so on.
      const rank = Math.ceil(index / 2);
      const side = index === 0 ? 0 : index % 2 === 1 ? -1 : 1;
      return {
        ox: side * rank * pattern.spacing,
        oy: 0,
        // Behind the point by the same rank, so the V has roughly equal arms.
        along: -rank * pattern.spacing,
      };
    }

    case "ring": {
      // Evenly around the circle. `count` in the denominator rather than `count - 1`
      // so the last member does not land on top of the first.
      const angle = (index / Math.max(1, count)) * Math.PI * 2;
      return {
        ox: Math.cos(angle) * pattern.radius,
        oy: Math.sin(angle) * pattern.radius,
        along: 0,
      };
    }
  }
}

/**
 * Resolves authored waves against the enemy catalog and the rail, sorted by trigger.
 *
 * Sorting here rather than trusting the author is what lets the runtime walk them with
 * a cursor instead of scanning the level every tick. A wave naming an unknown enemy or
 * an unknown branch is dropped rather than thrown on: validated content cannot produce
 * one, and unvalidated content should not take a run down.
 */
export function buildWaves(
  specs: readonly WaveSpec[],
  catalog: readonly EnemyDef[],
  network: RailNetwork,
): Wave[] {
  const waves: Wave[] = [];

  for (const spec of specs) {
    const def = catalog.find((candidate) => candidate.id === spec.enemy);
    if (!def) continue;

    // `null` means "wherever the party goes" — every course. A named branch resolves
    // to itself plus everything downstream of it.
    const courses = network.coursesThrough(spec.course ?? null);
    if (courses.length === 0) continue; // names a branch this rail does not have

    waves.push({
      id: spec.id,
      def,
      count: spec.count,
      pattern: spec.pattern,
      triggerS: spec.triggerS,
      lead: spec.lead,
      ox: spec.ox ?? 0,
      oy: spec.oy ?? 0,
      courses,
      firesTrigger: spec.firesTrigger,
    });
  }

  // Stable within equal triggers, so two waves authored at the same distance keep
  // their authored order — which is what makes their entity handles, and therefore
  // their weave phases and variants, reproducible.
  return waves.sort((a, b) => a.triggerS - b.triggerS);
}
