// Enemy movement, aim, and fire.
//
// Three things happen per enemy per tick, in this order, and the order matters:
//
//   1. STATION. Where it wants to be, expressed in rail space and resolved to a world
//      point through the rail frame. Velocity is set toward it and `motionSystem`
//      integrates, so enemies travel through the same pipeline everything else does —
//      which is what makes the view's interpolation work on them for free.
//   2. FACING. Eased toward the nearest ship at the def's turn rate. Facing is stored
//      state, not derived from velocity: an enemy holding station has no velocity to
//      derive from, and the firing cone is measured against it.
//   3. FIRE. Only if the cooldown is spent, the target is inside the fire range, and
//      the target is inside the cone AROUND THE CURRENT FACING. That last clause is
//      the whole reason facing exists — measuring the cone against the direction to
//      the target instead would make it always true, and a turret the party had just
//      flown past could shoot backwards on the same tick.
//
// Nothing here touches `world.rng`. Every random value comes from `enemyRngFor`, which
// derives a stream from the enemy's own handle. See the header of `sim/enemy.ts`.

import { clamp, Quat, Vec3 } from "@core/math/index.js";
import type { Entity } from "@core/ecs.js";
import { Faction } from "../faction.js";
import { enemyRngFor, stationRailS, turnToward, weaveOffset, weavePhaseFor } from "../enemy.js";
import { coneFor, createFlightState, readFlight } from "../flight.js";
import type { MutableRailFrame } from "../rail.js";
import type { SimWorld } from "../world.js";

const WORLD_UP = new Vec3(0, 1, 0);

// Scratch. Allocation-free: this runs for every enemy, every tick.
const frame: MutableRailFrame = {
  position: new Vec3(),
  tangent: new Vec3(),
  normal: new Vec3(),
  binormal: new Vec3(),
};
const station = new Vec3();
const position = new Vec3();
const toStation = new Vec3();
const velocity = new Vec3();
const facing = new Vec3();
const desired = new Vec3();
const toTarget = new Vec3();
const targetPosition = new Vec3();
const shipPosition = new Vec3();
/** Rail forward at the PARTY's position — the axis every aim cone is measured from. */
const partyForward = new Vec3();
const targetFlight = createFlightState();
const shotDirection = new Vec3();
const shotVelocity = new Vec3();
const muzzle = new Vec3();
const up = new Vec3();
const right = new Vec3();
const orientation = new Quat();

/**
 * Nearest living ship to `from`, written into `targetPosition`. Returns its slot, or
 * -1 if the party is all down.
 *
 * By SLOT rather than dense row, like every other party loop: both are deterministic,
 * but slot order stays stable as players join and leave, and a tie between two ships
 * equidistant from a drone should not resolve differently because someone reconnected.
 */
function nearestShipTo(world: SimWorld, from: Vec3): number {
  const { ship, transform } = world.components;
  let bestSlot = -1;
  let bestDistanceSq = Infinity;

  for (let slot = 0; slot < world.shipBySlot.length; slot++) {
    const entity = world.shipBySlot[slot];
    if (entity === undefined || !world.ecs.isAlive(entity)) continue;

    const s = ship.row(entity);
    const t = transform.row(entity);
    if (s < 0 || t < 0 || ship.columns.health[s]! <= 0) continue;

    shipPosition.readFrom(transform.columns.pos, t * 3);
    const distanceSq = shipPosition.distanceToSq(from);
    if (distanceSq >= bestDistanceSq) continue;

    bestDistanceSq = distanceSq;
    bestSlot = slot;
    targetPosition.copy(shipPosition);
  }

  return bestSlot;
}

/**
 * Whether a ship could bring its guns to bear on something at this bearing.
 *
 * `cosFromForward` is the cosine of the angle between rail-forward and the direction
 * from the SHIP to the enemy — so 1 is dead ahead and -1 is directly astern.
 *
 * The rule this enforces: nothing fires on a ship that has no way to answer. A rail
 * shooter's reticle is confined to a cone around rail-forward, and outside a stop the
 * party cannot turn around, so an enemy the party has flown past could sit behind them
 * and shoot with total impunity. That is not difficulty, it is just damage, and it got
 * worse when the rail speed was halved — a trailing enemy stays inside its own fire
 * range for twice as long.
 *
 * Measured against the ship's CURRENT aim mode rather than a constant, which is what
 * makes an omni stop behave correctly for free: omni's cone is π, every bearing is
 * reachable, and being shot from behind while you can turn to face it is fair.
 */
function canReturnFire(world: SimWorld, slot: number, cosFromForward: number): boolean {
  const entity = world.shipBySlot[slot];
  if (entity === undefined) return false;
  // A ship with no flight state is not something this should silently protect.
  if (!readFlight(world, entity, targetFlight)) return true;

  const cone = coneFor(targetFlight.aimMode);
  if (cone >= Math.PI) return true;
  return Math.acos(clamp(cosFromForward, -1, 1)) <= cone;
}

export function enemyAiSystem(world: SimWorld): void {
  const rail = world.rail;
  if (!rail) return;
  const course = rail.courses[world.courseId];
  if (!course) return;

  const { enemy, transform, motion } = world.components;
  const dt = world.dt;

  // Once per tick, not per enemy: the aim cone is measured from rail-forward at the
  // PARTY's position, which is the same axis for every enemy in the world.
  course.tangentAt(world.railS, partyForward);

  for (let row = 0; row < enemy.count; row++) {
    const entity = enemy.dense[row]! as Entity;
    const def = world.enemyCatalog[enemy.columns.defId[row]!];
    if (!def) continue;

    const t = transform.row(entity);
    const m = motion.row(entity);
    if (t < 0 || m < 0) continue;

    // ── 1. Station ────────────────────────────────────────────────────────────
    // A charger's lead shrinks every tick and is allowed to go negative — it passes
    // the party rather than parking on top of them.
    if (def.behavior.kind === "charger") {
      enemy.columns.station[row] = enemy.columns.station[row]! - def.behavior.closeSpeed * dt;
    }

    const targetS = clamp(
      stationRailS(def.behavior, enemy.columns.station[row]!, world.railS),
      0,
      course.length,
    );
    course.frameAt(targetS, frame);

    const lateral =
      enemy.columns.ox[row]! + weaveOffset(def.weave, weavePhaseFor(entity), world.tick);
    station
      .copy(frame.position)
      .addScaledVector(frame.binormal, lateral)
      .addScaledVector(frame.normal, enemy.columns.oy[row]!);

    position.readFrom(transform.columns.pos, t * 3);
    toStation.copy(station).sub(position);
    const gap = toStation.length();
    if (gap > 1e-6) {
      // Never faster than the authored speed, and never overshooting when it is close:
      // `gap / dt` is the velocity that lands exactly on the station this tick.
      velocity.copy(toStation).multiplyScalar(Math.min(def.speed, gap / dt) / gap);
    } else {
      velocity.set(0, 0, 0);
    }
    velocity.writeTo(motion.columns.vel, m * 3);

    // ── 2. Facing ─────────────────────────────────────────────────────────────
    const targetSlot = nearestShipTo(world, position);
    if (targetSlot >= 0) {
      toTarget.copy(targetPosition).sub(position);
      const distance = toTarget.length();
      desired.copy(toTarget).multiplyScalar(distance > 1e-6 ? 1 / distance : 0);
      if (distance <= 1e-6) desired.copy(frame.tangent);
    } else {
      // Nobody to look at: face down-track, so a wiped party does not leave a field of
      // enemies staring at wherever they happened to die.
      desired.copy(frame.tangent);
    }

    facing.readFrom(enemy.columns.facing, row * 3);
    turnToward(facing, desired, def.turnRate * dt);
    facing.writeTo(enemy.columns.facing, row * 3);

    // Orientation is for the renderer only; nothing in the simulation reads it back.
    // Built from the facing plus world-up, falling back when the two are parallel.
    up.copy(WORLD_UP).orthogonalize(facing);
    if (up.lengthSq() < 1e-6) up.copy(frame.normal).orthogonalize(facing);
    if (up.lengthSq() < 1e-6) up.set(0, 0, 1).orthogonalize(facing);
    up.normalize();
    right.crossVectors(facing, up).normalize();
    orientation.setFromBasis(facing, up, right).writeTo(transform.columns.rot, t * 4);

    // ── 3. Fire ───────────────────────────────────────────────────────────────
    // The cooldown ticks down BEFORE the check, and the tick it reaches zero is a
    // firing tick — the same arithmetic `firingSystem` does for the player, so an
    // interval of N means a shot every N ticks for both. Decrementing after the check
    // would quietly make every enemy weapon one tick slower than it says it is.
    const cooling = enemy.columns.fireCooldown[row]!;
    if (cooling > 0) enemy.columns.fireCooldown[row] = cooling - 1;
    if (cooling > 1) continue;
    if (targetSlot < 0) continue;

    const distance = toTarget.length();
    if (distance > def.fireRange) continue;
    if (Math.acos(clamp(facing.dot(desired), -1, 1)) > def.aimCone) continue;
    // Nothing shoots a ship that cannot shoot back. `desired` is the unit vector from
    // this enemy TO the ship, so its negation is the bearing the ship would have to
    // turn onto to answer.
    if (!canReturnFire(world, targetSlot, -desired.dot(partyForward))) continue;

    const weapon = world.weaponCatalog[def.weapon];
    if (!weapon) continue; // validated content cannot hit this

    // The one random draw an enemy makes, and it comes from its OWN stream. Firing is
    // conditional on everything above, so drawing from `world.rng` here — including
    // via `rng.fork()`, which advances its parent — would make the ambient hazard
    // field depend on whether the player flew into range.
    const rng = enemyRngFor(entity, world.tick, world.seed);
    shotDirection.copy(facing);
    shotDirection.x += rng.range(-weapon.spread, weapon.spread);
    shotDirection.y += rng.range(-weapon.spread, weapon.spread);
    shotDirection.z += rng.range(-weapon.spread, weapon.spread);
    shotDirection.normalize();

    // Clear of its own hull, so a bolt does not spawn inside the enemy that fired it.
    muzzle.copy(position).addScaledVector(shotDirection, weapon.muzzleForward + def.radius);
    shotVelocity.copy(shotDirection).multiplyScalar(weapon.projectileSpeed);
    world.spawnProjectile(
      entity,
      -1,
      muzzle,
      shotVelocity,
      weapon.projectileLifetimeTicks,
      weapon.damage,
      Faction.Enemy,
    );
    enemy.columns.fireCooldown[row] = weapon.fireIntervalTicks;
  }
}
