// The pickup catalog.
//
// Two, deliberately. `repair` is the one the game needed — before it there was no way
// to recover hull, so a long level was decided by the first mistake — and `credits` is
// the hook M3's shop reads. A catalog of eight variations on "a bit more of something"
// would be content, and content is not what this step is for.

import type { PickupCatalog, PickupDef } from "../schemas/pickup.js";

/**
 * Restores a quarter of a base hull.
 *
 * 25 rather than a fraction: an upgraded ship should not heal proportionally faster,
 * or the hull upgrade would improve repair as well as capacity and be worth twice what
 * the shop says. `repair` caps at the resolved maximum, which is where the upgrade's
 * value shows up.
 */
export const REPAIR: PickupDef = {
  id: "pickup.repair",
  radius: 2.2,
  effect: { kind: "repair", amount: 25 },
  lifetimeTicks: 600, // ten seconds — long enough to turn back for, not forever
  scatterRadius: 1.8,
};

/**
 * 100 credits, raised from 50 once the shop existed to spend them at.
 *
 * The arithmetic, which `__tests__/economy.spec.test.ts` now pins: drones are the only
 * enemy that pays credits, and the demo level fields ten of them before the fork plus six
 * more on the port branch. At a 0.35 drop chance that is an expected 175 credits for a
 * PERFECT trunk run — every drone destroyed, every drop collected — against a cheapest
 * upgrade of 250. One and a half flawless runs before anything in the shop is reachable,
 * and a tester who flies three runs would never see it do anything.
 *
 * The DENOMINATION is the right lever rather than the drop CHANCE. How often a pickup
 * appears is a pacing decision that has already been flown — it sets how much is on
 * screen and how often the player is pulled off their line to collect something — and
 * the drone's own comment calls the rarity deliberate. How much each one is worth was
 * never anything but a round number.
 *
 * At 100 a perfect trunk run pays 350: the first upgrade inside one good run, the whole
 * catalog in about six. Both are fences rather than targets — the collection rate is the
 * factor no headless number can supply, and it only comes from flying it.
 */
export const CREDITS: PickupDef = {
  id: "pickup.credits",
  radius: 2.2,
  effect: { kind: "credits", amount: 100 },
  lifetimeTicks: 600,
  scatterRadius: 1.8,
};

export const PICKUPS: PickupCatalog = {
  [REPAIR.id]: REPAIR,
  [CREDITS.id]: CREDITS,
};

/**
 * The catalog as an ORDERED list — the `defId` every instance stores, so it is part of
 * the wire format and every replay fingerprint. Appending is safe; reordering is not.
 * Same contract as `HAZARD_ORDER` and `ENEMY_ORDER`.
 */
export const PICKUP_ORDER: readonly PickupDef[] = [REPAIR, CREDITS];
