// Turning uniforms into directions, once.
//
// Four places in `view` needed "a direction that does not bunch at the poles" — a
// rock's spin axis, a lobe's centre, a chip's velocity, a chip's spin axis — and each
// had written out the same three lines. `core/rng.ts` already has `onUnitSphere`, but
// it fills a `@core/math` `Vec3` from an `Rng`, and these callers have neither: two
// derive their uniforms from a HASH rather than a stream, and all four want a Three.js
// `Vector3` to put in an instance matrix.
//
// So this is the same construction against the other two types, in one place, rather
// than a fifth copy. The formula matters more than it looks — see below.

import type { Vector3 } from "three";

/**
 * A uniformly distributed direction, from two independent uniforms in `[0, 1)`.
 *
 * `z` uniform in [-1, 1] and the azimuth uniform is the standard construction and the
 * only one of the obvious two that is correct: sampling the two ANGLES uniformly
 * instead bunches directions at the poles, which puts a visible axis through anything
 * built from many of them — a field of rocks mostly spinning the same way, a burst that
 * throws most of its debris in two directions.
 *
 * `Math.max(0, …)` guards the square root against a `z` of exactly ±1, where floating
 * point can produce a very small negative and `Math.sqrt` returns NaN — one NaN in an
 * instance matrix and the object silently does not draw.
 */
export function directionFromUniforms(uz: number, uPhi: number, out: Vector3): Vector3 {
  const z = uz * 2 - 1;
  const phi = uPhi * Math.PI * 2;
  const ring = Math.sqrt(Math.max(0, 1 - z * z));
  return out.set(ring * Math.cos(phi), ring * Math.sin(phi), z);
}
