// The build tag in the bottom-right corner.
//
// Four hex digits of the commit the bundle was built from, and it exists for one
// concrete reason: this game is flown by testers on their own phones and the feedback
// that comes back is "the rail feels slower now". Without a visible build id there is
// no way to know whether they are flying the build you think they are — a deploy that
// silently no-ops, a Service Worker holding a stale bundle, and a real regression all
// produce the same sentence.
//
// The SHA is injected at BUILD time (`__BUILD_SHA__`, see `vite.config.ts`) rather than
// fetched at runtime. A runtime fetch would need a file the deploy also has to write,
// which is one more thing that can be stale — and staleness is the exact failure this
// is here to detect.
//
// Split model/view like `hud.ts` and `touch.ts`: `buildTag` is pure string handling
// with a spec, and the element below decides nothing.

import { CHIP_BLOCK_HEIGHT } from "./touch.js";

/** How many hex digits are shown. Four is enough to name a build and short enough to read. */
export const TAG_DIGITS = 4;

/** What is shown when there is no SHA — a dev server, or a build outside a git tree. */
export const NO_SHA_TAG = "#dev";

/**
 * The last four digits of a commit SHA, or `#dev`.
 *
 * Defensive about its input on purpose: `__BUILD_SHA__` is whatever a shell command
 * produced at build time, and the failure modes are an empty string (not a git tree),
 * a value with a trailing newline (a `git rev-parse` someone forgot to trim), and the
 * literal placeholder from a build that did not substitute at all. None of those
 * should reach the screen as-is, and none is worth a broken boot.
 */
export function buildTag(sha: string | undefined | null): string {
  const trimmed = (sha ?? "").trim().toLowerCase();
  // Hex only. Anything else is a branch name, a placeholder, or an error message that
  // happened to be captured, and none of them is a commit.
  if (!/^[0-9a-f]{4,40}$/.test(trimmed)) return NO_SHA_TAG;
  return `#${trimmed.slice(-TAG_DIGITS)}`;
}

/** The SHA this bundle was built from, as injected by the bundler. */
export function injectedSha(): string | undefined {
  // `typeof` rather than a bare reference: the define is present in every build and in
  // the Vitest config, but a consumer that imports this module through some other
  // toolchain would otherwise get a ReferenceError at import time rather than `#dev`.
  return typeof __BUILD_SHA__ === "string" ? __BUILD_SHA__ : undefined;
}

const STYLE = `
.sw-version {
  position: fixed; z-index: 7;
  right: calc(10px + env(safe-area-inset-right, 0px));
  bottom: calc(8px + env(safe-area-inset-bottom, 0px));
  font: 10px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.12em; color: #5d6b82;
  pointer-events: none; user-select: none; -webkit-user-select: none;
  text-shadow: 0 1px 2px rgba(0,0,0,0.8);
}
/* With the on-screen controls up, the bottom-right corner belongs to the 2×2 chip
   block — a tag under it would be behind BOOST. Lifted clear rather than hidden,
   because a phone tester is precisely who needs to be able to read the build id. */
.sw-version.touch { bottom: calc(${CHIP_BLOCK_HEIGHT + 4}px + env(safe-area-inset-bottom, 0px)); }
`;

export interface VersionTag {
  readonly root: HTMLElement;
  /** Lifts the tag clear of the touch chips when the on-screen controls are up. */
  setTouchActive(active: boolean): void;
  dispose(): void;
}

export function createVersionTag(
  parent: HTMLElement = document.body,
  sha: string | undefined = injectedSha(),
): VersionTag {
  const style = document.createElement("style");
  style.textContent = STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-version";
  root.dataset.version = "";
  root.textContent = buildTag(sha);
  // The full SHA on hover, for the one case where four digits are ambiguous. Not on
  // screen: the tag is meant to be ignorable.
  if (sha) root.title = `build ${sha}`;
  parent.appendChild(root);

  return {
    root,
    setTouchActive(active) {
      root.classList.toggle("touch", active);
    },
    dispose() {
      root.remove();
      style.remove();
    },
  };
}
