// Shakedown — the first level, and the one everybody has flown.
//
// Was `demo.ts`, exporting `DEMO_LEVEL` typed by an interface declared in the same
// file. It is a `LevelSpec` in a catalog now (PARITY step 1), and the rename is the
// point: "the demo level" stops being true the moment there are two. Not one line of
// its CONTENT changed with the move, so the level people have flown is the level they
// flew — only its shape and its name did.
//
// It is shaped to exercise the things worth looking at: a long sweeping curve (the
// rail-curvature carry), a climb and descent (the rotation-minimizing frame away from
// world-up), two waypoint stops — one that forces the tight forward cone, one omni stop
// where the pole can actually be crossed — and, at last, a FORK.
//
// The fork was flagged as missing after M1b, after M2 step 1 and after M2 step 2, and
// each time the note said the branch machinery was built and only the level authoring
// was outstanding. That turned out to be wrong: `chooseCourse` was never called by any
// system, so a fork here would have carried the party straight down course 0. The
// wiring landed with `sim/systems/forks.ts`; this is the content half.
//
// Enemies arrive as WAVES, and a wave past the fork names the branch it belongs to —
// so both routes now have their own encounter rather than the level going quiet after
// the split. That constraint used to be "keep every enemy short of the fork, enforced
// by a test"; the course dimension replaces it.

import type { LevelSpec } from "../schemas/level.js";

export const SHAKEDOWN: LevelSpec = {
  schemaVersion: 1,
  id: "level.shakedown",
  name: "Shakedown",
  // Halved from 34 after the first phone flight: everything arrived faster than it
  // could be read, and a rail shooter's difficulty should come from what is in front
  // of you rather than from how quickly it gets there. Only `app/main.ts` reads this —
  // every spec sets its own speed — so the change is contained to the shipped level.
  //
  // Worth knowing that this makes the rear-fire problem WORSE on its own, not better:
  // an enemy behind you stays inside its own fire range for twice as long. The fairness
  // gate in `systems/enemies.ts` is what actually fixes that, and the two landed
  // together for that reason.
  speed: 17,
  ambient: { ratePerSecond: 3.5, spread: 16, maxAlive: 60 },

  // Paced so each archetype gets a stretch of rail to itself before they mix, and so
  // each PATTERN is met once on its own: a pair, then a line, then a column arriving
  // one at a time, then a vee.
  waves: [
    { id: "wave.picket", enemy: "enemy.drone", count: 2, pattern: { kind: "line", spacing: 5 }, triggerS: 90, lead: 60 },
    { id: "wave.runner", enemy: "enemy.interceptor", count: 1, pattern: { kind: "line", spacing: 0 }, triggerS: 170, lead: 45 },
    { id: "wave.picket2", enemy: "enemy.drone", count: 3, pattern: { kind: "line", spacing: 4 }, triggerS: 210, lead: 55, oy: -1 },
    { id: "wave.charge", enemy: "enemy.lancer", count: 2, pattern: { kind: "column", spacing: 30 }, triggerS: 250, lead: 90 },
    // Past the destroy-two stop, where the player has had some practice.
    { id: "wave.escort", enemy: "enemy.interceptor", count: 3, pattern: { kind: "vee", spacing: 5 }, triggerS: 330, lead: 50 },
    { id: "wave.swarm", enemy: "enemy.drone", count: 5, pattern: { kind: "ring", radius: 7 }, triggerS: 390, lead: 60 },
    { id: "wave.lance", enemy: "enemy.lancer", count: 3, pattern: { kind: "column", spacing: 25 }, triggerS: 400, lead: 90 },

    // ── Past the fork (commit at ~517) ────────────────────────────────────────
    // Each names its branch, which is what makes them unambiguous: the same rail
    // distance is a different world point on each course. Deliberately different, so
    // the two routes are worth choosing between rather than reskins of each other.
    { id: "wave.high-gauntlet", enemy: "enemy.interceptor", count: 4, pattern: { kind: "vee", spacing: 6 }, triggerS: 580, lead: 60, course: "trunk" },
    { id: "wave.port-ambush", enemy: "enemy.drone", count: 6, pattern: { kind: "ring", radius: 8 }, triggerS: 600, lead: 55, course: "port" },
    { id: "wave.port-lance", enemy: "enemy.lancer", count: 2, pattern: { kind: "column", spacing: 30 }, triggerS: 680, lead: 80, course: "port" },
  ],

  rail: {
    box: { width: 8, height: 5 },
    waypoints: [
      { position: [0, 0, 0] },
      { position: [80, 0, 0] },
      // A sweeping right-hand curve — hands-off should track it, not lag it.
      { position: [160, 6, 40] },
      { position: [240, 10, 20] },
      // Destroy-two stop: forces the tight forward cone and spawns its own targets.
      {
        position: [300, 10, -20],
        stop: { mode: "forward", advance: { type: "destroyed", count: 2 }, burst: 5 },
      },
      { position: [370, 24, -60] },
      // A climb, well away from world-up, where a naive frame would degenerate.
      { position: [420, 60, -80] },
      // Omni stop: the full sphere, so the pole is reachable by pitching up.
      {
        position: [450, 90, -80],
        stop: { mode: "omni", advance: { type: "time", seconds: 6 } },
      },
      // ── The fork ──────────────────────────────────────────────────────────
      // Waypoint 8. The choice commits one segment earlier, at waypoint 7's arc
      // length (~517 units), where every course still has identical geometry — so the
      // rail bends toward the chosen path before it splits, telegraphing it the way
      // Star Fox does, with no sideways jerk. See Addendum 3.
      //
      // The two options diverge along the fork frame's BINORMAL, which is the axis
      // `steerX` slides the ship on and the axis `partyLateral` reads. A high/low
      // split would look dramatic and give the default selector almost nothing to go
      // on — the fork would resolve on rounding rather than on flying. A spec asserts
      // the two laterals have opposite signs.
      { position: [500, 110, -40] },
      // Starboard: the trunk swings out and stays high.
      { position: [596, 128, -36] },
      { position: [672, 112, 4] },
      { position: [730, 92, 44] },
    ],

    branches: [
      {
        id: "port",
        atWaypoint: 8,
        // Port: cuts inside and drops away. Shorter, so the two courses are not
        // interchangeable — there should be a reason to prefer one.
        waypoints: [
          { position: [524, 132, 52] },
          { position: [560, 112, 128] },
          { position: [612, 88, 180] },
        ],
      },
    ],
  },
};
