// The level catalog.
//
// Same shape as every other catalog here — a record keyed by id, plus an ORDER array
// that is the presentation sequence — and for the same reason: the record is how
// content is looked up and the order is what a menu renders. `content.test.ts` asserts
// the two agree, because a level in one and not the other is either a level nothing can
// load or a level nobody can pick.
//
// `DEFAULT_LEVEL` is what a run is built from when nothing says otherwise. It is
// deliberately a named export rather than `LEVEL_ORDER[0]`: reordering the presentation
// list should not silently change which level the game boots into.

import type { LevelSpec } from "../schemas/level.js";
import { SHAKEDOWN } from "./shakedown.js";
import { NARROWS } from "./narrows.js";

export { SHAKEDOWN } from "./shakedown.js";
export { NARROWS } from "./narrows.js";

export const LEVELS: Readonly<Record<string, LevelSpec>> = {
  [SHAKEDOWN.id]: SHAKEDOWN,
  [NARROWS.id]: NARROWS,
};

/** Presentation order. Shakedown first — it is the one that teaches the controls. */
export const LEVEL_ORDER: readonly LevelSpec[] = [SHAKEDOWN, NARROWS];

export const DEFAULT_LEVEL: LevelSpec = SHAKEDOWN;
