// Which level a URL asks for.
//
// The provisional seam, and it is worth saying so plainly: `?level=` is how the second
// level is reached until PARITY step 2 gives the game a record of what a player has
// completed and step 3 gives it somewhere to choose from. It mirrors `?difficulty=easy`
// and `?debug=1` — both of which exist for the same reason, that a build has to be
// steerable before it has a menu.
//
// It lives in `ui/` rather than in `content/` because reading a URL is not content's
// job, and it is pure so it can be specced without a browser — the same split
// `settingsStore.loadSettings(search)` already makes.

import { DEFAULT_LEVEL, LEVELS } from "@content/levels/index.js";
import type { LevelSpec } from "@content/schemas/level.js";

/**
 * The level named by `?level=`, or `DEFAULT_LEVEL`.
 *
 * An unknown id falls back rather than throwing. A query string is the one input a
 * player can typo, paste half of, or carry over from a build where that level existed —
 * and a white screen tells them nothing, where the wrong level is immediately obvious
 * and immediately fixable. The same argument the meta-save makes for dropping unknown
 * upgrade ids instead of rejecting the document.
 *
 * Both the bare id and the `level.` prefix are accepted, so `?level=narrows` works.
 * The prefix is a namespace, not a password.
 */
export function levelFromSearch(
  search: string,
  catalog: Readonly<Record<string, LevelSpec>> = LEVELS,
): LevelSpec {
  const requested = new URLSearchParams(search).get("level");
  if (requested === null) return DEFAULT_LEVEL;
  return lookup(catalog, requested) ?? lookup(catalog, `level.${requested}`) ?? DEFAULT_LEVEL;
}

/**
 * `catalog[id]`, but only for keys the catalog actually OWNS.
 *
 * The plain index would answer `?level=__proto__` with `Object.prototype` — truthy,
 * not a level, and returned in place of the fallback. That is not a hypothetical: the
 * spec caught it on the first run. Any lookup of an untrusted string in an object
 * literal has this hole, and a query string is as untrusted as input gets.
 */
function lookup(
  catalog: Readonly<Record<string, LevelSpec>>,
  id: string,
): LevelSpec | undefined {
  return Object.hasOwn(catalog, id) ? catalog[id] : undefined;
}
