// The title screen.
//
// Shown once the assets are in and before the first run starts. It exists for one
// concrete reason beyond looking like a game: difficulty has to be choosable BEFORE
// you fly, not only after you have died once. A picker that only appeared on the
// game-over screen would mean the first run of every session was always NORMAL.
//
// It is also where the debug menu is unlocked: ↑↑↓↓←→←→BA reveals a DEBUG button, the
// same gesture the old game used on its overworld. The unlock is raised as an event
// rather than acted on here — this screen knows how to reveal a button, and nothing
// about what is behind it.
//
// The simulation is already built and ticking behind this — `startGame` runs from the
// moment boot finishes, so `window.__sw` is available to the smoke and the console
// whether or not anyone has pressed PLAY. What the title gates is the player's
// attention, not the clock. That is a deliberate simplification: a paused-until-play
// world would need a pause concept in the fixed-step loop, which is M5's business.

import type { DifficultyDef } from "@content/difficulty/index.js";
import { createDifficultyPicker, type DifficultyPicker } from "./difficultyPicker.js";
import { createSettingsPanel, type SettingsPanel } from "./settingsPanel.js";
import { SequenceMatcher } from "./konami.js";
import type { StickSensitivity } from "./settingsStore.js";

const STYLE = `
.sw-title {
  position: fixed; inset: 0; z-index: 8;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  /* Tight enough that title + difficulty + two sliders + PLAY fit a 390px-tall
     phone in landscape, which is the shortest viewport this has to survive. */
  gap: 18px;
  background: radial-gradient(circle at 50% 45%, rgba(10,20,38,0.82), rgba(3,6,12,0.96));
  font: 13px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #cddcf0; user-select: none; -webkit-user-select: none;
  /* The whole screen takes input: it is a modal gate, and a stray tap landing on the
     game behind it would fire a shot into a run the player has not started yet. */
  pointer-events: auto; touch-action: manipulation;
}
.sw-title-name {
  font-size: 34px; letter-spacing: 0.34em; color: #ffd479;
  text-shadow: 0 2px 18px rgba(255,190,90,0.25);
  /* The letter-spacing pushes the text off-centre by one space's width. */
  text-indent: 0.34em;
}
.sw-title-tag { color: #7e8ea8; letter-spacing: 0.2em; font-size: 11px; }
.sw-title-play {
  pointer-events: auto;
  font: 600 16px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.24em; color: #eaf3ff;
  background: rgba(30,70,120,0.85); border: 1px solid #6fa2dd; border-radius: 11px;
  padding: 0 44px; min-height: 56px; min-width: 200px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  transition: background-color 100ms linear, transform 100ms ease-out;
}
.sw-title-play:hover { background: rgba(44,96,158,0.9); }
.sw-title-play:active { transform: scale(0.97); }
.sw-title-hint { color: #63728c; font-size: 11px; letter-spacing: 0.12em; }
/* Sized and placed like the debug button rather than like PLAY: it is a way OFF this
   screen into a panel, not the thing the screen is for, and PLAY has to stay the
   obvious target for a thumb. */
.sw-title-shop {
  pointer-events: auto;
  font: 600 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.2em; color: #7fd6a2;
  background: rgba(12,34,26,0.85); border: 1px solid #2f6b50; border-radius: 9px;
  padding: 0 20px; min-height: 44px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.sw-title-shop:hover { background: rgba(18,50,38,0.9); }
.sw-title-shop:active { transform: scale(0.97); }
/* Hidden until the code is entered, and it stays revealed on later visits because the
   unlock is stored. Sized like a real button rather than a link: it is pressed with a
   thumb on the device the tuning is being flown on. */
.sw-title-debug {
  pointer-events: auto;
  font: 600 12px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.2em; color: #ffd479;
  background: rgba(46,34,10,0.85); border: 1px solid #7a6330; border-radius: 9px;
  padding: 0 20px; min-height: 44px;
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
}
.sw-title-debug:hover { background: rgba(66,49,14,0.9); }
.sw-title-debug:active { transform: scale(0.97); }
.sw-title-debug.sw-title-hidden { display: none; }
`;

export interface TitleScreenOptions {
  readonly initialDifficulty: DifficultyDef;
  readonly initialSensitivity: StickSensitivity;
  /** Called as a slider moves. Applies live — no restart, no confirm. */
  readonly onSensitivityChange: (sensitivity: StickSensitivity) => void;
  /** Called when the player changes difficulty here. No confirm — there is no run yet. */
  readonly onDifficultyChange: (difficulty: DifficultyDef) => void;
  /** Called when PLAY is pressed. The screen removes itself first. */
  readonly onPlay: () => void;
  /**
   * Whether the debug button is already revealed — the code was entered in an earlier
   * session, or `?debug=1` is on the URL.
   */
  readonly debugUnlocked?: boolean;
  /** Called the first time the Konami code completes here. Persist it. */
  readonly onDebugUnlock?: () => void;
  /** Called when the DEBUG button is pressed. The title screen stays up. */
  readonly onDebug?: () => void;
  /**
   * Called when UPGRADES is pressed. The title screen stays up.
   *
   * Optional so a screen can be built without a shop — which is what every existing spec
   * does, and what the game itself did before there was one to open.
   */
  readonly onShop?: () => void;
}

export interface TitleScreen {
  readonly root: HTMLElement;
  /**
   * Shows or hides the stick-sensitivity sliders.
   *
   * Hidden on a keyboard, because that is all they scale. Driven by
   * `controls.onTouchActive` rather than by a sniff here, so the panel appears at the
   * same moment the stick it belongs to does.
   */
  setSensitivityVisible(visible: boolean): void;
  dispose(): void;
}

export function createTitleScreen(
  options: TitleScreenOptions,
  parent: HTMLElement = document.body,
): TitleScreen {
  const style = document.createElement("style");
  style.textContent = STYLE;
  document.head.appendChild(style);

  const root = document.createElement("div");
  root.className = "sw-title";

  const name = document.createElement("div");
  name.className = "sw-title-name";
  name.textContent = "SUN WEASEL";

  const tag = document.createElement("div");
  tag.className = "sw-title-tag";
  tag.textContent = "SHAKEDOWN";

  const picker: DifficultyPicker = createDifficultyPicker({
    initial: options.initialDifficulty,
    onChange: options.onDifficultyChange,
  });

  const settings: SettingsPanel = createSettingsPanel({
    initial: options.initialSensitivity,
    onChange: options.onSensitivityChange,
  });

  const play = document.createElement("button");
  play.type = "button";
  play.className = "sw-title-play";
  play.dataset.play = "";
  play.textContent = "PLAY";

  const hint = document.createElement("div");
  hint.className = "sw-title-hint";
  hint.textContent = "";

  // Only mounted when there is a shop to open. An UPGRADES button that did nothing
  // would be worse than none on the screen a new player meets first.
  const shop = document.createElement("button");
  shop.type = "button";
  shop.className = "sw-title-shop";
  shop.dataset.shopOpen = "";
  shop.textContent = "UPGRADES";

  const debug = document.createElement("button");
  debug.type = "button";
  debug.className = "sw-title-debug";
  debug.dataset.debug = "";
  debug.textContent = "DEBUG";
  // Revealed from the start when the code was entered in an earlier session — the
  // unlock is stored, so nobody has to re-enter it after every reload on a phone.
  debug.classList.toggle("sw-title-hidden", !options.debugUnlocked);

  root.append(name, tag, picker.root, settings.root, play);
  if (options.onShop) root.appendChild(shop);
  root.append(debug, hint);
  parent.appendChild(root);

  // ── The Konami code ─────────────────────────────────────────────────────────
  // Listened for on `window` rather than on the title root, because the root is a
  // div and never holds focus — a keydown would only arrive here if something inside
  // happened to be focused, which after a click on a slider is the slider.
  const konami = new SequenceMatcher();
  const onKeyDown = (event: KeyboardEvent) => {
    if (!konami.push(event.code)) return;
    debug.classList.remove("sw-title-hidden");
    options.onDebugUnlock?.();
  };
  window.addEventListener("keydown", onKeyDown);

  const onDebug = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    options.onDebug?.();
  };
  debug.addEventListener("click", onDebug);

  // Opens over the title rather than replacing it: what is bought applies to the next
  // run, so closing the shop should put the player back in front of PLAY.
  const onShop = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    options.onShop?.();
  };
  shop.addEventListener("click", onShop);

  let disposed = false;
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    window.removeEventListener("keydown", onKeyDown);
    debug.removeEventListener("click", onDebug);
    shop.removeEventListener("click", onShop);
    picker.dispose();
    settings.dispose();
    root.remove();
    style.remove();
  };

  const onPlay = (event: Event) => {
    event.preventDefault();
    event.stopPropagation();
    dispose();
    options.onPlay();
  };
  play.addEventListener("click", onPlay);

  return {
    root,
    setSensitivityVisible: (visible) => settings.setVisible(visible),
    dispose,
  };
}
